-- NRSV-CE OLD TESTAMENT BIBLE VERSES (PART 10)

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 1, 1, 'Happy are those  
    who do not follow the advice of the wicked,  
or take the path that sinners tread,  
    or sit in the seat of scoffers;', 'en', 'NRSV-CE', 'Psalm 1'),
(19, 'Maz', 'Psalms', 1, 2, 'but their delight is in the law of the LORD,  
    and on his law they meditate day and night.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 1, 3, 'They are like trees  
    planted by streams of water,  
which yield their fruit in its season,  
    and their leaves do not wither.  
In all that they do, they prosper.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 1, 4, 'The wicked are not so,  
    but are like chaff that the wind drives away.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 1, 5, 'Therefore the wicked will not stand in the judgment,  
    nor sinners in the congregation of the righteous;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 1, 6, 'for the LORD watches over the way of the righteous,  
    but the way of the wicked will perish.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 2, 1, 'Why do the nations conspire,  
    and the peoples plot in vain?', 'en', 'NRSV-CE', 'Psalm 2'),
(19, 'Maz', 'Psalms', 2, 2, 'The kings of the earth set themselves,  
    and the rulers take counsel together,  
    against the LORD and his anointed, saying,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 2, 3, '"Let us burst their bonds asunder,  
    and cast their cords from us."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 2, 4, 'He who sits in the heavens laughs;  
    the LORD has them in derision.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 2, 5, 'Then he will speak to them in his wrath,  
    and terrify them in his fury, saying,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 2, 6, '"I have set my king on Zion, my holy hill."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 2, 7, 'I will tell of the decree of the LORD:  
He said to me, "You are my son;  
    today I have begotten you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 2, 8, 'Ask of me, and I will make the nations your heritage,  
    and the ends of the earth your possession.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 2, 9, 'You shall break them with a rod of iron,  
    and dash them in pieces like a potter"s vessel."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 2, 10, 'Now therefore, O kings, be wise;  
    be warned, O rulers of the earth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 2, 11, 'Serve the LORD with fear,  
    with trembling', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 2, 12, 'kiss his feet,  
or he will be angry, and you will perish in the way;  
    for his wrath is quickly kindled.
Happy are all who take refuge in him.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 3, 1, 'O LORD, how many are my foes!  
    Many are rising against me;', 'en', 'NRSV-CE', 'Psalm 3'),
(19, 'Maz', 'Psalms', 3, 2, 'many are saying to me,  
    "There is no help for you in God."_Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 3, 3, 'But you, O LORD, are a shield around me,  
    my glory, and the one who lifts up my head.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 3, 4, 'I cry aloud to the LORD,  
    and he answers me from his holy hill._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 3, 5, 'I lie down and sleep;  
    I wake again, for the LORD sustains me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 3, 6, 'I am not afraid of ten thousands of people  
    who have set themselves against me all around.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 3, 7, 'Rise up, O LORD!  
    Deliver me, O my God!  
For you strike all my enemies on the cheek;  
    you break the teeth of the wicked.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 3, 8, 'Deliverance belongs to the LORD;  
    may your blessing be on your people!_Selah_', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 4, 1, 'Answer me when I call, O God of my right!  
    You gave me room when I was in distress.  
    Be gracious to me, and hear my prayer.', 'en', 'NRSV-CE', 'Psalm 4'),
(19, 'Maz', 'Psalms', 4, 2, 'How long, you people, shall my honor suffer shame?  
    How long will you love vain words, and seek after lies?_Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 4, 3, 'But know that the LORD has set apart the faithful for himself;  
    the LORD hears when I call to him.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 4, 4, 'When you are disturbed, do not sin;  
    ponder it on your beds, and be silent._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 4, 5, 'Offer right sacrifices,  
    and put your trust in the LORD.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 4, 6, 'There are many who say, "O that we might see some good!  
    Let the light of your face shine on us, O LORD!"', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 4, 7, 'You have put gladness in my heart  
    more than when their grain and wine abound.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 4, 8, 'I will both lie down and sleep in peace;  
    for you alone, O LORD, make me lie down in safety.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 5, 1, 'Give ear to my words, O LORD;  
    give heed to my sighing.', 'en', 'NRSV-CE', 'Psalm 5'),
(19, 'Maz', 'Psalms', 5, 2, 'Listen to the sound of my cry,  
    my King and my God,  
    for to you I pray.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 5, 3, 'O LORD, in the morning you hear my voice;  
    in the morning I plead my case to you, and watch.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 5, 4, 'For you are not a God who delights in wickedness;  
    evil will not sojourn with you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 5, 5, 'The boastful will not stand before your eyes;  
    you hate all evildoers.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 5, 6, 'You destroy those who speak lies;  
    the LORD abhors the bloodthirsty and deceitful.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 5, 7, 'But I, through the abundance of your steadfast love,  
    will enter your house,  
I will bow down toward your holy temple  
    in awe of you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 5, 8, 'Lead me, O LORD, in your righteousness  
    because of my enemies;  
    make your way straight before me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 5, 9, 'For there is no truth in their mouths;  
    their hearts are destruction;  
their throats are open graves;  
    they flatter with their tongues.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 5, 10, 'Make them bear their guilt, O God;  
    let them fall by their own counsels;  
because of their many transgressions cast them out,  
    for they have rebelled against you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 5, 11, 'But let all who take refuge in you rejoice;  
    let them ever sing for joy.  
Spread your protection over them,  
    so that those who love your name may exult in you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 5, 12, 'For you bless the righteous, O LORD;  
    you cover them with favor as with a shield.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 6, 1, 'O LORD, do not rebuke me in your anger,  
    or discipline me in your wrath.', 'en', 'NRSV-CE', 'Psalm 6'),
(19, 'Maz', 'Psalms', 6, 2, 'Be gracious to me, O LORD, for I am languishing;  
    O LORD, heal me, for my bones are shaking with terror.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 6, 3, 'My soul also is struck with terror,  
    while you, O LORD--how long?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 6, 4, 'Turn, O LORD, save my life;  
    deliver me for the sake of your steadfast love.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 6, 5, 'For in death there is no remembrance of you;  
    in Sheol who can give you praise?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 6, 6, 'I am weary with my moaning;  
    every night I flood my bed with tears;  
    I drench my couch with my weeping.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 6, 7, 'My eyes waste away because of grief;  
    they grow weak because of all my foes.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 6, 8, 'Depart from me, all you workers of evil,  
    for the LORD has heard the sound of my weeping.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 6, 9, 'The LORD has heard my supplication;  
    the LORD accepts my prayer.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 6, 10, 'All my enemies shall be ashamed and struck with terror;  
    they shall turn back, and in a moment be put to shame.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 7, 1, 'O LORD my God, in you I take refuge;  
    save me from all my pursuers, and deliver me,', 'en', 'NRSV-CE', 'Psalm 7'),
(19, 'Maz', 'Psalms', 7, 2, 'or like a lion they will tear me apart;  
    they will drag me away, with no one to rescue.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 7, 3, 'O LORD my God, if I have done this,  
    if there is wrong in my hands,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 7, 4, 'if I have repaid my ally with harm  
    or plundered my foe without cause,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 7, 5, 'then let the enemy pursue and overtake me,  
    trample my life to the ground,  
    and lay my soul in the dust._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 7, 6, 'Rise up, O LORD, in your anger;  
    lift yourself up against the fury of my enemies;  
    awake, O my God; you have appointed a judgment.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 7, 7, 'Let the assembly of the peoples be gathered around you,  
    and over it take your seat on high.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 7, 8, 'The LORD judges the peoples;  
    judge me, O LORD, according to my righteousness  
    and according to the integrity that is in me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 7, 9, 'O let the evil of the wicked come to an end,  
    but establish the righteous,  
you who test the minds and hearts,  
    O righteous God.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 7, 10, 'God is my shield,  
    who saves the upright in heart.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 7, 11, 'God is a righteous judge,  
    and a God who has indignation every day.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 7, 12, 'If one does not repent, God will whet his sword;  
    he has bent and strung his bow;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 7, 13, 'he has prepared his deadly weapons,  
    making his arrows fiery shafts.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 7, 14, 'See how they conceive evil,  
    and are pregnant with mischief,  
    and bring forth lies.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 7, 15, 'They make a pit, digging it out,  
    and fall into the hole that they have made.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 7, 16, 'Their mischief returns upon their own heads,  
    and on their own heads their violence descends.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 7, 17, 'I will give to the LORD the thanks due to his righteousness,  
    and sing praise to the name of the LORD, the Most High.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 8, 1, 'O LORD, our Sovereign,  
    how majestic is your name in all the earth!
You have set your glory above the heavens.', 'en', 'NRSV-CE', 'Psalm 8'),
(19, 'Maz', 'Psalms', 8, 2, 'Out of the mouths of babes and infants  
you have founded a bulwark because of your foes,  
    to silence the enemy and the avenger.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 8, 3, 'When I look at your heavens, the work of your fingers,  
    the moon and the stars that you have established;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 8, 4, 'what are human beings that you are mindful of them,  
    mortals that you care for them?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 8, 5, 'Yet you have made them a little lower than God,  
    and crowned them with glory and honor.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 8, 6, 'You have given them dominion over the works of your hands;  
    you have put all things under their feet,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 8, 7, 'all sheep and oxen,  
    and also the beasts of the field,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 8, 8, 'the birds of the air, and the fish of the sea,  
    whatever passes along the paths of the seas.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 8, 9, 'O LORD, our Sovereign,  
    how majestic is your name in all the earth!', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 9, 1, 'I will give thanks to the LORD with my whole heart;  
    I will tell of all your wonderful deeds.', 'en', 'NRSV-CE', 'Psalm 9'),
(19, 'Maz', 'Psalms', 9, 2, 'I will be glad and exult in you;  
    I will sing praise to your name, O Most High.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 9, 3, 'When my enemies turned back,  
    they stumbled and perished before you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 9, 4, 'For you have maintained my just cause;  
    you have sat on the throne giving righteous judgment.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 9, 5, 'You have rebuked the nations, you have destroyed the wicked;  
    you have blotted out their name forever and ever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 9, 6, 'The enemies have vanished in everlasting ruins;  
    their cities you have rooted out;  
    the very memory of them has perished.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 9, 7, 'But the LORD sits enthroned forever,  
    he has established his throne for judgment.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 9, 8, 'He judges the world with righteousness;  
    he judges the peoples with equity.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 9, 9, 'The LORD is a stronghold for the oppressed,  
    a stronghold in times of trouble.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 9, 10, 'And those who know your name put their trust in you,  
    for you, O LORD, have not forsaken those who seek you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 9, 11, 'Sing praises to the LORD, who dwells in Zion.  
    Declare his deeds among the peoples.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 9, 12, 'For he who avenges blood is mindful of them;  
    he does not forget the cry of the afflicted.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 9, 13, 'Be gracious to me, O LORD.  
    See what I suffer from those who hate me;  
    you are the one who lifts me up from the gates of death,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 9, 14, 'so that I may recount all your praises,  
    and, in the gates of daughter Zion,  
    rejoice in your deliverance.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 9, 15, 'The nations have sunk in the pit that they made;  
    in the net that they hid has their own foot been caught.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 9, 16, 'The LORD has made himself known, he has executed judgment;  
    the wicked are snared in the work of their own hands._Higgaion. Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 9, 17, 'The wicked shall depart to Sheol,  
    all the nations that forget God.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 9, 18, 'For the needy shall not always be forgotten,  
    nor the hope of the poor perish forever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 9, 19, 'Rise up, O LORD! Do not let mortals prevail;  
    let the nations be judged before you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 9, 20, 'Put them in fear, O LORD;  
    let the nations know that they are only human._Selah_', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 10, 1, 'Why, O LORD, do you stand far off?  
    Why do you hide yourself in times of trouble?', 'en', 'NRSV-CE', 'Psalm 10'),
(19, 'Maz', 'Psalms', 10, 2, 'In arrogance the wicked persecute the poor--  
    let them be caught in the schemes they have devised.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 10, 3, 'For the wicked boast of the desires of their heart,  
    those greedy for gain curse and renounce the LORD.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 10, 4, 'In the pride of their countenance the wicked say, "God will not seek it out";  
    all their thoughts are, "There is no God."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 10, 5, 'Their ways prosper at all times;  
    your judgments are on high, out of their sight;  
    as for their foes, they scoff at them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 10, 6, 'They think in their heart, "We shall not be moved;  
    throughout all generations we shall not meet adversity."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 10, 7, 'Their mouths are filled with cursing and deceit and oppression;  
    under their tongues are mischief and iniquity.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 10, 8, 'They sit in ambush in the villages;  
    in hiding places they murder the innocent.
Their eyes stealthily watch for the helpless;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 10, 9, 'they lurk in secret like a lion in its covert;  
they lurk that they may seize the poor;  
    they seize the poor and drag them off in their net.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 10, 10, 'They stoop, they crouch,  
    and the helpless fall by their might.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 10, 11, 'They think in their heart, "God has forgotten,  
    he has hidden his face, he will never see it."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 10, 12, 'Rise up, O LORD; O God, lift up your hand;  
    do not forget the oppressed.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 10, 13, 'Why do the wicked renounce God,  
    and say in their hearts, "You will not call us to account"?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 10, 14, 'But you do see! Indeed you note trouble and grief,  
    that you may take it into your hands;  
the helpless commit themselves to you;  
    you have been the helper of the orphan.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 10, 15, 'Break the arm of the wicked and evildoers;  
    seek out their wickedness until you find none.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 10, 16, 'The LORD is king forever and ever;  
    the nations shall perish from his land.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 10, 17, 'O LORD, you will hear the desire of the meek;  
    you will strengthen their heart, you will incline your ear', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 10, 18, 'to do justice for the orphan and the oppressed,  
    so that those from earth may strike terror no more.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 11, 1, 'In the LORD I take refuge; how can you say to me,  
    "Flee like a bird to the mountains;', 'en', 'NRSV-CE', 'Psalm 11'),
(19, 'Maz', 'Psalms', 11, 2, 'for look, the wicked bend the bow,  
    they have fitted their arrow to the string,  
    to shoot in the dark at the upright in heart.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 11, 3, 'If the foundations are destroyed,  
    what can the righteous do?"', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 11, 4, 'The LORD is in his holy temple;  
    the LORD"s throne is in heaven.  
    His eyes behold, his gaze examines humankind.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 11, 5, 'The LORD tests the righteous and the wicked,  
    and his soul hates the lover of violence.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 11, 6, 'On the wicked he will rain coals of fire and sulfur;  
    a scorching wind shall be the portion of their cup.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 11, 7, 'For the LORD is righteous;  
he loves righteous deeds;  
    the upright shall behold his face.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 12, 1, 'Help, O LORD, for there is no longer anyone who is godly;  
    the faithful have disappeared from humankind.', 'en', 'NRSV-CE', 'Psalm 12'),
(19, 'Maz', 'Psalms', 12, 2, 'They utter lies to each other;  
    with flattering lips and a double heart they speak.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 12, 3, 'May the LORD cut off all flattering lips,  
    the tongue that makes great boasts,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 12, 4, 'those who say, "With our tongues we will prevail;  
    our lips are our own--who is our master?"', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 12, 5, '"Because the poor are despoiled, because the needy groan,  
    I will now rise up," says the LORD;  
    "I will place them in the safety for which they long."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 12, 6, 'The promises of the LORD are promises that are pure,  
    silver refined in a furnace on the ground,  
    purified seven times.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 12, 7, 'You, O LORD, will protect us;  
    you will guard us from this generation forever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 12, 8, 'On every side the wicked prowl,  
    as vileness is exalted among humankind.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 13, 1, 'How long, O LORD? Will you forget me forever?  
    How long will you hide your face from me?', 'en', 'NRSV-CE', 'Psalm 13'),
(19, 'Maz', 'Psalms', 13, 2, 'How long must I bear pain in my soul,  
    and have sorrow in my heart all day long?  
How long shall my enemy be exalted over me?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 13, 3, 'Consider and answer me, O LORD my God!  
    Give light to my eyes, or I will sleep the sleep of death,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 13, 4, 'and my enemy will say, "I have prevailed";  
    my foes will rejoice because I am shaken.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 13, 5, 'But I trusted in your steadfast love;  
    my heart shall rejoice in your salvation.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 13, 6, 'I will sing to the LORD,  
    because he has dealt bountifully with me.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 14, 1, 'Fools say in their hearts, "There is no God."  
    They are corrupt, they do abominable deeds;  
    there is no one who does good.', 'en', 'NRSV-CE', 'Psalm 14'),
(19, 'Maz', 'Psalms', 14, 2, 'The LORD looks down from heaven on humankind  
    to see if there are any who are wise,  
    who seek after God.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 14, 3, 'They have all gone astray, they are all alike perverse;  
    there is no one who does good,  
    no, not one.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 14, 4, 'Have they no knowledge, all the evildoers  
    who eat up my people as they eat bread,  
    and do not call upon the LORD?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 14, 5, 'There they shall be in great terror,  
    for God is with the company of the righteous.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 14, 6, 'You would confound the plans of the poor,  
    but the LORD is their refuge.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 14, 7, 'O that deliverance for Israel would come from Zion!  
    When the LORD restores the fortunes of his people,  
    Jacob will rejoice; Israel will be glad.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 15, 1, 'O LORD, who may abide in your tent?  
    Who may dwell on your holy hill?', 'en', 'NRSV-CE', 'Psalm 15'),
(19, 'Maz', 'Psalms', 15, 2, 'Those who walk blamelessly, and do what is right,  
    and speak the truth from their heart;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 15, 3, 'who do not slander with their tongue,  
    and do no evil to their friends,  
    nor take up a reproach against their neighbors;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 15, 4, 'in whose eyes the wicked are despised,  
    but who honor those who fear the LORD;  
who stand by their oath even to their hurt;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 15, 5, 'who do not lend money at interest,  
    and do not take a bribe against the innocent.
Those who do these things shall never be moved.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 16, 1, 'Protect me, O God, for in you I take refuge.', 'en', 'NRSV-CE', 'Psalm 16'),
(19, 'Maz', 'Psalms', 16, 2, 'I say to the LORD, "You are my Lord;  
    I have no good apart from you."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 16, 3, 'As for the holy ones in the land, they are the noble,  
    in whom is all my delight.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 16, 4, 'Those who choose another god multiply their sorrows;  
    their drink offerings of blood I will not pour out  
    or take their names upon my lips.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 16, 5, 'The LORD is my chosen portion and my cup;  
    you hold my lot.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 16, 6, 'The boundary lines have fallen for me in pleasant places;  
    I have a goodly heritage.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 16, 7, 'I bless the LORD who gives me counsel;  
    in the night also my heart instructs me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 16, 8, 'I keep the LORD always before me;  
    because he is at my right hand, I shall not be moved.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 16, 9, 'Therefore my heart is glad, and my soul rejoices;  
    my body also rests secure.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 16, 10, 'For you do not give me up to Sheol,  
    or let your faithful one see the Pit.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 16, 11, 'You show me the path of life.  
    In your presence there is fullness of joy;  
    in your right hand are pleasures forevermore.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 17, 1, 'Hear a just cause, O LORD; attend to my cry;  
    give ear to my prayer from lips free of deceit.', 'en', 'NRSV-CE', 'Psalm 17'),
(19, 'Maz', 'Psalms', 17, 2, 'From you let my vindication come;  
    let your eyes see the right.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 17, 3, 'If you try my heart, if you visit me by night,  
    if you test me, you will find no wickedness in me;  
    my mouth does not transgress.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 17, 4, 'As for what others do, by the word of your lips  
    I have avoided the ways of the violent.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 17, 5, 'My steps have held fast to your paths;  
    my feet have not slipped.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 17, 6, 'I call upon you, for you will answer me, O God;  
    incline your ear to me, hear my words.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 17, 7, 'Wondrously show your steadfast love,  
    O savior of those who seek refuge  
    from their adversaries at your right hand.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 17, 8, 'Guard me as the apple of the eye;  
    hide me in the shadow of your wings,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 17, 9, 'from the wicked who despoil me,  
    my deadly enemies who surround me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 17, 10, 'They close their hearts to pity;  
    with their mouths they speak arrogantly.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 17, 11, 'They track me down; now they surround me;  
    they set their eyes to cast me to the ground.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 17, 12, 'They are like a lion eager to tear,  
    like a young lion lurking in ambush.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 17, 13, 'Rise up, O LORD, confront them, overthrow them!  
    By your sword deliver my life from the wicked,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 17, 14, 'from mortals--by your hand, O LORD--  
    from mortals whose portion in life is in this world.  
May their bellies be filled with what you have stored up for them;  
    may their children have more than enough;  
    may they leave something over to their little ones.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 17, 15, 'As for me, I shall behold your face in righteousness;  
    when I awake I shall be satisfied, beholding your likeness.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 18, 1, 'I love you, O LORD, my strength.', 'en', 'NRSV-CE', 'Psalm 18'),
(19, 'Maz', 'Psalms', 18, 2, 'The LORD is my rock, my fortress, and my deliverer,  
    my God, my rock in whom I take refuge,  
    my shield, and the horn of my salvation, my stronghold.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 3, 'I call upon the LORD, who is worthy to be praised,  
    so I shall be saved from my enemies.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 4, 'The cords of death encompassed me;  
    the torrents of perdition assailed me;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 5, 'the cords of Sheol entangled me;  
    the snares of death confronted me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 6, 'In my distress I called upon the LORD;  
    to my God I cried for help.  
From his temple he heard my voice,  
    and my cry to him reached his ears.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 7, 'Then the earth reeled and rocked;  
    the foundations also of the mountains trembled  
    and quaked, because he was angry.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 8, 'Smoke went up from his nostrils,  
    and devouring fire from his mouth;  
    glowing coals flamed forth from him.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 9, 'He bowed the heavens, and came down;  
    thick darkness was under his feet.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 10, 'He rode on a cherub, and flew;  
    he came swiftly upon the wings of the wind.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 11, 'He made darkness his covering around him,  
    his canopy thick clouds dark with water.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 12, 'Out of the brightness before him  
    there broke through his clouds  
    hailstones and coals of fire.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 13, 'The LORD also thundered in the heavens,  
    and the Most High uttered his voice.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 14, 'And he sent out his arrows, and scattered them;  
    he flashed forth lightnings, and routed them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 15, 'Then the channels of the sea were seen,  
    and the foundations of the world were laid bare  
at your rebuke, O LORD,  
    at the blast of the breath of your nostrils.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 16, 'He reached down from on high, he took me;  
    he drew me out of mighty waters.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 17, 'He delivered me from my strong enemy,  
    and from those who hated me;  
    for they were too mighty for me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 18, 'They confronted me in the day of my calamity;  
    but the LORD was my support.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 19, 'He brought me out into a broad place;  
    he delivered me, because he delighted in me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 20, 'The LORD rewarded me according to my righteousness;  
    according to the cleanness of my hands he recompensed me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 21, 'For I have kept the ways of the LORD,  
    and have not wickedly departed from my God.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 22, 'For all his ordinances were before me,  
    and his statutes I did not put away from me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 23, 'I was blameless before him,  
    and I kept myself from guilt.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 24, 'Therefore the LORD has recompensed me according to my righteousness,  
    according to the cleanness of my hands in his sight.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 25, 'With the loyal you show yourself loyal;  
    with the blameless you show yourself blameless;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 26, 'with the pure you show yourself pure;  
    and with the crooked you show yourself perverse.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 27, 'For you deliver a humble people,  
    but the haughty eyes you bring down.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 28, 'It is you who light my lamp;  
    the LORD, my God, lights up my darkness.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 29, 'By you I can crush a troop,  
    and by my God I can leap over a wall.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 30, 'This God--his way is perfect;  
    the promise of the LORD proves true;  
    he is a shield for all who take refuge in him.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 31, 'For who is God except the LORD?  
    And who is a rock besides our God?--', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 32, 'the God who girded me with strength,  
    and made my way safe.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 33, 'He made my feet like the feet of a deer,  
    and set me secure on the heights.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 34, 'He trains my hands for war,  
    so that my arms can bend a bow of bronze.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 35, 'You have given me the shield of your salvation,  
    and your right hand has supported me;  
    your help has made me great.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 36, 'You gave me a wide place for my steps under me,  
    and my feet did not slip.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 37, 'I pursued my enemies and overtook them;  
    and did not turn back until they were consumed.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 38, 'I struck them down, so that they were not able to rise;  
    they fell under my feet.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 39, 'For you girded me with strength for the battle;  
    you made my assailants sink under me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 40, 'You made my enemies turn their backs to me,  
    and those who hated me I destroyed.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 41, 'They cried for help, but there was no one to save them;  
    they cried to the LORD, but he did not answer them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 42, 'I beat them fine, like dust before the wind;  
    I cast them out like the mire of the streets.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 43, 'You delivered me from strife with the peoples;  
    you made me head of the nations;  
    people whom I had not known served me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 44, 'As soon as they heard of me they obeyed me;  
    foreigners came cringing to me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 45, 'Foreigners lost heart,  
    and came trembling out of their strongholds.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 46, 'The LORD lives! Blessed be my rock,  
    and exalted be the God of my salvation,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 47, 'the God who gave me vengeance  
    and subdued peoples under me;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 48, 'who delivered me from my enemies;  
    indeed, you exalted me above my adversaries;  
    you delivered me from the violent.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 49, 'For this I will extol you, O LORD, among the nations,  
    and sing praises to your name.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 18, 50, 'Great triumphs he gives to his king,  
    and shows steadfast love to his anointed,  
    to David and his descendants forever.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 19, 1, 'The heavens are telling the glory of God;  
    and the firmament proclaims his handiwork.', 'en', 'NRSV-CE', 'Psalm 19'),
(19, 'Maz', 'Psalms', 19, 2, 'Day to day pours forth speech,  
    and night to night declares knowledge.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 19, 3, 'There is no speech, nor are there words;  
    their voice is not heard;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 19, 4, 'yet their voice goes out through all the earth,  
    and their words to the end of the world.
In the heavens he has set a tent for the sun,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 19, 5, 'which comes out like a bridegroom from his wedding canopy,  
    and like a strong man runs its course with joy.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 19, 6, 'Its rising is from the end of the heavens,  
    and its circuit to the end of them;  
    and nothing is hid from its heat.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 19, 7, 'The law of the LORD is perfect,  
    reviving the soul;  
the decrees of the LORD are sure,  
    making wise the simple;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 19, 8, 'the precepts of the LORD are right,  
    rejoicing the heart;  
the commandment of the LORD is clear,  
    enlightening the eyes;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 19, 9, 'the fear of the LORD is pure,  
    enduring forever;  
the ordinances of the LORD are true  
    and righteous altogether.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 19, 10, 'More to be desired are they than gold,  
    even much fine gold;  
sweeter also than honey,  
    and drippings of the honeycomb.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 19, 11, 'Moreover by them is your servant warned;  
    in keeping them there is great reward.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 19, 12, 'But who can detect their errors?  
    Clear me from hidden faults.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 19, 13, 'Keep back your servant also from the insolent;  
    do not let them have dominion over me.  
Then I shall be blameless,  
    and innocent of great transgression.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 19, 14, 'Let the words of my mouth and the meditation of my heart  
    be acceptable to you,  
    O LORD, my rock and my redeemer.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 20, 1, 'The LORD answer you in the day of trouble!  
    The name of the God of Jacob protect you!', 'en', 'NRSV-CE', 'Psalm 20'),
(19, 'Maz', 'Psalms', 20, 2, 'May he send you help from the sanctuary,  
    and give you support from Zion.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 20, 3, 'May he remember all your offerings,  
    and regard with favor your burnt sacrifices._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 20, 4, 'May he grant you your heart"s desire,  
    and fulfill all your plans.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 20, 5, 'May we shout for joy over your victory,  
    and in the name of our God set up our banners.  
May the LORD fulfill all your petitions.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 20, 6, 'Now I know that the LORD will help his anointed;  
    he will answer him from his holy heaven  
    with mighty victories by his right hand.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 20, 7, 'Some take pride in chariots, and some in horses,  
    but our pride is in the name of the LORD our God.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 20, 8, 'They will collapse and fall,  
    but we shall rise and stand upright.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 20, 9, 'Give victory to the king, O LORD;  
    answer us when we call.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 21, 1, 'In your strength the king rejoices, O LORD,  
    and in your help how greatly he exults!', 'en', 'NRSV-CE', 'Psalm 21'),
(19, 'Maz', 'Psalms', 21, 2, 'You have given him his heart"s desire,  
    and have not withheld the request of his lips._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 21, 3, 'For you meet him with rich blessings;  
    you set a crown of fine gold on his head.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 21, 4, 'He asked you for life; you gave it to him--  
    length of days forever and ever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 21, 5, 'His glory is great through your help;  
    splendor and majesty you bestow on him.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 21, 6, 'You bestow on him blessings forever;  
    you make him glad with the joy of your presence.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 21, 7, 'For the king trusts in the LORD,  
    and through the steadfast love of the Most High he shall not be moved.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 21, 8, 'Your hand will find out all your enemies;  
    your right hand will find out those who hate you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 21, 9, 'You will make them like a fiery furnace  
    when you appear.  
The LORD will swallow them up in his wrath,  
    and fire will consume them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 21, 10, 'You will destroy their offspring from the earth,  
    and their children from among humankind.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 21, 11, 'If they plan evil against you,  
    if they devise mischief, they will not succeed.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 21, 12, 'For you will put them to flight;  
    you will aim at their faces with your bows.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 21, 13, 'Be exalted, O LORD, in your strength!  
    We will sing and praise your power.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 22, 1, 'My God, my God, why have you forsaken me?  
    Why are you so far from helping me, from the words of my groaning?', 'en', 'NRSV-CE', 'Psalm 22'),
(19, 'Maz', 'Psalms', 22, 2, 'O my God, I cry by day, but you do not answer;  
    and by night, but find no rest.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 3, 'Yet you are holy,  
    enthroned on the praises of Israel.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 4, 'In you our ancestors trusted;  
    they trusted, and you delivered them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 5, 'To you they cried, and were saved;  
    in you they trusted, and were not put to shame.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 6, 'But I am a worm, and not human;  
    scorned by others, and despised by the people.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 7, 'All who see me mock at me;  
    they make mouths at me, they shake their heads;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 8, '"Commit your cause to the LORD; let him deliver--  
    let him rescue the one in whom he delights!"', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 9, 'Yet it was you who took me from the womb;  
    you kept me safe on my mother"s breast.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 10, 'On you I was cast from my birth,  
    and since my mother bore me you have been my God.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 11, 'Do not be far from me,  
    for trouble is near  
    and there is no one to help.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 12, 'Many bulls encircle me,  
    strong bulls of Bashan surround me;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 13, 'they open wide their mouths at me,  
    like a ravening and roaring lion.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 14, 'I am poured out like water,  
    and all my bones are out of joint;  
my heart is like wax;  
    it is melted within my breast;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 15, 'my mouth is dried up like a potsherd,  
    and my tongue sticks to my jaws;  
    you lay me in the dust of death.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 16, 'For dogs are all around me;  
    a company of evildoers encircles me.  
My hands and feet have shriveled;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 17, 'I can count all my bones.  
They stare and gloat over me;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 18, 'they divide my clothes among themselves,  
    and for my clothing they cast lots.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 19, 'But you, O LORD, do not be far away!  
    O my help, come quickly to my aid!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 20, 'Deliver my soul from the sword,  
    my life from the power of the dog!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 21, 'Save me from the mouth of the lion!
From the horns of the wild oxen you have rescued me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 22, 'I will tell of your name to my brothers and sisters;  
    in the midst of the congregation I will praise you:', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 23, 'You who fear the LORD, praise him!  
    All you offspring of Jacob, glorify him;  
    stand in awe of him, all you offspring of Israel!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 24, 'For he did not despise or abhor  
    the affliction of the afflicted;  
he did not hide his face from me,  
    but heard when I cried to him.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 25, 'From you comes my praise in the great congregation;  
    my vows I will pay before those who fear him.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 26, 'The poor shall eat and be satisfied;  
    those who seek him shall praise the LORD.  
    May your hearts live forever!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 27, 'All the ends of the earth shall remember  
    and turn to the LORD;  
and all the families of the nations  
    shall worship before him.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 28, 'For dominion belongs to the LORD,  
    and he rules over the nations.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 29, 'To him, indeed, shall all who sleep in the earth bow down;  
    before him shall bow all who go down to the dust,  
    and I shall live for him.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 30, 'Posterity will serve him;  
    future generations will be told about the Lord,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 22, 31, 'and proclaim his deliverance to a people yet unborn,  
    saying that he has done it.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 23, 1, 'The LORD is my shepherd, I shall not want.', 'en', 'NRSV-CE', 'Psalm 23'),
(19, 'Maz', 'Psalms', 23, 2, 'He makes me lie down in green pastures;  
he leads me beside still waters;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 23, 3, 'he restores my soul.  
He leads me in right paths  
    for his name"s sake.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 23, 4, 'Even though I walk through the darkest valley,  
    I fear no evil;  
for you are with me;  
    your rod and your staff--  
    they comfort me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 23, 5, 'You prepare a table before me  
    in the presence of my enemies;  
you anoint my head with oil;  
    my cup overflows.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 23, 6, 'Surely goodness and mercy shall follow me  
    all the days of my life,  
and I shall dwell in the house of the LORD  
    my whole life long.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 24, 1, 'The earth is the LORD"s and all that is in it,  
    the world, and those who live in it;', 'en', 'NRSV-CE', 'Psalm 24'),
(19, 'Maz', 'Psalms', 24, 2, 'for he has founded it on the seas,  
    and established it on the rivers.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 24, 3, 'Who shall ascend the hill of the LORD?  
    And who shall stand in his holy place?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 24, 4, 'Those who have clean hands and pure hearts,  
    who do not lift up their souls to what is false,  
    and do not swear deceitfully.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 24, 5, 'They will receive blessing from the LORD,  
    and vindication from the God of their salvation.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 24, 6, 'Such is the company of those who seek him,  
    who seek the face of the God of Jacob._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 24, 7, 'Lift up your heads, O gates!  
    and be lifted up, O ancient doors!  
    that the King of glory may come in.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 24, 8, 'Who is the King of glory?  
    The LORD, strong and mighty,  
    the LORD, mighty in battle.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 24, 9, 'Lift up your heads, O gates!  
    and be lifted up, O ancient doors!  
    that the King of glory may come in.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 24, 10, 'Who is this King of glory?  
    The LORD of hosts,  
    he is the King of glory._Selah_', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 25, 1, 'To you, O LORD, I lift up my soul.', 'en', 'NRSV-CE', 'Psalm 25'),
(19, 'Maz', 'Psalms', 25, 2, 'O my God, in you I trust;  
    do not let me be put to shame;  
    do not let my enemies exult over me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 25, 3, 'Do not let those who wait for you be put to shame;  
    let them be ashamed who are wantonly treacherous.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 25, 4, 'Make me to know your ways, O LORD;  
    teach me your paths.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 25, 5, 'Lead me in your truth, and teach me,  
    for you are the God of my salvation;  
    for you I wait all day long.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 25, 6, 'Be mindful of your mercy, O LORD, and of your steadfast love,  
    for they have been from of old.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 25, 7, 'Do not remember the sins of my youth or my transgressions;  
    according to your steadfast love remember me,  
    for your goodness" sake, O LORD!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 25, 8, 'Good and upright is the LORD;  
    therefore he instructs sinners in the way.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 25, 9, 'He leads the humble in what is right,  
    and teaches the humble his way.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 25, 10, 'All the paths of the LORD are steadfast love and faithfulness,  
    for those who keep his covenant and his decrees.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 25, 11, 'For your name"s sake, O LORD,  
    pardon my guilt, for it is great.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 25, 12, 'Who are they that fear the LORD?  
    He will teach them the way that they should choose.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 25, 13, 'They will abide in prosperity,  
    and their children shall possess the land.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 25, 14, 'The friendship of the LORD is for those who fear him,  
    and he makes his covenant known to them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 25, 15, 'My eyes are ever toward the LORD,  
    for he will pluck my feet out of the net.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 25, 16, 'Turn to me and be gracious to me,  
    for I am lonely and afflicted.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 25, 17, 'Relieve the troubles of my heart,  
    and bring me out of my distress.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 25, 18, 'Consider my affliction and my trouble,  
    and forgive all my sins.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 25, 19, 'Consider how many are my foes,  
    and with what violent hatred they hate me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 25, 20, 'O guard my life, and deliver me;  
    do not let me be put to shame, for I take refuge in you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 25, 21, 'May integrity and uprightness preserve me,  
    for I wait for you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 25, 22, 'Redeem Israel, O God,  
    out of all its troubles.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 26, 1, 'Vindicate me, O LORD,  
    for I have walked in my integrity,  
    and I have trusted in the LORD without wavering.', 'en', 'NRSV-CE', 'Psalm 26'),
(19, 'Maz', 'Psalms', 26, 2, 'Prove me, O LORD, and try me;  
    test my heart and mind.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 26, 3, 'For your steadfast love is before my eyes,  
    and I walk in faithfulness to you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 26, 4, 'I do not sit with the worthless,  
    nor do I consort with hypocrites;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 26, 5, 'I hate the company of evildoers,  
    and will not sit with the wicked.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 26, 6, 'I wash my hands in innocence,  
    and go around your altar, O LORD,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 26, 7, 'singing aloud a song of thanksgiving,  
    and telling all your wondrous deeds.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 26, 8, 'O LORD, I love the house in which you dwell,  
    and the place where your glory abides.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 26, 9, 'Do not sweep me away with sinners,  
    nor my life with the bloodthirsty,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 26, 10, 'those in whose hands are evil devices,  
    and whose right hands are full of bribes.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 26, 11, 'But as for me, I walk in my integrity;  
    redeem me, and be gracious to me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 26, 12, 'My foot stands on level ground;  
    in the great congregation I will bless the LORD.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 27, 1, 'The LORD is my light and my salvation;  
    whom shall I fear?  
The LORD is the stronghold of my life;  
    of whom shall I be afraid?', 'en', 'NRSV-CE', 'Psalm 27'),
(19, 'Maz', 'Psalms', 27, 2, 'When evildoers assail me  
    to devour my flesh--  
my adversaries and foes--  
    they shall stumble and fall.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 27, 3, 'Though an army encamp against me,  
    my heart shall not fear;  
though war rise up against me,  
    yet I will be confident.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 27, 4, 'One thing I asked of the LORD,  
    that will I seek after:  
to live in the house of the LORD  
    all the days of my life,  
to behold the beauty of the LORD,  
    and to inquire in his temple.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 27, 5, 'For he will hide me in his shelter  
    in the day of trouble;  
he will conceal me under the cover of his tent;  
    he will set me high on a rock.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 27, 6, 'Now my head is lifted up  
    above my enemies all around me,  
and I will offer in his tent  
    sacrifices with shouts of joy;  
I will sing and make melody to the LORD.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 27, 7, 'Hear, O LORD, when I cry aloud,  
    be gracious to me and answer me!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 27, 8, '"Come," my heart says, "seek his face!"  
    Your face, LORD, do I seek.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 27, 9, 'Do not hide your face from me.
Do not turn your servant away in anger,  
    you who have been my help.  
Do not cast me off, do not forsake me,  
    O God of my salvation!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 27, 10, 'If my father and mother forsake me,  
    the LORD will take me up.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 27, 11, 'Teach me your way, O LORD,  
    and lead me on a level path  
    because of my enemies.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 27, 12, 'Do not give me up to the will of my adversaries,  
    for false witnesses have risen against me,  
    and they are breathing out violence.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 27, 13, 'I believe that I shall see the goodness of the LORD  
    in the land of the living.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 27, 14, 'Wait for the LORD;  
    be strong, and let your heart take courage;  
    wait for the LORD!', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 28, 1, 'To you, O LORD, I call;  
    my rock, do not refuse to hear me,  
for if you are silent to me,  
    I shall be like those who go down to the Pit.', 'en', 'NRSV-CE', 'Psalm 28'),
(19, 'Maz', 'Psalms', 28, 2, 'Hear the voice of my supplication,  
    as I cry to you for help,  
as I lift up my hands  
    toward your most holy sanctuary.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 28, 3, 'Do not drag me away with the wicked,  
    with those who are workers of evil,  
who speak peace with their neighbors,  
    while mischief is in their hearts.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 28, 4, 'Repay them according to their work,  
    and according to the evil of their deeds;  
repay them according to the work of their hands;  
    render them their due reward.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 28, 5, 'Because they do not regard the works of the LORD,  
    or the work of his hands,  
he will break them down and build them up no more.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 28, 6, 'Blessed be the LORD,  
    for he has heard the sound of my pleadings.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 28, 7, 'The LORD is my strength and my shield;  
    in him my heart trusts;  
so I am helped, and my heart exults,  
    and with my song I give thanks to him.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 28, 8, 'The LORD is the strength of his people;  
    he is the saving refuge of his anointed.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 28, 9, 'O save your people, and bless your heritage;  
    be their shepherd, and carry them forever.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 29, 1, 'Ascribe to the LORD, O heavenly beings,  
    ascribe to the LORD glory and strength.', 'en', 'NRSV-CE', 'Psalm 29'),
(19, 'Maz', 'Psalms', 29, 2, 'Ascribe to the LORD the glory of his name;  
    worship the LORD in holy splendor.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 29, 3, 'The voice of the LORD is over the waters;  
    the God of glory thunders,  
    the LORD, over mighty waters.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 29, 4, 'The voice of the LORD is powerful;  
    the voice of the LORD is full of majesty.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 29, 5, 'The voice of the LORD breaks the cedars;  
    the LORD breaks the cedars of Lebanon.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 29, 6, 'He makes Lebanon skip like a calf,  
    and Sirion like a young wild ox.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 29, 7, 'The voice of the LORD flashes forth flames of fire.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 29, 8, 'The voice of the LORD shakes the wilderness;  
    the LORD shakes the wilderness of Kadesh.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 29, 9, 'The voice of the LORD causes the oaks to whirl,  
    and strips the forest bare;  
    and in his temple all say, "Glory!"', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 29, 10, 'The LORD sits enthroned over the flood;  
    the LORD sits enthroned as king forever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 29, 11, 'May the LORD give strength to his people!  
    May the LORD bless his people with peace!', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 30, 1, 'I will extol you, O LORD, for you have drawn me up,  
    and did not let my foes rejoice over me.', 'en', 'NRSV-CE', 'Psalm 30'),
(19, 'Maz', 'Psalms', 30, 2, 'O LORD my God, I cried to you for help,  
    and you have healed me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 30, 3, 'O LORD, you brought up my soul from Sheol,  
    restored me to life from among those gone down to the Pit.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 30, 4, 'Sing praises to the LORD, O you his faithful ones,  
    and give thanks to his holy name.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 30, 5, 'For his anger is but for a moment;  
    his favor is for a lifetime.  
Weeping may linger for the night,  
    but joy comes with the morning.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 30, 6, 'As for me, I said in my prosperity,  
    "I shall never be moved."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 30, 7, 'By your favor, O LORD,  
    you had established me as a strong mountain;  
you hid your face;  
    I was dismayed.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 30, 8, 'To you, O LORD, I cried,  
    and to the LORD I made supplication:', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 30, 9, '"What profit is there in my death,  
    if I go down to the Pit?  
Will the dust praise you?  
    Will it tell of your faithfulness?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 30, 10, 'Hear, O LORD, and be gracious to me!  
    O LORD, be my helper!"', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 30, 11, 'You have turned my mourning into dancing;  
    you have taken off my sackcloth  
    and clothed me with joy,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 30, 12, 'so that my soul may praise you and not be silent.  
    O LORD my God, I will give thanks to you forever.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 31, 1, 'In you, O LORD, I seek refuge;  
    do not let me ever be put to shame;  
    in your righteousness deliver me.', 'en', 'NRSV-CE', 'Psalm 31'),
(19, 'Maz', 'Psalms', 31, 2, 'Incline your ear to me;  
    rescue me speedily.  
Be a rock of refuge for me,  
    a strong fortress to save me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 31, 3, 'You are indeed my rock and my fortress;  
    for your name"s sake lead me and guide me,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 31, 4, 'take me out of the net that is hidden for me,  
    for you are my refuge.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 31, 5, 'Into your hand I commit my spirit;  
    you have redeemed me, O LORD, faithful God.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 31, 6, 'You hate those who pay regard to worthless idols,  
    but I trust in the LORD.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 31, 7, 'I will exult and rejoice in your steadfast love,  
    because you have seen my affliction;  
    you have taken heed of my adversities,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 31, 8, 'and have not delivered me into the hand of the enemy;  
    you have set my feet in a broad place.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 31, 9, 'Be gracious to me, O LORD, for I am in distress;  
    my eye wastes away from grief,  
    my soul and body also.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 31, 10, 'For my life is spent with sorrow,  
    and my years with sighing;  
my strength fails because of my misery,  
    and my bones waste away.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 31, 11, 'I am the scorn of all my adversaries,  
    a horror to my neighbors,  
an object of dread to my acquaintances;  
    those who see me in the street flee from me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 31, 12, 'I have passed out of mind like one who is dead;  
    I have become like a broken vessel.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 31, 13, 'For I hear the whispering of many--  
    terror all around!--  
as they scheme together against me,  
    as they plot to take my life.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 31, 14, 'But I trust in you, O LORD;  
    I say, "You are my God."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 31, 15, 'My times are in your hand;  
    deliver me from the hand of my enemies and persecutors.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 31, 16, 'Let your face shine upon your servant;  
    save me in your steadfast love.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 31, 17, 'Do not let me be put to shame, O LORD,  
    for I call on you;  
let the wicked be put to shame;  
    let them go dumbfounded to Sheol.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 31, 18, 'Let the lying lips be stilled  
    that speak insolently against the righteous  
    with pride and contempt.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 31, 19, 'O how abundant is your goodness  
    that you have laid up for those who fear you,  
and accomplished for those who take refuge in you,  
    in the sight of everyone!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 31, 20, 'In the shelter of your presence you hide them  
    from human plots;  
you hold them safe under your shelter  
    from contentious tongues.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 31, 21, 'Blessed be the LORD,  
    for he has wondrously shown his steadfast love to me  
    when I was beset as a city under siege.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 31, 22, 'I had said in my alarm,  
    "I am driven far from your sight."  
But you heard my supplications  
    when I cried out to you for help.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 31, 23, 'Love the LORD, all you his saints.  
    The LORD preserves the faithful,  
    but abundantly repays the one who acts haughtily.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 31, 24, 'Be strong, and let your heart take courage,  
    all you who wait for the LORD.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 32, 1, 'Happy are those whose transgression is forgiven,  
    whose sin is covered.', 'en', 'NRSV-CE', 'Psalm 32'),
(19, 'Maz', 'Psalms', 32, 2, 'Happy are those to whom the LORD imputes no iniquity,  
    and in whose spirit there is no deceit.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 32, 3, 'While I kept silence, my body wasted away  
    through my groaning all day long.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 32, 4, 'For day and night your hand was heavy upon me;  
    my strength was dried up as by the heat of summer._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 32, 5, 'Then I acknowledged my sin to you,  
    and I did not hide my iniquity;  
I said, "I will confess my transgressions to the LORD,"  
    and you forgave the guilt of my sin._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 32, 6, 'Therefore let all who are faithful  
    offer prayer to you;  
at a time of distress, the rush of mighty waters  
    shall not reach them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 32, 7, 'You are a hiding place for me;  
    you preserve me from trouble;  
    you surround me with glad cries of deliverance._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 32, 8, 'I will instruct you and teach you the way you should go;  
    I will counsel you with my eye upon you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 32, 9, 'Do not be like a horse or a mule, without understanding,  
    whose temper must be curbed with bit and bridle,  
    else it will not stay near you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 32, 10, 'Many are the torments of the wicked,  
    but steadfast love surrounds those who trust in the LORD.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 32, 11, 'Be glad in the LORD and rejoice, O righteous,  
    and shout for joy, all you upright in heart.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 33, 1, 'Rejoice in the LORD, O you righteous.  
    Praise befits the upright.', 'en', 'NRSV-CE', 'Psalm 33'),
(19, 'Maz', 'Psalms', 33, 2, 'Praise the LORD with the lyre;  
    make melody to him with the harp of ten strings.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 33, 3, 'Sing to him a new song;  
    play skillfully on the strings, with loud shouts.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 33, 4, 'For the word of the LORD is upright,  
    and all his work is done in faithfulness.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 33, 5, 'He loves righteousness and justice;  
    the earth is full of the steadfast love of the LORD.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 33, 6, 'By the word of the LORD the heavens were made,  
    and all their host by the breath of his mouth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 33, 7, 'He gathered the waters of the sea as in a bottle;  
    he put the deeps in storehouses.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 33, 8, 'Let all the earth fear the LORD;  
    let all the inhabitants of the world stand in awe of him.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 33, 9, 'For he spoke, and it came to be;  
    he commanded, and it stood firm.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 33, 10, 'The LORD brings the counsel of the nations to nothing;  
    he frustrates the plans of the peoples.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 33, 11, 'The counsel of the LORD stands forever,  
    the thoughts of his heart to all generations.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 33, 12, 'Happy is the nation whose God is the LORD,  
    the people whom he has chosen as his heritage.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 33, 13, 'The LORD looks down from heaven;  
    he sees all humankind.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 33, 14, 'From where he sits enthroned he watches  
    all the inhabitants of the earth--', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 33, 15, 'he who fashions the hearts of them all,  
    and observes all their deeds.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 33, 16, 'A king is not saved by his great army;  
    a warrior is not delivered by his great strength.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 33, 17, 'The war horse is a vain hope for victory,  
    and by its great might it cannot save.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 33, 18, 'Truly the eye of the LORD is on those who fear him,  
    on those who hope in his steadfast love,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 33, 19, 'to deliver their soul from death,  
    and to keep them alive in famine.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 33, 20, 'Our soul waits for the LORD;  
    he is our help and shield.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 33, 21, 'Our heart is glad in him,  
    because we trust in his holy name.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 33, 22, 'Let your steadfast love, O LORD, be upon us,  
    even as we hope in you.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 34, 1, 'I will bless the LORD at all times;  
    his praise shall continually be in my mouth.', 'en', 'NRSV-CE', 'Psalm 34'),
(19, 'Maz', 'Psalms', 34, 2, 'My soul makes its boast in the LORD;  
    let the humble hear and be glad.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 34, 3, 'O magnify the LORD with me,  
    and let us exalt his name together.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 34, 4, 'I sought the LORD, and he answered me,  
    and delivered me from all my fears.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 34, 5, 'Look to him, and be radiant;  
    so your faces shall never be ashamed.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 34, 6, 'This poor soul cried, and was heard by the LORD,  
    and was saved from every trouble.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 34, 7, 'The angel of the LORD encamps  
    around those who fear him, and delivers them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 34, 8, 'O taste and see that the LORD is good;  
    happy are those who take refuge in him.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 34, 9, 'O fear the LORD, you his holy ones,  
    for those who fear him have no want.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 34, 10, 'The young lions suffer want and hunger,  
    but those who seek the LORD lack no good thing.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 34, 11, 'Come, O children, listen to me;  
    I will teach you the fear of the LORD.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 34, 12, 'Which of you desires life,  
    and covets many days to enjoy good?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 34, 13, 'Keep your tongue from evil,  
    and your lips from speaking deceit.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 34, 14, 'Depart from evil, and do good;  
    seek peace, and pursue it.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 34, 15, 'The eyes of the LORD are on the righteous,  
    and his ears are open to their cry.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 34, 16, 'The face of the LORD is against evildoers,  
    to cut off the remembrance of them from the earth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 34, 17, 'When the righteous cry for help, the LORD hears,  
    and rescues them from all their troubles.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 34, 18, 'The LORD is near to the brokenhearted,  
    and saves the crushed in spirit.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 34, 19, 'Many are the afflictions of the righteous,  
    but the LORD rescues them from them all.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 34, 20, 'He keeps all their bones;  
    not one of them will be broken.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 34, 21, 'Evil brings death to the wicked,  
    and those who hate the righteous will be condemned.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 34, 22, 'The LORD redeems the life of his servants;  
    none of those who take refuge in him will be condemned.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 35, 1, 'Contend, O LORD, with those who contend with me;  
    fight against those who fight against me!', 'en', 'NRSV-CE', 'Psalm 35'),
(19, 'Maz', 'Psalms', 35, 2, 'Take hold of shield and buckler,  
    and rise up to help me!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 35, 3, 'Draw the spear and javelin  
    against my pursuers;  
say to my soul,  
    "I am your salvation."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 35, 4, 'Let them be put to shame and dishonor  
    who seek after my life.  
Let them be turned back and confounded  
    who devise evil against me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 35, 5, 'Let them be like chaff before the wind,  
    with the angel of the LORD driving them on.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 35, 6, 'Let their way be dark and slippery,  
    with the angel of the LORD pursuing them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 35, 7, 'For without cause they hid their net for me;  
    without cause they dug a pit for my life.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 35, 8, 'Let ruin come on them unawares.  
And let the net that they hid ensnare them;  
    let them fall in it--to their ruin.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 35, 9, 'Then my soul shall rejoice in the LORD,  
    exulting in his deliverance.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 35, 10, 'All my bones shall say,  
    "O LORD, who is like you?  
You deliver the weak  
    from those too strong for them,  
    the weak and needy from those who despoil them."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 35, 11, 'Malicious witnesses rise up;  
    they ask me about things I do not know.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 35, 12, 'They repay me evil for good;  
    my soul is forlorn.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 35, 13, 'But as for me, when they were sick,  
    I wore sackcloth;  
    I afflicted myself with fasting.  
I prayed with head bowed on my bosom,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 35, 14, 'as though I grieved for a friend or a brother;  
I went about as one who laments for a mother,  
    bowed down and in mourning.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 35, 15, 'But at my stumbling they gathered in glee,  
    they gathered together against me;  
ruffians whom I did not know  
    tore at me without ceasing;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 35, 16, 'they impiously mocked more and more,  
    gnashing at me with their teeth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 35, 17, 'How long, O LORD, will you look on?  
    Rescue me from their ravages,  
    my life from the lions!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 35, 18, 'Then I will thank you in the great congregation;  
    in the mighty throng I will praise you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 35, 19, 'Do not let my treacherous enemies rejoice over me,  
    or those who hate me without cause wink the eye.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 35, 20, 'For they do not speak peace,  
    but they conceive deceitful words  
    against those who are quiet in the land.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 35, 21, 'They open wide their mouths against me;  
    they say, "Aha, Aha,  
    our eyes have seen it."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 35, 22, 'You have seen, O LORD; do not be silent!  
    O Lord, do not be far from me!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 35, 23, 'Wake up! Bestir yourself for my defense,  
    for my cause, my God and my Lord!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 35, 24, 'Vindicate me, O LORD, my God,  
    according to your righteousness,  
    and do not let them rejoice over me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 35, 25, 'Do not let them say to themselves,  
    "Aha, we have our heart"s desire."  
Do not let them say, "We have swallowed you up."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 35, 26, 'Let all those who rejoice at my calamity  
    be put to shame and confusion;  
let those who exalt themselves against me  
    be clothed with shame and dishonor.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 35, 27, 'Let those who desire my vindication  
    shout for joy and be glad,  
    and say evermore,  
"Great is the LORD,  
    who delights in the welfare of his servant."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 35, 28, 'Then my tongue shall tell of your righteousness  
    and of your praise all day long.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 36, 1, 'Transgression speaks to the wicked  
    deep in their hearts;  
there is no fear of God  
    before their eyes.', 'en', 'NRSV-CE', 'Psalm 36'),
(19, 'Maz', 'Psalms', 36, 2, 'For they flatter themselves in their own eyes  
    that their iniquity cannot be found out and hated.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 36, 3, 'The words of their mouths are mischief and deceit;  
    they have ceased to act wisely and do good.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 36, 4, 'They plot mischief while on their beds;  
    they are set on a way that is not good;  
    they do not reject evil.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 36, 5, 'Your steadfast love, O LORD, extends to the heavens,  
    your faithfulness to the clouds.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 36, 6, 'Your righteousness is like the mighty mountains,  
    your judgments are like the great deep;  
    you save humans and animals alike, O LORD.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 36, 7, 'How precious is your steadfast love, O God!  
    All people may take refuge in the shadow of your wings.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 36, 8, 'They feast on the abundance of your house,  
    and you give them drink from the river of your delights.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 36, 9, 'For with you is the fountain of life;  
    in your light we see light.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 36, 10, 'O continue your steadfast love to those who know you,  
    and your salvation to the upright of heart!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 36, 11, 'Do not let the foot of the arrogant tread on me,  
    or the hand of the wicked drive me away.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 36, 12, 'There the evildoers lie prostrate;  
    they are thrust down, unable to rise.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 37, 1, 'Do not fret because of the wicked;  
    do not be envious of wrongdoers,', 'en', 'NRSV-CE', 'Psalm 37'),
(19, 'Maz', 'Psalms', 37, 2, 'for they will soon fade like the grass,  
    and wither like the green herb.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 3, 'Trust in the LORD, and do good;  
    so you will live in the land, and enjoy security.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 4, 'Take delight in the LORD,  
    and he will give you the desires of your heart.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 5, 'Commit your way to the LORD;  
    trust in him, and he will act.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 6, 'He will make your vindication shine like the light,  
    and the justice of your cause like the noonday.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 7, 'Be still before the LORD, and wait patiently for him;  
    do not fret over those who prosper in their way,  
    over those who carry out evil devices.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 8, 'Refrain from anger, and forsake wrath.  
    Do not fret--it leads only to evil.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 9, 'For the wicked shall be cut off,  
    but those who wait for the LORD shall inherit the land.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 10, 'Yet a little while, and the wicked will be no more;  
    though you look diligently for their place, they will not be there.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 11, 'But the meek shall inherit the land,  
    and delight themselves in abundant prosperity.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 12, 'The wicked plot against the righteous,  
    and gnash their teeth at them;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 13, 'but the LORD laughs at the wicked,  
    for he sees that their day is coming.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 14, 'The wicked draw the sword and bend their bows  
    to bring down the poor and needy,  
    to kill those who walk uprightly;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 15, 'their sword shall enter their own heart,  
    and their bows shall be broken.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 16, 'Better is a little that the righteous person has  
    than the abundance of many wicked.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 17, 'For the arms of the wicked shall be broken,  
    but the LORD upholds the righteous.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 18, 'The LORD knows the days of the blameless,  
    and their heritage will abide forever;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 19, 'they are not put to shame in evil times,  
    in the days of famine they have abundance.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 20, 'But the wicked perish,  
    and the enemies of the LORD are like the glory of the pastures;  
    they vanish--like smoke they vanish away.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 21, 'The wicked borrow, and do not pay back,  
    but the righteous are generous and keep giving;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 22, 'for those blessed by the LORD shall inherit the land,  
    but those cursed by him shall be cut off.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 23, 'Our steps are made firm by the LORD,  
    when he delights in our way;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 24, 'though we stumble, we shall not fall headlong,  
    for the LORD holds us by the hand.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 25, 'I have been young, and now am old,  
    yet I have not seen the righteous forsaken  
    or their children begging bread.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 26, 'They are ever giving liberally and lending,  
    and their children become a blessing.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 27, 'Depart from evil, and do good;  
    so you shall abide forever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 28, 'For the LORD loves justice;  
    he will not forsake his faithful ones.
The righteous shall be kept safe forever,  
    but the children of the wicked shall be cut off.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 29, 'The righteous shall inherit the land,  
    and live in it forever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 30, 'The mouths of the righteous utter wisdom,  
    and their tongues speak justice.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 31, 'The law of their God is in their hearts;  
    their steps do not slip.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 32, 'The wicked watch for the righteous,  
    and seek to kill them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 33, 'The LORD will not abandon them to their power,  
    or let them be condemned when they are brought to trial.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 34, 'Wait for the LORD, and keep to his way,  
    and he will exalt you to inherit the land;  
    you will look on the destruction of the wicked.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 35, 'I have seen the wicked oppressing,  
    and towering like a cedar of Lebanon.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 36, 'Again I passed by, and they were no more;  
    though I sought them, they could not be found.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 37, 'Mark the blameless, and behold the upright,  
    for there is posterity for the peaceable.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 38, 'But transgressors shall be altogether destroyed;  
    the posterity of the wicked shall be cut off.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 39, 'The salvation of the righteous is from the LORD;  
    he is their refuge in the time of trouble.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 37, 40, 'The LORD helps them and rescues them;  
    he rescues them from the wicked, and saves them,  
    because they take refuge in him.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 38, 1, 'O LORD, do not rebuke me in your anger,  
    or discipline me in your wrath.', 'en', 'NRSV-CE', 'Psalm 38'),
(19, 'Maz', 'Psalms', 38, 2, 'For your arrows have sunk into me,  
    and your hand has come down on me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 38, 3, 'There is no soundness in my flesh  
    because of your indignation;  
there is no health in my bones  
    because of my sin.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 38, 4, 'For my iniquities have gone over my head;  
    they weigh like a burden too heavy for me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 38, 5, 'My wounds grow foul and fester  
    because of my foolishness;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 38, 6, 'I am utterly bowed down and prostrate;  
    all day long I go around mourning.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 38, 7, 'For my loins are filled with burning,  
    and there is no soundness in my flesh.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 38, 8, 'I am utterly spent and crushed;  
    I groan because of the tumult of my heart.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 38, 9, 'O Lord, all my longing is known to you;  
    my sighing is not hidden from you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 38, 10, 'My heart throbs, my strength fails me;  
    as for the light of my eyes--it also has gone from me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 38, 11, 'My friends and companions stand aloof from my affliction,  
    and my neighbors stand far off.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 38, 12, 'Those who seek my life lay their snares;  
    those who seek to hurt me speak of ruin,  
    and meditate treachery all day long.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 38, 13, 'But I am like the deaf, I do not hear;  
    like the mute, who cannot speak.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 38, 14, 'Truly, I am like one who does not hear,  
    and in whose mouth is no retort.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 38, 15, 'But it is for you, O LORD, that I wait;  
    it is you, O Lord my God, who will answer.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 38, 16, 'For I pray, "Only do not let them rejoice over me,  
    those who boast against me when my foot slips."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 38, 17, 'For I am ready to fall,  
    and my pain is ever with me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 38, 18, 'I confess my iniquity;  
    I am sorry for my sin.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 38, 19, 'Those who are my foes without cause are mighty,  
    and many are those who hate me wrongfully.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 38, 20, 'Those who render me evil for good  
    are my adversaries because I follow after good.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 38, 21, 'Do not forsake me, O LORD;  
    O my God, do not be far from me;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 38, 22, 'make haste to help me,  
    O Lord, my salvation.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 39, 1, 'I said, "I will guard my ways  
    that I may not sin with my tongue;  
I will keep a muzzle on my mouth  
    as long as the wicked are in my presence."', 'en', 'NRSV-CE', 'Psalm 39'),
(19, 'Maz', 'Psalms', 39, 2, 'I was silent and still;  
    I held my peace to no avail;  
my distress grew worse,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 39, 3, 'my heart became hot within me.  
While I mused, the fire burned;  
    then I spoke with my tongue:', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 39, 4, '"LORD, let me know my end,  
    and what is the measure of my days;  
    let me know how fleeting my life is.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 39, 5, 'You have made my days a few handbreadths,  
    and my lifetime is as nothing in your sight.  
Surely everyone stands as a mere breath._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 39, 6, 'Surely everyone goes about like a shadow.  
Surely for nothing they are in turmoil;  
    they heap up, and do not know who will gather.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 39, 7, '"And now, O Lord, what do I wait for?  
    My hope is in you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 39, 8, 'Deliver me from all my transgressions.  
    Do not make me the scorn of the fool.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 39, 9, 'I am silent; I do not open my mouth,  
    for it is you who have done it.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 39, 10, 'Remove your stroke from me;  
    I am worn down by the blows of your hand.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 39, 11, '"You chastise mortals  
    in punishment for sin,  
consuming like a moth what is dear to them;  
    surely everyone is a mere breath._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 39, 12, '"Hear my prayer, O LORD,  
    and give ear to my cry;  
    do not hold your peace at my tears.  
For I am your passing guest,  
    an alien, like all my forebears.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 39, 13, 'Turn your gaze away from me, that I may smile again,  
    before I depart and am no more."', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 40, 1, 'I waited patiently for the LORD;  
    he inclined to me and heard my cry.', 'en', 'NRSV-CE', 'Psalm 40'),
(19, 'Maz', 'Psalms', 40, 2, 'He drew me up from the desolate pit,  
    out of the miry bog,  
and set my feet upon a rock,  
    making my steps secure.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 40, 3, 'He put a new song in my mouth,  
    a song of praise to our God.  
Many will see and fear,  
    and put their trust in the LORD.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 40, 4, 'Happy are those who make  
    the LORD their trust,  
who do not turn to the proud,  
    to those who go astray after false gods.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 40, 5, 'You have multiplied, O LORD my God,  
    your wondrous deeds and your thoughts toward us;  
    none can compare with you.  
Were I to proclaim and tell of them,  
    they would be more than can be counted.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 40, 6, 'Sacrifice and offering you do not desire,  
    but you have given me an open ear.  
Burnt offering and sin offering  
    you have not required.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 40, 7, 'Then I said, "Here I am;  
    in the scroll of the book it is written of me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 40, 8, 'I delight to do your will, O my God;  
    your law is within my heart."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 40, 9, 'I have told the glad news of deliverance  
    in the great congregation;  
see, I have not restrained my lips,  
    as you know, O LORD.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 40, 10, 'I have not hidden your saving help within my heart,  
    I have spoken of your faithfulness and your salvation;  
I have not concealed your steadfast love and your faithfulness  
    from the great congregation.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 40, 11, 'Do not, O LORD, withhold  
    your mercy from me;  
let your steadfast love and your faithfulness  
    keep me safe forever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 40, 12, 'For evils have encompassed me  
    without number;  
my iniquities have overtaken me,  
    until I cannot see;  
they are more than the hairs of my head,  
    and my heart fails me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 40, 13, 'Be pleased, O LORD, to deliver me;  
    O LORD, make haste to help me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 40, 14, 'Let all those be put to shame and confusion  
    who seek to snatch away my life;  
let those be turned back and brought to dishonor  
    who desire my hurt.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 40, 15, 'Let those be appalled because of their shame  
    who say to me, "Aha, Aha!"', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 40, 16, 'But may all who seek you  
    rejoice and be glad in you;  
may those who love your salvation  
    say continually, "Great is the LORD!"', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 40, 17, 'As for me, I am poor and needy,  
    but the Lord takes thought for me.  
You are my help and my deliverer;  
    do not delay, O my God.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 41, 1, 'Happy are those who consider the poor;  
    the LORD delivers them in the day of trouble.', 'en', 'NRSV-CE', 'Psalm 41'),
(19, 'Maz', 'Psalms', 41, 2, 'The LORD protects them and keeps them alive;  
    they are called happy in the land.  
    You do not give them up to the will of their enemies.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 41, 3, 'The LORD sustains them on their sickbed;  
    in their illness you heal all their infirmities.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 41, 4, 'As for me, I said, "O LORD, be gracious to me;  
    heal me, for I have sinned against you."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 41, 5, 'My enemies wonder in malice  
    when I will die, and my name perish.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 41, 6, 'And when they come to see me, they utter empty words,  
    while their hearts gather mischief;  
    when they go out, they tell it abroad.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 41, 7, 'All who hate me whisper together about me;  
    they imagine the worst for me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 41, 8, 'They think that a deadly thing has fastened on me,  
    that I will not rise again from where I lie.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 41, 9, 'Even my bosom friend in whom I trusted,  
    who ate of my bread, has lifted the heel against me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 41, 10, 'But you, O LORD, be gracious to me,  
    and raise me up, that I may repay them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 41, 11, 'By this I know that you are pleased with me;  
    because my enemy has not triumphed over me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 41, 12, 'But you have upheld me because of my integrity,  
    and set me in your presence forever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 41, 13, 'Blessed be the LORD, the God of Israel,  
    from everlasting to everlasting.  
Amen and Amen.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 42, 1, 'As a deer longs for flowing streams,  
    so my soul longs for you, O God.', 'en', 'NRSV-CE', 'Psalm 42'),
(19, 'Maz', 'Psalms', 42, 2, 'My soul thirsts for God,  
    for the living God.  
When shall I come and behold  
    the face of God?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 42, 3, 'My tears have been my food  
    day and night,  
while people say to me continually,  
    "Where is your God?"', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 42, 4, 'These things I remember,  
    as I pour out my soul:  
how I went with the throng,  
    and led them in procession to the house of God,  
with glad shouts and songs of thanksgiving,  
    a multitude keeping festival.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 42, 5, 'Why are you cast down, O my soul,  
    and why are you disquieted within me?  
Hope in God; for I shall again praise him,  
    my help', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 42, 6, 'and my God.
My soul is cast down within me;  
    therefore I remember you  
from the land of Jordan and of Hermon,  
    from Mount Mizar.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 42, 7, 'Deep calls to deep  
    at the thunder of your cataracts;  
all your waves and your billows  
    have gone over me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 42, 8, 'By day the LORD commands his steadfast love,  
    and at night his song is with me,  
    a prayer to the God of my life.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 42, 9, 'I say to God, my rock,  
    "Why have you forgotten me?  
Why must I walk about mournfully  
    because the enemy oppresses me?"', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 42, 10, 'As with a deadly wound in my body,  
    my adversaries taunt me,  
while they say to me continually,  
    "Where is your God?"', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 42, 11, 'Why are you cast down, O my soul,  
    and why are you disquieted within me?  
Hope in God; for I shall again praise him,  
    my help and my God.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 43, 1, 'Vindicate me, O God, and defend my cause  
    against an ungodly people;  
from those who are deceitful and unjust  
    deliver me!', 'en', 'NRSV-CE', 'Psalm 43'),
(19, 'Maz', 'Psalms', 43, 2, 'For you are the God in whom I take refuge;  
    why have you cast me off?  
Why must I walk about mournfully  
    because of the oppression of the enemy?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 43, 3, 'O send out your light and your truth;  
    let them lead me;  
let them bring me to your holy hill  
    and to your dwelling.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 43, 4, 'Then I will go to the altar of God,  
    to God my exceeding joy;  
and I will praise you with the harp,  
    O God, my God.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 43, 5, 'Why are you cast down, O my soul,  
    and why are you disquieted within me?  
Hope in God; for I shall again praise him,  
    my help and my God.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 44, 1, 'We have heard with our ears, O God,  
    our ancestors have told us,  
what deeds you performed in their days,  
    in the days of old:', 'en', 'NRSV-CE', 'Psalm 44'),
(19, 'Maz', 'Psalms', 44, 2, 'you with your own hand drove out the nations,  
    but them you planted;  
you afflicted the peoples,  
    but them you set free;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 44, 3, 'for not by their own sword did they win the land,  
    nor did their own arm give them victory;  
but your right hand, and your arm,  
    and the light of your countenance,  
    for you delighted in them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 44, 4, 'You are my King and my God;  
    you command victories for Jacob.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 44, 5, 'Through you we push down our foes;  
    through your name we tread down our assailants.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 44, 6, 'For not in my bow do I trust,  
    nor can my sword save me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 44, 7, 'But you have saved us from our foes,  
    and have put to confusion those who hate us.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 44, 8, 'In God we have boasted continually,  
    and we will give thanks to your name forever._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 44, 9, 'Yet you have rejected us and abased us,  
    and have not gone out with our armies.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 44, 10, 'You made us turn back from the foe,  
    and our enemies have gotten spoil.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 44, 11, 'You have made us like sheep for slaughter,  
    and have scattered us among the nations.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 44, 12, 'You have sold your people for a trifle,  
    demanding no high price for them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 44, 13, 'You have made us the taunt of our neighbors,  
    the derision and scorn of those around us.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 44, 14, 'You have made us a byword among the nations,  
    a laughingstock among the peoples.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 44, 15, 'All day long my disgrace is before me,  
    and shame has covered my face', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 44, 16, 'at the words of the taunters and revilers,  
    at the sight of the enemy and the avenger.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 44, 17, 'All this has come upon us,  
    yet we have not forgotten you,  
    or been false to your covenant.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 44, 18, 'Our heart has not turned back,  
    nor have our steps departed from your way,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 44, 19, 'yet you have broken us in the haunt of jackals,  
    and covered us with deep darkness.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 44, 20, 'If we had forgotten the name of our God,  
    or spread out our hands to a strange god,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 44, 21, 'would not God discover this?  
    For he knows the secrets of the heart.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 44, 22, 'Because of you we are being killed all day long,  
    and accounted as sheep for the slaughter.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 44, 23, 'Rouse yourself! Why do you sleep, O Lord?  
    Awake, do not cast us off forever!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 44, 24, 'Why do you hide your face?  
    Why do you forget our affliction and oppression?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 44, 25, 'For we sink down to the dust;  
    our bodies cling to the ground.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 44, 26, 'Rise up, come to our help.  
    Redeem us for the sake of your steadfast love.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 45, 1, 'My heart overflows with a goodly theme;  
    I address my verses to the king;  
    my tongue is like the pen of a ready scribe.', 'en', 'NRSV-CE', 'Psalm 45'),
(19, 'Maz', 'Psalms', 45, 2, 'You are the most handsome of men;  
    grace is poured upon your lips;  
    therefore God has blessed you forever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 45, 3, 'Gird your sword on your thigh, O mighty one,  
    in your glory and majesty.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 45, 4, 'In your majesty ride on victoriously  
    for the cause of truth and to defend the right;  
    let your right hand teach you dread deeds.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 45, 5, 'Your arrows are sharp  
    in the heart of the king"s enemies;  
    the peoples fall under you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 45, 6, 'Your throne, O God, endures forever and ever.  
    Your royal scepter is a scepter of equity;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 45, 7, 'you love righteousness and hate wickedness.  
Therefore God, your God, has anointed you  
    with the oil of gladness beyond your companions;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 45, 8, 'your robes are all fragrant with myrrh and aloes and cassia.  
From ivory palaces stringed instruments make you glad;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 45, 9, 'daughters of kings are among your ladies of honor;  
    at your right hand stands the queen in gold of Ophir.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 45, 10, 'Hear, O daughter, consider and incline your ear;  
    forget your people and your father"s house,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 45, 11, 'and the king will desire your beauty.  
Since he is your lord, bow to him;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 45, 12, 'the people of Tyre will seek your favor with gifts,  
    the richest of the people', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 45, 13, 'with all kinds of wealth.   
    The princess is decked in her chamber with gold-woven robes;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 45, 14, 'in many-colored robes she is led to the king;  
    behind her the virgins, her companions, follow.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 45, 15, 'With joy and gladness they are led along  
    as they enter the palace of the king.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 45, 16, 'In the place of ancestors you, O king, shall have sons;  
    you will make them princes in all the earth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 45, 17, 'I will cause your name to be celebrated in all generations;  
    therefore the peoples will praise you forever and ever.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 46, 1, 'God is our refuge and strength,  
    a very present help in trouble.', 'en', 'NRSV-CE', 'Psalm 46'),
(19, 'Maz', 'Psalms', 46, 2, 'Therefore we will not fear, though the earth should change,  
    though the mountains shake in the heart of the sea;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 46, 3, 'though its waters roar and foam,  
    though the mountains tremble with its tumult._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 46, 4, 'There is a river whose streams make glad the city of God,  
    the holy habitation of the Most High.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 46, 5, 'God is in the midst of the city; it shall not be moved;  
    God will help it when the morning dawns.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 46, 6, 'The nations are in an uproar, the kingdoms totter;  
    he utters his voice, the earth melts.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 46, 7, 'The LORD of hosts is with us;  
    the God of Jacob is our refuge._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 46, 8, 'Come, behold the works of the LORD;  
    see what desolations he has brought on the earth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 46, 9, 'He makes wars cease to the end of the earth;  
    he breaks the bow, and shatters the spear;  
    he burns the shields with fire.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 46, 10, '"Be still, and know that I am God!  
    I am exalted among the nations,  
    I am exalted in the earth."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 46, 11, 'The LORD of hosts is with us;  
    the God of Jacob is our refuge._Selah_', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 47, 1, 'Clap your hands, all you peoples;  
    shout to God with loud songs of joy.', 'en', 'NRSV-CE', 'Psalm 47'),
(19, 'Maz', 'Psalms', 47, 2, 'For the LORD, the Most High, is awesome,  
    a great king over all the earth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 47, 3, 'He subdued peoples under us,  
    and nations under our feet.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 47, 4, 'He chose our heritage for us,  
    the pride of Jacob whom he loves._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 47, 5, 'God has gone up with a shout,  
    the LORD with the sound of a trumpet.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 47, 6, 'Sing praises to God, sing praises;  
    sing praises to our King, sing praises.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 47, 7, 'For God is the king of all the earth;  
    sing praises with a psalm.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 47, 8, 'God is king over the nations;  
    God sits on his holy throne.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 47, 9, 'The princes of the peoples gather  
    as the people of the God of Abraham.  
For the shields of the earth belong to God;  
    he is highly exalted.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 48, 1, 'Great is the LORD and greatly to be praised  
    in the city of our God.  
His holy mountain,', 'en', 'NRSV-CE', 'Psalm 48'),
(19, 'Maz', 'Psalms', 48, 2, 'beautiful in elevation,  
    is the joy of all the earth,  
Mount Zion, in the far north,  
    the city of the great King.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 48, 3, 'Within its citadels God  
    has shown himself a sure defense.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 48, 4, 'Then the kings assembled,  
    they came on together.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 48, 5, 'As soon as they saw it, they were astounded;  
    they were in panic, they took to flight;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 48, 6, 'trembling took hold of them there,  
    pains as of a woman in labor,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 48, 7, 'as when an east wind shatters  
    the ships of Tarshish.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 48, 8, 'As we have heard, so have we seen  
    in the city of the LORD of hosts,  
in the city of our God,  
    which God establishes forever._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 48, 9, 'We ponder your steadfast love, O God,  
    in the midst of your temple.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 48, 10, 'Your name, O God, like your praise,  
    reaches to the ends of the earth.  
Your right hand is filled with victory.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 48, 11, 'Let Mount Zion be glad,  
let the towns of Judah rejoice  
    because of your judgments.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 48, 12, 'Walk about Zion, go all around it,  
    count its towers,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 48, 13, 'consider well its ramparts;  
    go through its citadels,  
that you may tell the next generation', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 48, 14, 'that this is God,  
our God forever and ever.  
    He will be our guide forever.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 49, 1, 'Hear this, all you peoples;  
    give ear, all inhabitants of the world,', 'en', 'NRSV-CE', 'Psalm 49'),
(19, 'Maz', 'Psalms', 49, 2, 'both low and high,  
    rich and poor together.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 49, 3, 'My mouth shall speak wisdom;  
    the meditation of my heart shall be understanding.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 49, 4, 'I will incline my ear to a proverb;  
    I will solve my riddle to the music of the harp.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 49, 5, 'Why should I fear in times of trouble,  
    when the iniquity of my persecutors surrounds me,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 49, 6, 'those who trust in their wealth  
    and boast of the abundance of their riches?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 49, 7, 'Truly, no ransom avails for one"s life,  
    there is no price one can give to God for it.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 49, 8, 'For the ransom of life is costly,  
    and can never suffice,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 49, 9, 'that one should live on forever  
    and never see the grave.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 49, 10, 'When we look at the wise, they die;  
    fool and dolt perish together  
    and leave their wealth to others.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 49, 11, 'Their graves are their homes forever,  
    their dwelling places to all generations,  
    though they named lands their own.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 49, 12, 'Mortals cannot abide in their pomp;  
    they are like the animals that perish.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 49, 13, 'Such is the fate of the foolhardy,  
    the end of those who are pleased with their lot._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 49, 14, 'Like sheep they are appointed for Sheol;  
    Death shall be their shepherd;  
straight to the grave they descend,  
    and their form shall waste away;  
    Sheol shall be their home.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 49, 15, 'But God will ransom my soul from the power of Sheol,  
    for he will receive me._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 49, 16, 'Do not be afraid when some become rich,  
    when the wealth of their houses increases.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 49, 17, 'For when they die they will carry nothing away;  
    their wealth will not go down after them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 49, 18, 'Though in their lifetime they count themselves happy  
    --for you are praised when you do well for yourself--', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 49, 19, 'they will go to the company of their ancestors,  
    who will never again see the light.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 49, 20, 'Mortals cannot abide in their pomp;  
    they are like the animals that perish.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 50, 1, 'The mighty one, God the LORD,  
    speaks and summons the earth  
    from the rising of the sun to its setting.', 'en', 'NRSV-CE', 'Psalm 50'),
(19, 'Maz', 'Psalms', 50, 2, 'Out of Zion, the perfection of beauty,  
    God shines forth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 50, 3, 'Our God comes and does not keep silence,  
    before him is a devouring fire,  
    and a mighty tempest all around him.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 50, 4, 'He calls to the heavens above  
    and to the earth, that he may judge his people:', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 50, 5, '"Gather to me my faithful ones,  
    who made a covenant with me by sacrifice!"', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 50, 6, 'The heavens declare his righteousness,  
    for God himself is judge._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 50, 7, '"Hear, O my people, and I will speak,  
    O Israel, I will testify against you.  
    I am God, your God.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 50, 8, 'Not for your sacrifices do I rebuke you;  
    your burnt offerings are continually before me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 50, 9, 'I will not accept a bull from your house,  
    or goats from your folds.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 50, 10, 'For every wild animal of the forest is mine,  
    the cattle on a thousand hills.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 50, 11, 'I know all the birds of the air,  
    and all that moves in the field is mine.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 50, 12, '"If I were hungry, I would not tell you,  
    for the world and all that is in it is mine.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 50, 13, 'Do I eat the flesh of bulls,  
    or drink the blood of goats?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 50, 14, 'Offer to God a sacrifice of thanksgiving,  
    and pay your vows to the Most High.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 50, 15, 'Call on me in the day of trouble;  
    I will deliver you, and you shall glorify me."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 50, 16, 'But to the wicked God says:  
    "What right have you to recite my statutes,  
    or take my covenant on your lips?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 50, 17, 'For you hate discipline,  
    and you cast my words behind you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 50, 18, 'You make friends with a thief when you see one,  
    and you keep company with adulterers.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 50, 19, '"You give your mouth free rein for evil,  
    and your tongue frames deceit.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 50, 20, 'You sit and speak against your kin;  
    you slander your own mother"s child.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 50, 21, 'These things you have done and I have been silent;  
    you thought that I was one just like yourself.  
But now I rebuke you, and lay the charge before you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 50, 22, '"Mark this, then, you who forget God,  
    or I will tear you apart, and there will be no one to deliver.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 50, 23, 'Those who bring thanksgiving as their sacrifice honor me;  
    to those who go the right way  
    I will show the salvation of God."', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 51, 1, 'Have mercy on me, O God,  
    according to your steadfast love;  
according to your abundant mercy  
    blot out my transgressions.', 'en', 'NRSV-CE', 'Psalm 51'),
(19, 'Maz', 'Psalms', 51, 2, 'Wash me thoroughly from my iniquity,  
    and cleanse me from my sin.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 51, 3, 'For I know my transgressions,  
    and my sin is ever before me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 51, 4, 'Against you, you alone, have I sinned,  
    and done what is evil in your sight,  
so that you are justified in your sentence  
    and blameless when you pass judgment.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 51, 5, 'Indeed, I was born guilty,  
    a sinner when my mother conceived me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 51, 6, 'You desire truth in the inward being;  
    therefore teach me wisdom in my secret heart.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 51, 7, 'Purge me with hyssop, and I shall be clean;  
    wash me, and I shall be whiter than snow.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 51, 8, 'Let me hear joy and gladness;  
    let the bones that you have crushed rejoice.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 51, 9, 'Hide your face from my sins,  
    and blot out all my iniquities.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 51, 10, 'Create in me a clean heart, O God,  
    and put a new and right spirit within me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 51, 11, 'Do not cast me away from your presence,  
    and do not take your holy spirit from me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 51, 12, 'Restore to me the joy of your salvation,  
    and sustain in me a willing spirit.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 51, 13, 'Then I will teach transgressors your ways,  
    and sinners will return to you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 51, 14, 'Deliver me from bloodshed, O God,  
    O God of my salvation,  
    and my tongue will sing aloud of your deliverance.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 51, 15, 'O Lord, open my lips,  
    and my mouth will declare your praise.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 51, 16, 'For you have no delight in sacrifice;  
    if I were to give a burnt offering, you would not be pleased.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 51, 17, 'The sacrifice acceptable to God is a broken spirit;  
    a broken and contrite heart, O God, you will not despise.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 51, 18, 'Do good to Zion in your good pleasure;  
    rebuild the walls of Jerusalem,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 51, 19, 'then you will delight in right sacrifices,  
    in burnt offerings and whole burnt offerings;  
    then bulls will be offered on your altar.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 52, 1, 'Why do you boast, O mighty one,  
    of mischief done against the godly?  
    All day long', 'en', 'NRSV-CE', 'Psalm 52'),
(19, 'Maz', 'Psalms', 52, 2, 'you are plotting destruction.  
Your tongue is like a sharp razor,  
    you worker of treachery.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 52, 3, 'You love evil more than good,  
    and lying more than speaking the truth._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 52, 4, 'You love all words that devour,  
    O deceitful tongue.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 52, 5, 'But God will break you down forever;  
    he will snatch and tear you from your tent;  
    he will uproot you from the land of the living._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 52, 6, 'The righteous will see, and fear,  
    and will laugh at the evildoer, saying,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 52, 7, '"See the one who would not take  
    refuge in God,  
but trusted in abundant riches,  
    and sought refuge in wealth!"', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 52, 8, 'But I am like a green olive tree  
    in the house of God.  
I trust in the steadfast love of God  
    forever and ever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 52, 9, 'I will thank you forever,  
    because of what you have done.  
In the presence of the faithful  
    I will proclaim your name, for it is good.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 53, 1, 'Fools say in their hearts, "There is no God."  
    They are corrupt, they commit abominable acts;  
    there is no one who does good.', 'en', 'NRSV-CE', 'Psalm 53'),
(19, 'Maz', 'Psalms', 53, 2, 'God looks down from heaven on humankind  
    to see if there are any who are wise,  
    who seek after God.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 53, 3, 'They have all fallen away, they are all alike perverse;  
    there is no one who does good,  
    no, not one.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 53, 4, 'Have they no knowledge, those evildoers,  
    who eat up my people as they eat bread,  
    and do not call upon God?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 53, 5, 'There they shall be in great terror,  
    in terror such as has not been.  
For God will scatter the bones of the ungodly;  
    they will be put to shame, for God has rejected them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 53, 6, 'O that deliverance for Israel would come from Zion!  
    When God restores the fortunes of his people,  
    Jacob will rejoice; Israel will be glad.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 54, 1, 'Save me, O God, by your name,  
    and vindicate me by your might.', 'en', 'NRSV-CE', 'Psalm 54'),
(19, 'Maz', 'Psalms', 54, 2, 'Hear my prayer, O God;  
    give ear to the words of my mouth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 54, 3, 'For the insolent have risen against me,  
    the ruthless seek my life;  
    they do not set God before them._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 54, 4, 'But surely, God is my helper;  
    the Lord is the upholder of my life.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 54, 5, 'He will repay my enemies for their evil.  
    In your faithfulness, put an end to them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 54, 6, 'With a freewill offering I will sacrifice to you;  
    I will give thanks to your name, O LORD, for it is good.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 54, 7, 'For he has delivered me from every trouble,  
    and my eye has looked in triumph on my enemies.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 55, 1, 'Give ear to my prayer, O God;  
    do not hide yourself from my supplication.', 'en', 'NRSV-CE', 'Psalm 55'),
(19, 'Maz', 'Psalms', 55, 2, 'Attend to me, and answer me;  
    I am troubled in my complaint.  
I am distraught', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 55, 3, 'by the noise of the enemy,  
    because of the clamor of the wicked.  
For they bring trouble upon me,  
    and in anger they cherish enmity against me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 55, 4, 'My heart is in anguish within me,  
    the terrors of death have fallen upon me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 55, 5, 'Fear and trembling come upon me,  
    and horror overwhelms me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 55, 6, 'And I say, "O that I had wings like a dove!  
    I would fly away and be at rest;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 55, 7, 'truly, I would flee far away;  
    I would lodge in the wilderness;_Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 55, 8, 'I would hurry to find a shelter for myself  
    from the raging wind and tempest."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 55, 9, 'Confuse, O Lord, confound their speech;  
    for I see violence and strife in the city.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 55, 10, 'Day and night they go around it  
    on its walls,  
and iniquity and trouble are within it;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 55, 11, 'ruin is in its midst;  
oppression and fraud  
    do not depart from its marketplace.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 55, 12, 'It is not enemies who taunt me--  
    I could bear that;  
it is not adversaries who deal insolently with me--  
    I could hide from them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 55, 13, 'But it is you, my equal,  
    my companion, my familiar friend,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 55, 14, 'with whom I kept pleasant company;  
    we walked in the house of God with the throng.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 55, 15, 'Let death come upon them;  
    let them go down alive to Sheol;  
    for evil is in their homes and in their hearts.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 55, 16, 'But I call upon God,  
    and the LORD will save me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 55, 17, 'Evening and morning and at noon  
    I utter my complaint and moan,  
    and he will hear my voice.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 55, 18, 'He will redeem me unharmed  
    from the battle that I wage,  
    for many are arrayed against me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 55, 19, 'God, who is enthroned from of old,_Selah_  
    will hear, and will humble them--  
because they do not change,  
    and do not fear God.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 55, 20, 'My companion laid hands on a friend  
    and violated a covenant with me', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 55, 21, 'with speech smoother than butter,  
    but with a heart set on war;  
with words that were softer than oil,  
    but in fact were drawn swords.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 55, 22, 'Cast your burden on the LORD,  
    and he will sustain you;  
he will never permit  
    the righteous to be moved.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 55, 23, 'But you, O God, will cast them down  
    into the lowest pit;  
the bloodthirsty and treacherous  
    shall not live out half their days.  
But I will trust in you.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 56, 1, 'Be gracious to me, O God, for people trample on me;  
    all day long foes oppress me;', 'en', 'NRSV-CE', 'Psalm 56'),
(19, 'Maz', 'Psalms', 56, 2, 'my enemies trample on me all day long,  
    for many fight against me.  
O Most High,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 56, 3, 'when I am afraid,  
    I put my trust in you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 56, 4, 'In God, whose word I praise,  
    in God I trust; I am not afraid;  
    what can flesh do to me?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 56, 5, 'All day long they seek to injure my cause;  
    all their thoughts are against me for evil.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 56, 6, 'They stir up strife, they lurk,  
    they watch my steps.  
As they hoped to have my life,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 56, 7, 'so repay them for their crime;  
    in wrath cast down the peoples, O God!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 56, 8, 'You have kept count of my tossings;  
    put my tears in your bottle.  
    Are they not in your record?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 56, 9, 'Then my enemies will retreat  
    in the day when I call.  
    This I know, that God is for me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 56, 10, 'In God, whose word I praise,  
    in the LORD, whose word I praise,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 56, 11, 'in God I trust; I am not afraid.  
    What can a mere mortal do to me?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 56, 12, 'My vows to you I must perform, O God;  
    I will render thank offerings to you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 56, 13, 'For you have delivered my soul from death,  
    and my feet from falling,  
so that I may walk before God  
    in the light of life.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 57, 1, 'Be merciful to me, O God, be merciful to me,  
    for in you my soul takes refuge;  
in the shadow of your wings I will take refuge,  
    until the destroying storms pass by.', 'en', 'NRSV-CE', 'Psalm 57'),
(19, 'Maz', 'Psalms', 57, 2, 'I cry to God Most High,  
    to God who fulfills his purpose for me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 57, 3, 'He will send from heaven and save me,  
    he will put to shame those who trample on me._Selah_  
God will send forth his steadfast love and his faithfulness.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 57, 4, 'I lie down among lions  
    that greedily devour human prey;  
their teeth are spears and arrows,  
    their tongues sharp swords.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 57, 5, 'Be exalted, O God, above the heavens.  
    Let your glory be over all the earth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 57, 6, 'They set a net for my steps;  
    my soul was bowed down.  
They dug a pit in my path,  
    but they have fallen into it themselves._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 57, 7, 'My heart is steadfast, O God,  
    my heart is steadfast.  
I will sing and make melody.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 57, 8, 'Awake, my soul!  
Awake, O harp and lyre!  
    I will awake the dawn.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 57, 9, 'I will give thanks to you, O Lord, among the peoples;  
    I will sing praises to you among the nations.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 57, 10, 'For your steadfast love is as high as the heavens;  
    your faithfulness extends to the clouds.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 57, 11, 'Be exalted, O God, above the heavens.  
    Let your glory be over all the earth.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 58, 1, 'Do you indeed decree what is right, you gods?  
    Do you judge people fairly?', 'en', 'NRSV-CE', 'Psalm 58'),
(19, 'Maz', 'Psalms', 58, 2, 'No, in your hearts you devise wrongs;  
    your hands deal out violence on earth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 58, 3, 'The wicked go astray from the womb;  
    they err from their birth, speaking lies.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 58, 4, 'They have venom like the venom of a serpent,  
    like the deaf adder that stops its ear,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 58, 5, 'so that it does not hear the voice of charmers  
    or of the cunning enchanter.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 58, 6, 'O God, break the teeth in their mouths;  
    tear out the fangs of the young lions, O LORD!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 58, 7, 'Let them vanish like water that runs away;  
    like grass let them be trodden down and wither.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 58, 8, 'Let them be like the snail that dissolves into slime;  
    like the untimely birth that never sees the sun.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 58, 9, 'Sooner than your pots can feel the heat of thorns,  
    whether green or ablaze, may he sweep them away!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 58, 10, 'The righteous will rejoice when they see vengeance done;  
    they will bathe their feet in the blood of the wicked.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 58, 11, 'People will say, "Surely there is a reward for the righteous;  
    surely there is a God who judges on earth."', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 59, 1, 'Deliver me from my enemies, O my God;  
    protect me from those who rise up against me.', 'en', 'NRSV-CE', 'Psalm 59'),
(19, 'Maz', 'Psalms', 59, 2, 'Deliver me from those who work evil;  
    from the bloodthirsty save me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 59, 3, 'Even now they lie in wait for my life;  
    the mighty stir up strife against me.  
For no transgression or sin of mine, O LORD,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 59, 4, 'for no fault of mine, they run and make ready.
Rouse yourself, come to my help and see!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 59, 5, 'You, LORD God of hosts, are God of Israel.  
Awake to punish all the nations;  
    spare none of those who treacherously plot evil._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 59, 6, 'Each evening they come back,  
    howling like dogs  
    and prowling about the city.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 59, 7, 'There they are, bellowing with their mouths,  
    with sharp words on their lips--  
    for "Who," they think, "will hear us?"', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 59, 8, 'But you laugh at them, O LORD;  
    you hold all the nations in derision.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 59, 9, 'O my strength, I will watch for you;  
    for you, O God, are my fortress.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 59, 10, 'My God in his steadfast love will meet me;  
    my God will let me look in triumph on my enemies.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 59, 11, 'Do not kill them, or my people may forget;  
    make them totter by your power, and bring them down,  
    O Lord, our shield.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 59, 12, 'For the sin of their mouths, the words of their lips,  
    let them be trapped in their pride.  
For the cursing and lies that they utter,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 59, 13, 'consume them in wrath;  
    consume them until they are no more.  
Then it will be known to the ends of the earth  
    that God rules over Jacob._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 59, 14, 'Each evening they come back,  
    howling like dogs  
    and prowling about the city.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 59, 15, 'They roam about for food,  
    and growl if they do not get their fill.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 59, 16, 'But I will sing of your might;  
    I will sing aloud of your steadfast love in the morning.  
For you have been a fortress for me  
    and a refuge in the day of my distress.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 59, 17, 'O my strength, I will sing praises to you,  
    for you, O God, are my fortress,  
    the God who shows me steadfast love.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 60, 1, 'O God, you have rejected us, broken our defenses;  
    you have been angry; now restore us!', 'en', 'NRSV-CE', 'Psalm 60'),
(19, 'Maz', 'Psalms', 60, 2, 'You have caused the land to quake; you have torn it open;  
    repair the cracks in it, for it is tottering.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 60, 3, 'You have made your people suffer hard things;  
    you have given us wine to drink that made us reel.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 60, 4, 'You have set up a banner for those who fear you,  
    to rally to it out of bowshot._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 60, 5, 'Give victory with your right hand, and answer us,  
    so that those whom you love may be rescued.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 60, 6, 'God has promised in his sanctuary:  
    "With exultation I will divide up Shechem,  
    and portion out the Vale of Succoth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 60, 7, 'Gilead is mine, and Manasseh is mine;  
    Ephraim is my helmet;  
    Judah is my scepter.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 60, 8, 'Moab is my washbasin;  
    on Edom I hurl my shoe;  
    over Philistia I shout in triumph."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 60, 9, 'Who will bring me to the fortified city?  
    Who will lead me to Edom?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 60, 10, 'Have you not rejected us, O God?  
    You do not go out, O God, with our armies.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 60, 11, 'O grant us help against the foe,  
    for human help is worthless.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 60, 12, 'With God we shall do valiantly;  
    it is he who will tread down our foes.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 61, 1, 'Hear my cry, O God;  
    listen to my prayer.', 'en', 'NRSV-CE', 'Psalm 61'),
(19, 'Maz', 'Psalms', 61, 2, 'From the end of the earth I call to you,  
    when my heart is faint.
Lead me to the rock  
    that is higher than I;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 61, 3, 'for you are my refuge,  
    a strong tower against the enemy.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 61, 4, 'Let me abide in your tent forever,  
    find refuge under the shelter of your wings._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 61, 5, 'For you, O God, have heard my vows;  
    you have given me the heritage of those who fear your name.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 61, 6, 'Prolong the life of the king;  
    may his years endure to all generations!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 61, 7, 'May he be enthroned forever before God;  
    appoint steadfast love and faithfulness to watch over him!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 61, 8, 'So I will always sing praises to your name,  
    as I pay my vows day after day.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 62, 1, 'For God alone my soul waits in silence;  
    from him comes my salvation.', 'en', 'NRSV-CE', 'Psalm 62'),
(19, 'Maz', 'Psalms', 62, 2, 'He alone is my rock and my salvation,  
    my fortress; I shall never be shaken.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 62, 3, 'How long will you assail a person,  
    will you batter your victim, all of you,  
    as you would a leaning wall, a tottering fence?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 62, 4, 'Their only plan is to bring down a person of prominence.  
    They take pleasure in falsehood;  
they bless with their mouths,  
    but inwardly they curse._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 62, 5, 'For God alone my soul waits in silence,  
    for my hope is from him.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 62, 6, 'He alone is my rock and my salvation,  
    my fortress; I shall not be shaken.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 62, 7, 'On God rests my deliverance and my honor;  
    my mighty rock, my refuge is in God.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 62, 8, 'Trust in him at all times, O people;  
    pour out your heart before him;  
    God is a refuge for us._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 62, 9, 'Those of low estate are but a breath,  
    those of high estate are a delusion;  
in the balances they go up;  
    they are together lighter than a breath.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 62, 10, 'Put no confidence in extortion,  
    and set no vain hopes on robbery;  
    if riches increase, do not set your heart on them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 62, 11, 'Once God has spoken;  
    twice have I heard this:  
that power belongs to God,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 62, 12, 'and steadfast love belongs to you, O Lord.  
For you repay to all  
    according to their work.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 63, 1, 'O God, you are my God, I seek you,  
    my soul thirsts for you;  
my flesh faints for you,  
    as in a dry and weary land where there is no water.', 'en', 'NRSV-CE', 'Psalm 63'),
(19, 'Maz', 'Psalms', 63, 2, 'So I have looked upon you in the sanctuary,  
    beholding your power and glory.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 63, 3, 'Because your steadfast love is better than life,  
    my lips will praise you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 63, 4, 'So I will bless you as long as I live;  
    I will lift up my hands and call on your name.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 63, 5, 'My soul is satisfied as with a rich feast,  
    and my mouth praises you with joyful lips', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 63, 6, 'when I think of you on my bed,  
    and meditate on you in the watches of the night;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 63, 7, 'for you have been my help,  
    and in the shadow of your wings I sing for joy.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 63, 8, 'My soul clings to you;  
    your right hand upholds me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 63, 9, 'But those who seek to destroy my life  
    shall go down into the depths of the earth;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 63, 10, 'they shall be given over to the power of the sword,  
    they shall be prey for jackals.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 63, 11, 'But the king shall rejoice in God;  
    all who swear by him shall exult,  
    for the mouths of liars will be stopped.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 64, 1, 'Hear my voice, O God, in my complaint;  
    preserve my life from the dread enemy.', 'en', 'NRSV-CE', 'Psalm 64'),
(19, 'Maz', 'Psalms', 64, 2, 'Hide me from the secret plots of the wicked,  
    from the scheming of evildoers,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 64, 3, 'who whet their tongues like swords,  
    who aim bitter words like arrows,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 64, 4, 'shooting from ambush at the blameless;  
    they shoot suddenly and without fear.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 64, 5, 'They hold fast to their evil purpose;  
    they talk of laying snares secretly,  
thinking, "Who can see us?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 64, 6, 'Who can search out our crimes?  
We have thought out a cunningly conceived plot."  
    For the human heart and mind are deep.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 64, 7, 'But God will shoot his arrow at them;  
    they will be wounded suddenly.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 64, 8, 'Because of their tongue he will bring them to ruin;  
    all who see them will shake with horror.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 64, 9, 'Then everyone will fear;  
    they will tell what God has brought about,  
    and ponder what he has done.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 64, 10, 'Let the righteous rejoice in the LORD  
    and take refuge in him.  
Let all the upright in heart glory.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 65, 1, 'Praise is due to you,  
    O God, in Zion;  
and to you shall vows be performed,', 'en', 'NRSV-CE', 'Psalm 65'),
(19, 'Maz', 'Psalms', 65, 2, 'O you who answer prayer!  
To you all flesh shall come.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 65, 3, 'When deeds of iniquity overwhelm us,  
    you forgive our transgressions.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 65, 4, 'Happy are those whom you choose and bring near  
    to live in your courts.  
We shall be satisfied with the goodness of your house,  
    your holy temple.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 65, 5, 'By awesome deeds you answer us with deliverance,  
    O God of our salvation;  
you are the hope of all the ends of the earth  
    and of the farthest seas.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 65, 6, 'By your strength you established the mountains;  
    you are girded with might.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 65, 7, 'You silence the roaring of the seas,  
    the roaring of their waves,  
    the tumult of the peoples.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 65, 8, 'Those who live at earth"s farthest bounds are awed by your signs;  
you make the gateways of the morning and the evening shout for joy.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 65, 9, 'You visit the earth and water it,  
    you greatly enrich it;  
the river of God is full of water;  
    you provide the people with grain,  
    for so you have prepared it.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 65, 10, 'You water its furrows abundantly,  
    settling its ridges,  
softening it with showers,  
    and blessing its growth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 65, 11, 'You crown the year with your bounty;  
    your wagon tracks overflow with richness.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 65, 12, 'The pastures of the wilderness overflow,  
    the hills gird themselves with joy,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 65, 13, 'the meadows clothe themselves with flocks,  
    the valleys deck themselves with grain,  
    they shout and sing together for joy.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 66, 1, 'Make a joyful noise to God, all the earth;', 'en', 'NRSV-CE', 'Psalm 66'),
(19, 'Maz', 'Psalms', 66, 2, 'sing the glory of his name;  
    give to him glorious praise.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 66, 3, 'Say to God, "How awesome are your deeds!  
    Because of your great power, your enemies cringe before you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 66, 4, 'All the earth worships you;  
    they sing praises to you,  
    sing praises to your name."_Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 66, 5, 'Come and see what God has done:  
    he is awesome in his deeds among mortals.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 66, 6, 'He turned the sea into dry land;  
    they passed through the river on foot.  
There we rejoiced in him,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 66, 7, 'who rules by his might forever,  
whose eyes keep watch on the nations--  
    let the rebellious not exalt themselves._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 66, 8, 'Bless our God, O peoples,  
    let the sound of his praise be heard,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 66, 9, 'who has kept us among the living,  
    and has not let our feet slip.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 66, 10, 'For you, O God, have tested us;  
    you have tried us as silver is tried.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 66, 11, 'You brought us into the net;  
    you laid burdens on our backs;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 66, 12, 'you let people ride over our heads;  
    we went through fire and through water;  
yet you have brought us out to a spacious place.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 66, 13, 'I will come into your house with burnt offerings;  
    I will pay you my vows,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 66, 14, 'those that my lips uttered  
    and my mouth promised when I was in trouble.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 66, 15, 'I will offer to you burnt offerings of fatlings,  
    with the smoke of the sacrifice of rams;  
I will make an offering of bulls and goats._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 66, 16, 'Come and hear, all you who fear God,  
    and I will tell what he has done for me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 66, 17, 'I cried aloud to him,  
    and he was extolled with my tongue.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 66, 18, 'If I had cherished iniquity in my heart,  
    the Lord would not have listened.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 66, 19, 'But truly God has listened;  
    he has given heed to the words of my prayer.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 66, 20, 'Blessed be God,  
    because he has not rejected my prayer  
    or removed his steadfast love from me.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 67, 1, 'May God be gracious to us and bless us  
    and make his face to shine upon us,_Selah_', 'en', 'NRSV-CE', 'Psalm 67'),
(19, 'Maz', 'Psalms', 67, 2, 'that your way may be known upon earth,  
    your saving power among all nations.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 67, 3, 'Let the peoples praise you, O God;  
    let all the peoples praise you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 67, 4, 'Let the nations be glad and sing for joy,  
    for you judge the peoples with equity  
    and guide the nations upon earth._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 67, 5, 'Let the peoples praise you, O God;  
    let all the peoples praise you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 67, 6, 'The earth has yielded its increase;  
    God, our God, has blessed us.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 67, 7, 'May God continue to bless us;  
    let all the ends of the earth revere him.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 68, 1, 'Let God rise up, let his enemies be scattered;  
    let those who hate him flee before him.', 'en', 'NRSV-CE', 'Psalm 68'),
(19, 'Maz', 'Psalms', 68, 2, 'As smoke is driven away, so drive them away;  
    as wax melts before the fire,  
    let the wicked perish before God.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 3, 'But let the righteous be joyful;  
    let them exult before God;  
    let them be jubilant with joy.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 4, 'Sing to God, sing praises to his name;  
    lift up a song to him who rides upon the clouds--  
his name is the LORD--  
    be exultant before him.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 5, 'Father of orphans and protector of widows  
    is God in his holy habitation.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 6, 'God gives the desolate a home to live in;  
    he leads out the prisoners to prosperity,  
    but the rebellious live in a parched land.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 7, 'O God, when you went out before your people,  
    when you marched through the wilderness,_Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 8, 'the earth quaked, the heavens poured down rain  
    at the presence of God, the God of Sinai,  
    at the presence of God, the God of Israel.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 9, 'Rain in abundance, O God, you showered abroad;  
    you restored your heritage when it languished;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 10, 'your flock found a dwelling in it;  
    in your goodness, O God, you provided for the needy.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 11, 'The Lord gives the command;  
    great is the company of those who bore the tidings:', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 12, '"The kings of the armies, they flee, they flee!"  
The women at home divide the spoil,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 13, 'though they stay among the sheepfolds--  
the wings of a dove covered with silver,  
    its pinions with green gold.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 14, 'When the Almighty scattered kings there,  
    snow fell on Zalmon.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 15, 'O mighty mountain, mountain of Bashan;  
    O many-peaked mountain, mountain of Bashan!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 16, 'Why do you look with envy, O many-peaked mountain,  
    at the mount that God desired for his abode,  
    where the LORD will reside forever?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 17, 'With mighty chariotry, twice ten thousand,  
    thousands upon thousands,  
    the Lord came from Sinai into the holy place.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 18, 'You ascended the high mount,  
    leading captives in your train  
    and receiving gifts from people,  
even from those who rebel against the LORD God"s abiding there.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 19, 'Blessed be the Lord,  
    who daily bears us up;  
    God is our salvation._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 20, 'Our God is a God of salvation,  
    and to God, the Lord, belongs escape from death.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 21, 'But God will shatter the heads of his enemies,  
    the hairy crown of those who walk in their guilty ways.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 22, 'The Lord said,  
    "I will bring them back from Bashan,  
I will bring them back from the depths of the sea,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 23, 'so that you may bathe your feet in blood,  
    so that the tongues of your dogs may have their share from the foe."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 24, 'Your solemn processions are seen, O God,  
    the processions of my God, my King, into the sanctuary--', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 25, 'the singers in front, the musicians last,  
    between them girls playing tambourines:', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 26, '"Bless God in the great congregation,  
    the LORD, O you who are of Israel"s fountain!"', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 27, 'There is Benjamin, the least of them, in the lead,  
    the princes of Judah in a body,  
    the princes of Zebulun, the princes of Naphtali.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 28, 'Summon your might, O God;  
    show your strength, O God, as you have done for us before.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 29, 'Because of your temple at Jerusalem  
    kings bear gifts to you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 30, 'Rebuke the wild animals that live among the reeds,  
    the herd of bulls with the calves of the peoples.  
Trample under foot those who lust after tribute;  
    scatter the peoples who delight in war.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 31, 'Let bronze be brought from Egypt;  
    let Ethiopia hasten to stretch out its hands to God.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 32, 'Sing to God, O kingdoms of the earth;  
    sing praises to the Lord,_Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 33, 'O rider in the heavens, the ancient heavens;  
    listen, he sends out his voice, his mighty voice.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 34, 'Ascribe power to God,  
    whose majesty is over Israel;  
    and whose power is in the skies.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 68, 35, 'Awesome is God in his sanctuary,  
    the God of Israel;  
    he gives power and strength to his people.
Blessed be God!', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 69, 1, 'Save me, O God,  
    for the waters have come up to my neck.', 'en', 'NRSV-CE', 'Psalm 69'),
(19, 'Maz', 'Psalms', 69, 2, 'I sink in deep mire,  
    where there is no foothold;  
I have come into deep waters,  
    and the flood sweeps over me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 3, 'I am weary with my crying;  
    my throat is parched.  
My eyes grow dim  
    with waiting for my God.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 4, 'More in number than the hairs of my head  
    are those who hate me without cause;  
many are those who would destroy me,  
    my enemies who accuse me falsely.  
What I did not steal  
    must I now restore?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 5, 'O God, you know my folly;  
    the wrongs I have done are not hidden from you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 6, 'Do not let those who hope in you be put to shame because of me,  
    O Lord God of hosts;  
do not let those who seek you be dishonored because of me,  
    O God of Israel.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 7, 'It is for your sake that I have borne reproach,  
    that shame has covered my face.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 8, 'I have become a stranger to my kindred,  
    an alien to my mother"s children.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 9, 'It is zeal for your house that has consumed me;  
    the insults of those who insult you have fallen on me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 10, 'When I humbled my soul with fasting,  
    they insulted me for doing so.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 11, 'When I made sackcloth my clothing,  
    I became a byword to them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 12, 'I am the subject of gossip for those who sit in the gate,  
    and the drunkards make songs about me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 13, 'But as for me, my prayer is to you, O LORD.  
    At an acceptable time, O God,  
    in the abundance of your steadfast love, answer me.  
With your faithful help', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 14, 'rescue me  
    from sinking in the mire;  
let me be delivered from my enemies  
    and from the deep waters.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 15, 'Do not let the flood sweep over me,  
    or the deep swallow me up,  
    or the Pit close its mouth over me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 16, 'Answer me, O LORD, for your steadfast love is good;  
    according to your abundant mercy, turn to me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 17, 'Do not hide your face from your servant,  
    for I am in distress--make haste to answer me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 18, 'Draw near to me, redeem me,  
    set me free because of my enemies.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 19, 'You know the insults I receive,  
    and my shame and dishonor;  
    my foes are all known to you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 20, 'Insults have broken my heart,  
    so that I am in despair.  
I looked for pity, but there was none;  
    and for comforters, but I found none.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 21, 'They gave me poison for food,  
    and for my thirst they gave me vinegar to drink.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 22, 'Let their table be a trap for them,  
    a snare for their allies.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 23, 'Let their eyes be darkened so that they cannot see,  
    and make their loins tremble continually.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 24, 'Pour out your indignation upon them,  
    and let your burning anger overtake them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 25, 'May their camp be a desolation;  
    let no one live in their tents.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 26, 'For they persecute those whom you have struck down,  
    and those whom you have wounded, they attack still more.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 27, 'Add guilt to their guilt;  
    may they have no acquittal from you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 28, 'Let them be blotted out of the book of the living;  
    let them not be enrolled among the righteous.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 29, 'But I am lowly and in pain;  
    let your salvation, O God, protect me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 30, 'I will praise the name of God with a song;  
    I will magnify him with thanksgiving.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 31, 'This will please the LORD more than an ox  
    or a bull with horns and hoofs.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 32, 'Let the oppressed see it and be glad;  
    you who seek God, let your hearts revive.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 33, 'For the LORD hears the needy,  
    and does not despise his own that are in bonds.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 34, 'Let heaven and earth praise him,  
    the seas and everything that moves in them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 35, 'For God will save Zion  
    and rebuild the cities of Judah;  
and his servants shall live there and possess it;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 69, 36, 'the children of his servants shall inherit it,  
    and those who love his name shall live in it.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 70, 1, 'Be pleased, O God, to deliver me.  
    O LORD, make haste to help me!', 'en', 'NRSV-CE', 'Psalm 70'),
(19, 'Maz', 'Psalms', 70, 2, 'Let those be put to shame and confusion  
    who seek my life.  
Let those be turned back and brought to dishonor  
    who desire to hurt me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 70, 3, 'Let those who say, "Aha, Aha!"  
    turn back because of their shame.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 70, 4, 'Let all who seek you  
    rejoice and be glad in you.  
Let those who love your salvation  
    say evermore, "God is great!"', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 70, 5, 'But I am poor and needy;  
    hasten to me, O God!  
You are my help and my deliverer;  
    O LORD, do not delay!', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 71, 1, 'In you, O LORD, I take refuge;  
    let me never be put to shame.', 'en', 'NRSV-CE', 'Psalm 71'),
(19, 'Maz', 'Psalms', 71, 2, 'In your righteousness deliver me and rescue me;  
    incline your ear to me and save me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 71, 3, 'Be to me a rock of refuge,  
    a strong fortress, to save me,  
    for you are my rock and my fortress.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 71, 4, 'Rescue me, O my God, from the hand of the wicked,  
    from the grasp of the unjust and cruel.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 71, 5, 'For you, O Lord, are my hope,  
    my trust, O LORD, from my youth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 71, 6, 'Upon you I have leaned from my birth;  
    it was you who took me from my mother"s womb.  
My praise is continually of you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 71, 7, 'I have been like a portent to many,  
    but you are my strong refuge.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 71, 8, 'My mouth is filled with your praise,  
    and with your glory all day long.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 71, 9, 'Do not cast me off in the time of old age;  
    do not forsake me when my strength is spent.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 71, 10, 'For my enemies speak concerning me,  
    and those who watch for my life consult together.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 71, 11, 'They say, "Pursue and seize that person  
    whom God has forsaken,  
    for there is no one to deliver."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 71, 12, 'O God, do not be far from me;  
    O my God, make haste to help me!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 71, 13, 'Let my accusers be put to shame and consumed;  
    let those who seek to hurt me  
    be covered with scorn and disgrace.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 71, 14, 'But I will hope continually,  
    and will praise you yet more and more.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 71, 15, 'My mouth will tell of your righteous acts,  
    of your deeds of salvation all day long,  
    though their number is past my knowledge.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 71, 16, 'I will come praising the mighty deeds of the Lord God,  
    I will praise your righteousness, yours alone.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 71, 17, 'O God, from my youth you have taught me,  
    and I still proclaim your wondrous deeds.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 71, 18, 'So even to old age and gray hairs,  
    O God, do not forsake me,  
until I proclaim your might  
    to all the generations to come.  
Your power', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 71, 19, 'and your righteousness, O God,  
    reach the high heavens.
You who have done great things,  
    O God, who is like you?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 71, 20, 'You who have made me see many troubles and calamities  
    will revive me again;  
from the depths of the earth  
    you will bring me up again.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 71, 21, 'You will increase my honor,  
    and comfort me once again.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 71, 22, 'I will also praise you with the harp  
    for your faithfulness, O my God;  
I will sing praises to you with the lyre,  
    O Holy One of Israel.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 71, 23, 'My lips will shout for joy  
    when I sing praises to you;  
    my soul also, which you have rescued.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 71, 24, 'All day long my tongue will talk of your righteous help,  
for those who tried to do me harm  
    have been put to shame, and disgraced.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 72, 1, 'Give the king your justice, O God,  
    and your righteousness to a king"s son.', 'en', 'NRSV-CE', 'Psalm 72'),
(19, 'Maz', 'Psalms', 72, 2, 'May he judge your people with righteousness,  
    and your poor with justice.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 72, 3, 'May the mountains yield prosperity for the people,  
    and the hills, in righteousness.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 72, 4, 'May he defend the cause of the poor of the people,  
    give deliverance to the needy,  
    and crush the oppressor.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 72, 5, 'May he live while the sun endures,  
    and as long as the moon, throughout all generations.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 72, 6, 'May he be like rain that falls on the mown grass,  
    like showers that water the earth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 72, 7, 'In his days may righteousness flourish  
    and peace abound, until the moon is no more.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 72, 8, 'May he have dominion from sea to sea,  
    and from the River to the ends of the earth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 72, 9, 'May his foes bow down before him,  
    and his enemies lick the dust.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 72, 10, 'May the kings of Tarshish and of the isles  
    render him tribute,  
may the kings of Sheba and Seba  
    bring gifts.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 72, 11, 'May all kings fall down before him,  
    all nations give him service.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 72, 12, 'For he delivers the needy when they call,  
    the poor and those who have no helper.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 72, 13, 'He has pity on the weak and the needy,  
    and saves the lives of the needy.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 72, 14, 'From oppression and violence he redeems their life;  
    and precious is their blood in his sight.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 72, 15, 'Long may he live!  
    May gold of Sheba be given to him.  
May prayer be made for him continually,  
    and blessings invoked for him all day long.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 72, 16, 'May there be abundance of grain in the land;  
    may it wave on the tops of the mountains;  
    may its fruit be like Lebanon;  
and may people blossom in the cities  
    like the grass of the field.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 72, 17, 'May his name endure forever,  
    his fame continue as long as the sun.  
May all nations be blessed in him;  
    may they pronounce him happy.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 72, 18, 'Blessed be the LORD, the God of Israel,  
    who alone does wondrous things.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 72, 19, 'Blessed be his glorious name forever;  
    may his glory fill the whole earth.  
Amen and Amen.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 72, 20, 'The prayers of David son of Jesse are ended.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 73, 1, 'Truly God is good to the upright,  
    to those who are pure in heart.', 'en', 'NRSV-CE', 'Psalm 73'),
(19, 'Maz', 'Psalms', 73, 2, 'But as for me, my feet had almost stumbled;  
    my steps had nearly slipped.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 73, 3, 'For I was envious of the arrogant;  
    I saw the prosperity of the wicked.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 73, 4, 'For they have no pain;  
    their bodies are sound and sleek.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 73, 5, 'They are not in trouble as others are;  
    they are not plagued like other people.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 73, 6, 'Therefore pride is their necklace;  
    violence covers them like a garment.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 73, 7, 'Their eyes swell out with fatness;  
    their hearts overflow with follies.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 73, 8, 'They scoff and speak with malice;  
    loftily they threaten oppression.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 73, 9, 'They set their mouths against heaven,  
    and their tongues range over the earth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 73, 10, 'Therefore the people turn and praise them,  
    and find no fault in them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 73, 11, 'And they say, "How can God know?  
    Is there knowledge in the Most High?"', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 73, 12, 'Such are the wicked;  
    always at ease, they increase in riches.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 73, 13, 'All in vain I have kept my heart clean  
    and washed my hands in innocence.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 73, 14, 'For all day long I have been plagued,  
    and am punished every morning.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 73, 15, 'If I had said, "I will talk on in this way,"  
    I would have been untrue to the circle of your children.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 73, 16, 'But when I thought how to understand this,  
    it seemed to me a wearisome task,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 73, 17, 'until I went into the sanctuary of God;  
    then I perceived their end.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 73, 18, 'Truly you set them in slippery places;  
    you make them fall to ruin.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 73, 19, 'How they are destroyed in a moment,  
    swept away utterly by terrors!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 73, 20, 'They are like a dream when one awakes;  
    on awaking you despise their phantoms.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 73, 21, 'When my soul was embittered,  
    when I was pricked in heart,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 73, 22, 'I was stupid and ignorant;  
    I was like a brute beast toward you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 73, 23, 'Nevertheless I am continually with you;  
    you hold my right hand.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 73, 24, 'You guide me with your counsel,  
    and afterward you will receive me with honor.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 73, 25, 'Whom have I in heaven but you?  
    And there is nothing on earth that I desire other than you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 73, 26, 'My flesh and my heart may fail,  
    but God is the strength of my heart and my portion forever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 73, 27, 'Indeed, those who are far from you will perish;  
    you put an end to those who are false to you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 73, 28, 'But for me it is good to be near God;  
    I have made the Lord God my refuge,  
    to tell of all your works.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 74, 1, 'O God, why do you cast us off forever?  
    Why does your anger smoke against the sheep of your pasture?', 'en', 'NRSV-CE', 'Psalm 74'),
(19, 'Maz', 'Psalms', 74, 2, 'Remember your congregation, which you acquired long ago,  
    which you redeemed to be the tribe of your heritage.  
    Remember Mount Zion, where you came to dwell.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 74, 3, 'Direct your steps to the perpetual ruins;  
    the enemy has destroyed everything in the sanctuary.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 74, 4, 'Your foes have roared within your holy place;  
    they set up their emblems there.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 74, 5, 'At the upper entrance they hacked  
    the wooden trellis with axes.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 74, 6, 'And then, with hatchets and hammers,  
    they smashed all its carved work.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 74, 7, 'They set your sanctuary on fire;  
    they desecrated the dwelling place of your name,  
    bringing it to the ground.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 74, 8, 'They said to themselves, "We will utterly subdue them";  
    they burned all the meeting places of God in the land.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 74, 9, 'We do not see our emblems;  
    there is no longer any prophet,  
    and there is no one among us who knows how long.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 74, 10, 'How long, O God, is the foe to scoff?  
    Is the enemy to revile your name forever?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 74, 11, 'Why do you hold back your hand;  
    why do you keep your hand in your bosom?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 74, 12, 'Yet God my King is from of old,  
    working salvation in the earth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 74, 13, 'You divided the sea by your might;  
    you broke the heads of the dragons in the waters.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 74, 14, 'You crushed the heads of Leviathan;  
    you gave him as food for the creatures of the wilderness.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 74, 15, 'You cut openings for springs and torrents;  
    you dried up ever-flowing streams.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 74, 16, 'Yours is the day, yours also the night;  
    you established the luminaries and the sun.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 74, 17, 'You have fixed all the bounds of the earth;  
    you made summer and winter.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 74, 18, 'Remember this, O LORD, how the enemy scoffs,  
    and an impious people reviles your name.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 74, 19, 'Do not deliver the soul of your dove to the wild animals;  
    do not forget the life of your poor forever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 74, 20, 'Have regard for your covenant,  
    for the dark places of the land are full of the haunts of violence.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 74, 21, 'Do not let the downtrodden be put to shame;  
    let the poor and needy praise your name.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 74, 22, 'Rise up, O God, plead your cause;  
    remember how the impious scoff at you all day long.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 74, 23, 'Do not forget the clamor of your foes,  
    the uproar of your adversaries that goes up continually.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 75, 1, 'We give thanks to you, O God;  
    we give thanks; your name is near.  
People tell of your wondrous deeds.', 'en', 'NRSV-CE', 'Psalm 75'),
(19, 'Maz', 'Psalms', 75, 2, 'At the set time that I appoint  
    I will judge with equity.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 75, 3, 'When the earth totters, with all its inhabitants,  
    it is I who keep its pillars steady._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 75, 4, 'I say to the boastful, "Do not boast,"  
    and to the wicked, "Do not lift up your horn;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 75, 5, 'do not lift up your horn on high,  
    or speak with insolent neck."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 75, 6, 'For not from the east or from the west  
    and not from the wilderness comes lifting up;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 75, 7, 'but it is God who executes judgment,  
    putting down one and lifting up another.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 75, 8, 'For in the hand of the LORD there is a cup  
    with foaming wine, well mixed;  
he will pour a draught from it,  
    and all the wicked of the earth  
    shall drain it down to the dregs.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 75, 9, 'But I will rejoice forever;  
    I will sing praises to the God of Jacob.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 75, 10, 'All the horns of the wicked I will cut off,  
    but the horns of the righteous shall be exalted.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 76, 1, 'In Judah God is known,  
    his name is great in Israel.', 'en', 'NRSV-CE', 'Psalm 76'),
(19, 'Maz', 'Psalms', 76, 2, 'His abode has been established in Salem,  
    his dwelling place in Zion.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 76, 3, 'There he broke the flashing arrows,  
    the shield, the sword, and the weapons of war._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 76, 4, 'Glorious are you, more majestic  
    than the everlasting mountains.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 76, 5, 'The stouthearted were stripped of their spoil;  
    they sank into sleep;  
none of the troops  
    was able to lift a hand.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 76, 6, 'At your rebuke, O God of Jacob,  
    both rider and horse lay stunned.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 76, 7, 'But you indeed are awesome!  
    Who can stand before you  
    when once your anger is roused?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 76, 8, 'From the heavens you uttered judgment;  
    the earth feared and was still', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 76, 9, 'when God rose up to establish judgment,  
    to save all the oppressed of the earth._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 76, 10, 'Human wrath serves only to praise you,  
    when you bind the last bit of your wrath around you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 76, 11, 'Make vows to the LORD your God, and perform them;  
    let all who are around him bring gifts  
    to the one who is awesome,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 76, 12, 'who cuts off the spirit of princes,  
    who inspires fear in the kings of the earth.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 77, 1, 'I cry aloud to God,  
    aloud to God, that he may hear me.', 'en', 'NRSV-CE', 'Psalm 77'),
(19, 'Maz', 'Psalms', 77, 2, 'In the day of my trouble I seek the Lord;  
    in the night my hand is stretched out without wearying;  
    my soul refuses to be comforted.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 77, 3, 'I think of God, and I moan;  
    I meditate, and my spirit faints._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 77, 4, 'You keep my eyelids from closing;  
    I am so troubled that I cannot speak.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 77, 5, 'I consider the days of old,  
    and remember the years of long ago.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 77, 6, 'I commune with my heart in the night;  
    I meditate and search my spirit:', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 77, 7, '"Will the Lord spurn forever,  
    and never again be favorable?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 77, 8, 'Has his steadfast love ceased forever?  
    Are his promises at an end for all time?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 77, 9, 'Has God forgotten to be gracious?  
    Has he in anger shut up his compassion?"_Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 77, 10, 'And I say, "It is my grief  
    that the right hand of the Most High has changed."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 77, 11, 'I will call to mind the deeds of the LORD;  
    I will remember your wonders of old.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 77, 12, 'I will meditate on all your work,  
    and muse on your mighty deeds.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 77, 13, 'Your way, O God, is holy.  
    What god is so great as our God?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 77, 14, 'You are the God who works wonders;  
    you have displayed your might among the peoples.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 77, 15, 'With your strong arm you redeemed your people,  
    the descendants of Jacob and Joseph._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 77, 16, 'When the waters saw you, O God,  
    when the waters saw you, they were afraid;  
    the very deep trembled.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 77, 17, 'The clouds poured out water;  
    the skies thundered;  
    your arrows flashed on every side.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 77, 18, 'The crash of your thunder was in the whirlwind;  
    your lightnings lit up the world;  
    the earth trembled and shook.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 77, 19, 'Your way was through the sea,  
    your path, through the mighty waters;  
    yet your footprints were unseen.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 77, 20, 'You led your people like a flock  
    by the hand of Moses and Aaron.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 78, 1, 'Give ear, O my people, to my teaching;  
    incline your ears to the words of my mouth.', 'en', 'NRSV-CE', 'Psalm 78'),
(19, 'Maz', 'Psalms', 78, 2, 'I will open my mouth in a parable;  
    I will utter dark sayings from of old,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 3, 'things that we have heard and known,  
    that our ancestors have told us.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 4, 'We will not hide them from their children;  
    we will tell to the coming generation  
the glorious deeds of the LORD, and his might,  
    and the wonders that he has done.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 5, 'He established a decree in Jacob,  
    and appointed a law in Israel,  
which he commanded our ancestors  
    to teach to their children;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 6, 'that the next generation might know them,  
    the children yet unborn,  
and rise up and tell them to their children,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 7, 'so that they should set their hope in God,  
and not forget the works of God,  
    but keep his commandments;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 8, 'and that they should not be like their ancestors,  
    a stubborn and rebellious generation,  
a generation whose heart was not steadfast,  
    whose spirit was not faithful to God.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 9, 'The Ephraimites, armed with the bow,  
    turned back on the day of battle.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 10, 'They did not keep God"s covenant,  
    but refused to walk according to his law.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 11, 'They forgot what he had done,  
    and the miracles that he had shown them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 12, 'In the sight of their ancestors he worked marvels  
    in the land of Egypt, in the fields of Zoan.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 13, 'He divided the sea and let them pass through it,  
    and made the waters stand like a heap.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 14, 'In the daytime he led them with a cloud,  
    and all night long with a fiery light.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 15, 'He split rocks open in the wilderness,  
    and gave them drink abundantly as from the deep.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 16, 'He made streams come out of the rock,  
    and caused waters to flow down like rivers.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 17, 'Yet they sinned still more against him,  
    rebelling against the Most High in the desert.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 18, 'They tested God in their heart  
    by demanding the food they craved.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 19, 'They spoke against God, saying,  
    "Can God spread a table in the wilderness?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 20, 'Even though he struck the rock so that water gushed out  
    and torrents overflowed,  
can he also give bread,  
    or provide meat for his people?"', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 21, 'Therefore, when the LORD heard, he was full of rage;  
    a fire was kindled against Jacob,  
    his anger mounted against Israel,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 22, 'because they had no faith in God,  
    and did not trust his saving power.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 23, 'Yet he commanded the skies above,  
    and opened the doors of heaven;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 24, 'he rained down on them manna to eat,  
    and gave them the grain of heaven.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 25, 'Mortals ate of the bread of angels;  
    he sent them food in abundance.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 26, 'He caused the east wind to blow in the heavens,  
    and by his power he led out the south wind;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 27, 'he rained flesh upon them like dust,  
    winged birds like the sand of the seas;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 28, 'he let them fall within their camp,  
    all around their dwellings.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 29, 'And they ate and were well filled,  
    for he gave them what they craved.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 30, 'But before they had satisfied their craving,  
    while the food was still in their mouths,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 31, 'the anger of God rose against them  
    and he killed the strongest of them,  
    and laid low the flower of Israel.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 32, 'In spite of all this they still sinned;  
    they did not believe in his wonders.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 33, 'So he made their days vanish like a breath,  
    and their years in terror.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 34, 'When he killed them, they sought for him;  
    they repented and sought God earnestly.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 35, 'They remembered that God was their rock,  
    the Most High God their redeemer.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 36, 'But they flattered him with their mouths;  
    they lied to him with their tongues.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 37, 'Their heart was not steadfast toward him;  
    they were not true to his covenant.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 38, 'Yet he, being compassionate,  
    forgave their iniquity,  
    and did not destroy them;  
often he restrained his anger,  
    and did not stir up all his wrath.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 39, 'He remembered that they were but flesh,  
    a wind that passes and does not come again.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 40, 'How often they rebelled against him in the wilderness  
    and grieved him in the desert!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 41, 'They tested God again and again,  
    and provoked the Holy One of Israel.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 42, 'They did not keep in mind his power,  
    or the day when he redeemed them from the foe;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 43, 'when he displayed his signs in Egypt,  
    and his miracles in the fields of Zoan.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 44, 'He turned their rivers to blood,  
    so that they could not drink of their streams.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 45, 'He sent among them swarms of flies, which devoured them,  
    and frogs, which destroyed them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 46, 'He gave their crops to the caterpillar,  
    and the fruit of their labor to the locust.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 47, 'He destroyed their vines with hail,  
    and their sycamores with frost.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 48, 'He gave over their cattle to the hail,  
    and their flocks to thunderbolts.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 49, 'He let loose on them his fierce anger,  
    wrath, indignation, and distress,  
    a company of destroying angels.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 50, 'He made a path for his anger;  
    he did not spare them from death,  
    but gave their lives over to the plague.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 51, 'He struck all the firstborn in Egypt,  
    the first issue of their strength in the tents of Ham.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 52, 'Then he led out his people like sheep,  
    and guided them in the wilderness like a flock.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 53, 'He led them in safety, so that they were not afraid;  
    but the sea overwhelmed their enemies.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 54, 'And he brought them to his holy hill,  
    to the mountain that his right hand had won.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 55, 'He drove out nations before them;  
    he apportioned them for a possession  
    and settled the tribes of Israel in their tents.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 56, 'Yet they tested the Most High God,  
    and rebelled against him.  
    They did not observe his decrees,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 57, 'but turned away and were faithless like their ancestors;  
    they twisted like a treacherous bow.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 58, 'For they provoked him to anger with their high places;  
    they moved him to jealousy with their idols.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 59, 'When God heard, he was full of wrath,  
    and he utterly rejected Israel.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 60, 'He abandoned his dwelling at Shiloh,  
    the tent where he dwelt among mortals,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 61, 'and delivered his power to captivity,  
    his glory to the hand of the foe.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 62, 'He gave his people to the sword,  
    and vented his wrath on his heritage.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 63, 'Fire devoured their young men,  
    and their girls had no marriage song.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 64, 'Their priests fell by the sword,  
    and their widows made no lamentation.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 65, 'Then the Lord awoke as from sleep,  
    like a warrior shouting because of wine.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 66, 'He put his adversaries to rout;  
    he put them to everlasting disgrace.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 67, 'He rejected the tent of Joseph,  
    he did not choose the tribe of Ephraim;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 68, 'but he chose the tribe of Judah,  
    Mount Zion, which he loves.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 69, 'He built his sanctuary like the high heavens,  
    like the earth, which he has founded forever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 70, 'He chose his servant David,  
    and took him from the sheepfolds;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 71, 'from tending the nursing ewes he brought him  
    to be the shepherd of his people Jacob,  
    of Israel, his inheritance.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 78, 72, 'With upright heart he tended them,  
    and guided them with skillful hand.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 79, 1, 'O God, the nations have come into your inheritance;  
    they have defiled your holy temple;  
    they have laid Jerusalem in ruins.', 'en', 'NRSV-CE', 'Psalm 79'),
(19, 'Maz', 'Psalms', 79, 2, 'They have given the bodies of your servants  
    to the birds of the air for food,  
    the flesh of your faithful to the wild animals of the earth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 79, 3, 'They have poured out their blood like water  
    all around Jerusalem,  
    and there was no one to bury them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 79, 4, 'We have become a taunt to our neighbors,  
    mocked and derided by those around us.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 79, 5, 'How long, O LORD? Will you be angry forever?  
    Will your jealous wrath burn like fire?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 79, 6, 'Pour out your anger on the nations  
    that do not know you,  
and on the kingdoms  
    that do not call on your name.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 79, 7, 'For they have devoured Jacob  
    and laid waste his habitation.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 79, 8, 'Do not remember against us the iniquities of our ancestors;  
    let your compassion come speedily to meet us,  
    for we are brought very low.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 79, 9, 'Help us, O God of our salvation,  
    for the glory of your name;  
deliver us, and forgive our sins,  
    for your name"s sake.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 79, 10, 'Why should the nations say,  
    "Where is their God?"  
Let the avenging of the outpoured blood of your servants  
    be known among the nations before our eyes.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 79, 11, 'Let the groans of the prisoners come before you;  
    according to your great power preserve those doomed to die.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 79, 12, 'Return sevenfold into the bosom of our neighbors  
    the taunts with which they taunted you, O Lord!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 79, 13, 'Then we your people, the flock of your pasture,  
    will give thanks to you forever;  
    from generation to generation we will recount your praise.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 80, 1, 'Give ear, O Shepherd of Israel,  
    you who lead Joseph like a flock!  
You who are enthroned upon the cherubim, shine forth', 'en', 'NRSV-CE', 'Psalm 80'),
(19, 'Maz', 'Psalms', 80, 2, 'before Ephraim and Benjamin and Manasseh.  
Stir up your might,  
    and come to save us!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 80, 3, 'Restore us, O God;  
    let your face shine, that we may be saved.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 80, 4, 'O LORD God of hosts,  
    how long will you be angry with your people"s prayers?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 80, 5, 'You have fed them with the bread of tears,  
    and given them tears to drink in full measure.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 80, 6, 'You make us the scorn of our neighbors;  
    our enemies laugh among themselves.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 80, 7, 'Restore us, O God of hosts;  
    let your face shine, that we may be saved.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 80, 8, 'You brought a vine out of Egypt;  
    you drove out the nations and planted it.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 80, 9, 'You cleared the ground for it;  
    it took deep root and filled the land.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 80, 10, 'The mountains were covered with its shade,  
    the mighty cedars with its branches;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 80, 11, 'it sent out its branches to the sea,  
    and its shoots to the River.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 80, 12, 'Why then have you broken down its walls,  
    so that all who pass along the way pluck its fruit?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 80, 13, 'The boar from the forest ravages it,  
    and all that move in the field feed on it.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 80, 14, 'Turn again, O God of hosts;  
    look down from heaven, and see;  
have regard for this vine,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 80, 15, 'the stock that your right hand planted.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 80, 16, 'They have burned it with fire, they have cut it down;  
    may they perish at the rebuke of your countenance.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 80, 17, 'But let your hand be upon the one at your right hand,  
    the one whom you made strong for yourself.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 80, 18, 'Then we will never turn back from you;  
    give us life, and we will call on your name.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 80, 19, 'Restore us, O LORD God of hosts;  
    let your face shine, that we may be saved.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 81, 1, 'Sing aloud to God our strength;  
    shout for joy to the God of Jacob.', 'en', 'NRSV-CE', 'Psalm 81'),
(19, 'Maz', 'Psalms', 81, 2, 'Raise a song, sound the tambourine,  
    the sweet lyre with the harp.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 81, 3, 'Blow the trumpet at the new moon,  
    at the full moon, on our festal day.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 81, 4, 'For it is a statute for Israel,  
    an ordinance of the God of Jacob.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 81, 5, 'He made it a decree in Joseph,  
    when he went out over the land of Egypt.
I hear a voice I had not known:', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 81, 6, '"I relieved your shoulder of the burden;  
    your hands were freed from the basket.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 81, 7, 'In distress you called, and I rescued you;  
    I answered you in the secret place of thunder;  
    I tested you at the waters of Meribah._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 81, 8, 'Hear, O my people, while I admonish you;  
    O Israel, if you would but listen to me!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 81, 9, 'There shall be no strange god among you;  
    you shall not bow down to a foreign god.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 81, 10, 'I am the LORD your God,  
    who brought you up out of the land of Egypt.  
    Open your mouth wide and I will fill it.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 81, 11, '"But my people did not listen to my voice;  
    Israel would not submit to me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 81, 12, 'So I gave them over to their stubborn hearts,  
    to follow their own counsels.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 81, 13, 'O that my people would listen to me,  
    that Israel would walk in my ways!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 81, 14, 'Then I would quickly subdue their enemies,  
    and turn my hand against their foes.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 81, 15, 'Those who hate the LORD would cringe before him,  
    and their doom would last forever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 81, 16, 'I would feed you with the finest of the wheat,  
    and with honey from the rock I would satisfy you."', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 82, 1, 'God has taken his place in the divine council;  
    in the midst of the gods he holds judgment:', 'en', 'NRSV-CE', 'Psalm 82'),
(19, 'Maz', 'Psalms', 82, 2, '"How long will you judge unjustly  
    and show partiality to the wicked?_Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 82, 3, 'Give justice to the weak and the orphan;  
    maintain the right of the lowly and the destitute.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 82, 4, 'Rescue the weak and the needy;  
    deliver them from the hand of the wicked."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 82, 5, 'They have neither knowledge nor understanding,  
    they walk around in darkness;  
    all the foundations of the earth are shaken.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 82, 6, 'I say, "You are gods,  
    children of the Most High, all of you;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 82, 7, 'nevertheless, you shall die like mortals,  
    and fall like any prince."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 82, 8, 'Rise up, O God, judge the earth;  
    for all the nations belong to you!', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 83, 1, 'O God, do not keep silence;  
    do not hold your peace or be still, O God!', 'en', 'NRSV-CE', 'Psalm 83'),
(19, 'Maz', 'Psalms', 83, 2, 'Even now your enemies are in tumult;  
    those who hate you have raised their heads.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 83, 3, 'They lay crafty plans against your people;  
    they consult together against those you protect.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 83, 4, 'They say, "Come, let us wipe them out as a nation;  
    let the name of Israel be remembered no more."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 83, 5, 'They conspire with one accord;  
    against you they make a covenant--', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 83, 6, 'the tents of Edom and the Ishmaelites,  
    Moab and the Hagrites,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 83, 7, 'Gebal and Ammon and Amalek,  
    Philistia with the inhabitants of Tyre;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 83, 8, 'Assyria also has joined them;  
    they are the strong arm of the children of Lot._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 83, 9, 'Do to them as you did to Midian,  
    as to Sisera and Jabin at the Wadi Kishon,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 83, 10, 'who were destroyed at En-dor,  
    who became dung for the ground.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 83, 11, 'Make their nobles like Oreb and Zeeb,  
    all their princes like Zebah and Zalmunna,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 83, 12, 'who said, "Let us take the pastures of God  
    for our own possession."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 83, 13, 'O my God, make them like whirling dust,  
    like chaff before the wind.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 83, 14, 'As fire consumes the forest,  
    as the flame sets the mountains ablaze,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 83, 15, 'so pursue them with your tempest  
    and terrify them with your hurricane.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 83, 16, 'Fill their faces with shame,  
    so that they may seek your name, O LORD.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 83, 17, 'Let them be put to shame and dismayed forever;  
    let them perish in disgrace.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 83, 18, 'Let them know that you alone,  
    whose name is the LORD,  
    are the Most High over all the earth.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 84, 1, 'How lovely is your dwelling place,  
    O LORD of hosts!', 'en', 'NRSV-CE', 'Psalm 84'),
(19, 'Maz', 'Psalms', 84, 2, 'My soul longs, indeed it faints  
    for the courts of the LORD;  
my heart and my flesh sing for joy  
    to the living God.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 84, 3, 'Even the sparrow finds a home,  
    and the swallow a nest for herself,  
    where she may lay her young,  
at your altars, O LORD of hosts,  
    my King and my God.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 84, 4, 'Happy are those who live in your house,  
    ever singing your praise._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 84, 5, 'Happy are those whose strength is in you,  
    in whose heart are the highways to Zion.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 84, 6, 'As they go through the valley of Baca  
    they make it a place of springs;  
    the early rain also covers it with pools.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 84, 7, 'They go from strength to strength;  
    the God of gods will be seen in Zion.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 84, 8, 'O LORD God of hosts, hear my prayer;  
    give ear, O God of Jacob!_Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 84, 9, 'Behold our shield, O God;  
    look on the face of your anointed.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 84, 10, 'For a day in your courts is better  
    than a thousand elsewhere.  
I would rather be a doorkeeper in the house of my God  
    than live in the tents of wickedness.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 84, 11, 'For the LORD God is a sun and shield;  
    he bestows favor and honor.  
No good thing does the LORD withhold  
    from those who walk uprightly.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 84, 12, 'O LORD of hosts,  
    happy is everyone who trusts in you.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 85, 1, 'LORD, you were favorable to your land;  
    you restored the fortunes of Jacob.', 'en', 'NRSV-CE', 'Psalm 85'),
(19, 'Maz', 'Psalms', 85, 2, 'You forgave the iniquity of your people;  
    you pardoned all their sin._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 85, 3, 'You withdrew all your wrath;  
    you turned from your hot anger.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 85, 4, 'Restore us again, O God of our salvation,  
    and put away your indignation toward us.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 85, 5, 'Will you be angry with us forever?  
    Will you prolong your anger to all generations?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 85, 6, 'Will you not revive us again,  
    so that your people may rejoice in you?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 85, 7, 'Show us your steadfast love, O LORD,  
    and grant us your salvation.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 85, 8, 'Let me hear what God the LORD will speak,  
    for he will speak peace to his people,  
    to his faithful, to those who turn to him in their hearts.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 85, 9, 'Surely his salvation is at hand for those who fear him,  
    that his glory may dwell in our land.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 85, 10, 'Steadfast love and faithfulness will meet;  
    righteousness and peace will kiss each other.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 85, 11, 'Faithfulness will spring up from the ground,  
    and righteousness will look down from the sky.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 85, 12, 'The LORD will give what is good,  
    and our land will yield its increase.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 85, 13, 'Righteousness will go before him,  
    and will make a path for his steps.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 86, 1, 'Incline your ear, O LORD, and answer me,  
    for I am poor and needy.', 'en', 'NRSV-CE', 'Psalm 86'),
(19, 'Maz', 'Psalms', 86, 2, 'Preserve my life, for I am devoted to you;  
    save your servant who trusts in you.  
You are my God;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 86, 3, 'be gracious to me, O Lord,  
    for to you do I cry all day long.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 86, 4, 'Gladden the soul of your servant,  
    for to you, O Lord, I lift up my soul.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 86, 5, 'For you, O Lord, are good and forgiving,  
    abounding in steadfast love to all who call on you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 86, 6, 'Give ear, O LORD, to my prayer;  
    listen to my cry of supplication.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 86, 7, 'In the day of my trouble I call on you,  
    for you will answer me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 86, 8, 'There is none like you among the gods, O Lord,  
    nor are there any works like yours.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 86, 9, 'All the nations you have made shall come  
    and bow down before you, O Lord,  
    and shall glorify your name.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 86, 10, 'For you are great and do wondrous things;  
    you alone are God.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 86, 11, 'Teach me your way, O LORD,  
    that I may walk in your truth;  
    give me an undivided heart to revere your name.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 86, 12, 'I give thanks to you, O Lord my God, with my whole heart,  
    and I will glorify your name forever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 86, 13, 'For great is your steadfast love toward me;  
    you have delivered my soul from the depths of Sheol.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 86, 14, 'O God, the insolent rise up against me;  
    a band of ruffians seeks my life,  
    and they do not set you before them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 86, 15, 'But you, O Lord, are a God merciful and gracious,  
    slow to anger and abounding in steadfast love and faithfulness.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 86, 16, 'Turn to me and be gracious to me;  
    give your strength to your servant;  
    save the child of your serving girl.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 86, 17, 'Show me a sign of your favor,  
    so that those who hate me may see it and be put to shame,  
    because you, LORD, have helped me and comforted me.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 87, 1, 'On the holy mount stands the city he founded;', 'en', 'NRSV-CE', 'Psalm 87'),
(19, 'Maz', 'Psalms', 87, 2, 'the LORD loves the gates of Zion  
    more than all the dwellings of Jacob.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 87, 3, 'Glorious things are spoken of you,  
    O city of God._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 87, 4, 'Among those who know me I mention Rahab and Babylon;  
    Philistia too, and Tyre, with Ethiopia--  
    "This one was born there," they say.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 87, 5, 'And of Zion it shall be said,  
    "This one and that one were born in it";  
    for the Most High himself will establish it.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 87, 6, 'The LORD records, as he registers the peoples,  
    "This one was born there."_Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 87, 7, 'Singers and dancers alike say,  
    "All my springs are in you."', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 88, 1, 'O LORD, God of my salvation,  
    when, at night, I cry out in your presence,', 'en', 'NRSV-CE', 'Psalm 88'),
(19, 'Maz', 'Psalms', 88, 2, 'let my prayer come before you;  
    incline your ear to my cry.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 88, 3, 'For my soul is full of troubles,  
    and my life draws near to Sheol.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 88, 4, 'I am counted among those who go down to the Pit;  
    I am like those who have no help,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 88, 5, 'like those forsaken among the dead,  
    like the slain that lie in the grave,  
like those whom you remember no more,  
    for they are cut off from your hand.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 88, 6, 'You have put me in the depths of the Pit,  
    in the regions dark and deep.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 88, 7, 'Your wrath lies heavy upon me,  
    and you overwhelm me with all your waves._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 88, 8, 'You have caused my companions to shun me;  
    you have made me a thing of horror to them.  
I am shut in so that I cannot escape;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 88, 9, 'my eye grows dim through sorrow.  
Every day I call on you, O LORD;  
    I spread out my hands to you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 88, 10, 'Do you work wonders for the dead?  
    Do the shades rise up to praise you?_Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 88, 11, 'Is your steadfast love declared in the grave,  
    or your faithfulness in Abaddon?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 88, 12, 'Are your wonders known in the darkness,  
    or your saving help in the land of forgetfulness?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 88, 13, 'But I, O LORD, cry out to you;  
    in the morning my prayer comes before you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 88, 14, 'O LORD, why do you cast me off?  
    Why do you hide your face from me?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 88, 15, 'Wretched and close to death from my youth up,  
    I suffer your terrors; I am desperate.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 88, 16, 'Your wrath has swept over me;  
    your dread assaults destroy me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 88, 17, 'They surround me like a flood all day long;  
    from all sides they close in on me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 88, 18, 'You have caused friend and neighbor to shun me;  
    my companions are in darkness.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 89, 1, 'I will sing of your steadfast love, O LORD, forever;  
    with my mouth I will proclaim your faithfulness to all generations.', 'en', 'NRSV-CE', 'Psalm 89'),
(19, 'Maz', 'Psalms', 89, 2, 'I declare that your steadfast love is established forever;  
    your faithfulness is as firm as the heavens.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 3, 'You said, "I have made a covenant with my chosen one,  
    I have sworn to my servant David:', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 4, '"I will establish your descendants forever,  
    and build your throne for all generations.""_Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 5, 'Let the heavens praise your wonders, O LORD,  
    your faithfulness in the assembly of the holy ones.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 6, 'For who in the skies can be compared to the LORD?  
    Who among the heavenly beings is like the LORD,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 7, 'a God feared in the council of the holy ones,  
    great and awesome above all that are around him?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 8, 'O LORD God of hosts,  
    who is as mighty as you, O LORD?  
    Your faithfulness surrounds you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 9, 'You rule the raging of the sea;  
    when its waves rise, you still them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 10, 'You crushed Rahab like a carcass;  
    you scattered your enemies with your mighty arm.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 11, 'The heavens are yours, the earth also is yours;  
    the world and all that is in it--you have founded them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 12, 'The north and the south--you created them;  
    Tabor and Hermon joyously praise your name.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 13, 'You have a mighty arm;  
    strong is your hand, high your right hand.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 14, 'Righteousness and justice are the foundation of your throne;  
    steadfast love and faithfulness go before you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 15, 'Happy are the people who know the festal shout,  
    who walk, O LORD, in the light of your countenance;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 16, 'they exult in your name all day long,  
    and extol your righteousness.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 17, 'For you are the glory of their strength;  
    by your favor our horn is exalted.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 18, 'For our shield belongs to the LORD,  
    our king to the Holy One of Israel.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 19, 'Then you spoke in a vision to your faithful one, and said:  
    "I have set the crown on one who is mighty,  
    I have exalted one chosen from the people.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 20, 'I have found my servant David;  
    with my holy oil I have anointed him;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 21, 'my hand shall always remain with him;  
    my arm also shall strengthen him.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 22, 'The enemy shall not outwit him,  
    the wicked shall not humble him.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 23, 'I will crush his foes before him  
    and strike down those who hate him.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 24, 'My faithfulness and steadfast love shall be with him;  
    and in my name his horn shall be exalted.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 25, 'I will set his hand on the sea  
    and his right hand on the rivers.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 26, 'He shall cry to me, "You are my Father,  
    my God, and the Rock of my salvation!"', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 27, 'I will make him the firstborn,  
    the highest of the kings of the earth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 28, 'Forever I will keep my steadfast love for him,  
    and my covenant with him will stand firm.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 29, 'I will establish his line forever,  
    and his throne as long as the heavens endure.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 30, 'If his children forsake my law  
    and do not walk according to my ordinances,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 31, 'if they violate my statutes  
    and do not keep my commandments,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 32, 'then I will punish their transgression with the rod  
    and their iniquity with scourges;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 33, 'but I will not remove from him my steadfast love,  
    or be false to my faithfulness.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 34, 'I will not violate my covenant,  
    or alter the word that went forth from my lips.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 35, 'Once and for all I have sworn by my holiness;  
    I will not lie to David.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 36, 'His line shall continue forever,  
    and his throne endure before me like the sun.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 37, 'It shall be established forever like the moon,  
    an enduring witness in the skies."_Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 38, 'But now you have spurned and rejected him;  
    you are full of wrath against your anointed.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 39, 'You have renounced the covenant with your servant;  
    you have defiled his crown in the dust.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 40, 'You have broken through all his walls;  
    you have laid his strongholds in ruins.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 41, 'All who pass by plunder him;  
    he has become the scorn of his neighbors.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 42, 'You have exalted the right hand of his foes;  
    you have made all his enemies rejoice.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 43, 'Moreover, you have turned back the edge of his sword,  
    and you have not supported him in battle.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 44, 'You have removed the scepter from his hand,  
    and hurled his throne to the ground.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 45, 'You have cut short the days of his youth;  
    you have covered him with shame._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 46, 'How long, O LORD? Will you hide yourself forever?  
    How long will your wrath burn like fire?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 47, 'Remember how short my time is--  
    for what vanity you have created all mortals!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 48, 'Who can live and never see death?  
    Who can escape the power of Sheol?_Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 49, 'Lord, where is your steadfast love of old,  
    which by your faithfulness you swore to David?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 50, 'Remember, O Lord, how your servant is taunted;  
    how I bear in my bosom the insults of the peoples,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 51, 'with which your enemies taunt, O LORD,  
    with which they taunted the footsteps of your anointed.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 89, 52, 'Blessed be the LORD forever.  
Amen and Amen.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 90, 1, 'Lord, you have been our dwelling place  
    in all generations.', 'en', 'NRSV-CE', 'Psalm 90'),
(19, 'Maz', 'Psalms', 90, 2, 'Before the mountains were brought forth,  
    or ever you had formed the earth and the world,  
    from everlasting to everlasting you are God.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 90, 3, 'You turn us back to dust,  
    and say, "Turn back, you mortals."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 90, 4, 'For a thousand years in your sight  
    are like yesterday when it is past,  
    or like a watch in the night.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 90, 5, 'You sweep them away; they are like a dream,  
    like grass that is renewed in the morning;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 90, 6, 'in the morning it flourishes and is renewed;  
    in the evening it fades and withers.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 90, 7, 'For we are consumed by your anger;  
    by your wrath we are overwhelmed.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 90, 8, 'You have set our iniquities before you,  
    our secret sins in the light of your countenance.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 90, 9, 'For all our days pass away under your wrath;  
    our years come to an end like a sigh.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 90, 10, 'The days of our life are seventy years,  
    or perhaps eighty, if we are strong;  
even then their span is only toil and trouble;  
    they are soon gone, and we fly away.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 90, 11, 'Who considers the power of your anger?  
    Your wrath is as great as the fear that is due you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 90, 12, 'So teach us to count our days  
    that we may gain a wise heart.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 90, 13, 'Turn, O LORD! How long?  
    Have compassion on your servants!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 90, 14, 'Satisfy us in the morning with your steadfast love,  
    so that we may rejoice and be glad all our days.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 90, 15, 'Make us glad as many days as you have afflicted us,  
    and as many years as we have seen evil.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 90, 16, 'Let your work be manifest to your servants,  
    and your glorious power to their children.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 90, 17, 'Let the favor of the Lord our God be upon us,  
    and prosper for us the work of our hands--  
    O prosper the work of our hands!', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 91, 1, 'You who live in the shelter of the Most High,  
    who abide in the shadow of the Almighty,', 'en', 'NRSV-CE', 'Psalm 91'),
(19, 'Maz', 'Psalms', 91, 2, 'will say to the LORD, "My refuge and my fortress;  
    my God, in whom I trust."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 91, 3, 'For he will deliver you from the snare of the fowler  
    and from the deadly pestilence;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 91, 4, 'he will cover you with his pinions,  
    and under his wings you will find refuge;  
    his faithfulness is a shield and buckler.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 91, 5, 'You will not fear the terror of the night,  
    or the arrow that flies by day,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 91, 6, 'or the pestilence that stalks in darkness,  
    or the destruction that wastes at noonday.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 91, 7, 'A thousand may fall at your side,  
    ten thousand at your right hand,  
    but it will not come near you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 91, 8, 'You will only look with your eyes  
    and see the punishment of the wicked.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 91, 9, 'Because you have made the LORD your refuge,  
    the Most High your dwelling place,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 91, 10, 'no evil shall befall you,  
    no scourge come near your tent.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 91, 11, 'For he will command his angels concerning you  
    to guard you in all your ways.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 91, 12, 'On their hands they will bear you up,  
    so that you will not dash your foot against a stone.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 91, 13, 'You will tread on the lion and the adder,  
    the young lion and the serpent you will trample under foot.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 91, 14, 'Those who love me, I will deliver;  
    I will protect those who know my name.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 91, 15, 'When they call to me, I will answer them;  
    I will be with them in trouble,  
    I will rescue them and honor them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 91, 16, 'With long life I will satisfy them,  
    and show them my salvation.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 92, 1, 'It is good to give thanks to the LORD,  
    to sing praises to your name, O Most High;', 'en', 'NRSV-CE', 'Psalm 92'),
(19, 'Maz', 'Psalms', 92, 2, 'to declare your steadfast love in the morning,  
    and your faithfulness by night,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 92, 3, 'to the music of the lute and the harp,  
    to the melody of the lyre.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 92, 4, 'For you, O LORD, have made me glad by your work;  
    at the works of your hands I sing for joy.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 92, 5, 'How great are your works, O LORD!  
    Your thoughts are very deep!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 92, 6, 'The dullard cannot know,  
    the stupid cannot understand this:', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 92, 7, 'though the wicked sprout like grass  
    and all evildoers flourish,  
they are doomed to destruction forever,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 92, 8, 'but you, O LORD, are on high forever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 92, 9, 'For your enemies, O LORD,  
    for your enemies shall perish;  
    all evildoers shall be scattered.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 92, 10, 'But you have exalted my horn like that of the wild ox;  
    you have poured over me fresh oil.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 92, 11, 'My eyes have seen the downfall of my enemies;  
    my ears have heard the doom of my evil assailants.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 92, 12, 'The righteous flourish like the palm tree,  
    and grow like a cedar in Lebanon.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 92, 13, 'They are planted in the house of the LORD;  
    they flourish in the courts of our God.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 92, 14, 'In old age they still produce fruit;  
    they are always green and full of sap,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 92, 15, 'showing that the LORD is upright;  
    he is my rock, and there is no unrighteousness in him.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 93, 1, 'The LORD is king, he is robed in majesty;  
    the LORD is robed, he is girded with strength.  
He has established the world; it shall never be moved;', 'en', 'NRSV-CE', 'Psalm 93'),
(19, 'Maz', 'Psalms', 93, 2, 'your throne is established from of old;  
    you are from everlasting.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 93, 3, 'The floods have lifted up, O LORD,  
    the floods have lifted up their voice;  
    the floods lift up their roaring.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 93, 4, 'More majestic than the thunders of mighty waters,  
    more majestic than the waves of the sea,  
    majestic on high is the LORD!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 93, 5, 'Your decrees are very sure;  
    holiness befits your house,  
    O LORD, forevermore.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 94, 1, 'O LORD, you God of vengeance,  
    you God of vengeance, shine forth!', 'en', 'NRSV-CE', 'Psalm 94'),
(19, 'Maz', 'Psalms', 94, 2, 'Rise up, O judge of the earth;  
    give to the proud what they deserve!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 94, 3, 'O LORD, how long shall the wicked,  
    how long shall the wicked exult?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 94, 4, 'They pour out their arrogant words;  
    all the evildoers boast.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 94, 5, 'They crush your people, O LORD,  
    and afflict your heritage.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 94, 6, 'They kill the widow and the stranger,  
    they murder the orphan,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 94, 7, 'and they say, "The LORD does not see;  
    the God of Jacob does not perceive."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 94, 8, 'Understand, O dullest of the people;  
    fools, when will you be wise?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 94, 9, 'He who planted the ear, does he not hear?  
He who formed the eye, does he not see?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 94, 10, 'He who disciplines the nations,  
he who teaches knowledge to humankind,  
    does he not chastise?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 94, 11, 'The LORD knows our thoughts,  
    that they are but an empty breath.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 94, 12, 'Happy are those whom you discipline, O LORD,  
    and whom you teach out of your law,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 94, 13, 'giving them respite from days of trouble,  
    until a pit is dug for the wicked.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 94, 14, 'For the LORD will not forsake his people;  
    he will not abandon his heritage;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 94, 15, 'for justice will return to the righteous,  
    and all the upright in heart will follow it.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 94, 16, 'Who rises up for me against the wicked?  
    Who stands up for me against evildoers?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 94, 17, 'If the LORD had not been my help,  
    my soul would soon have lived in the land of silence.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 94, 18, 'When I thought, "My foot is slipping,"  
    your steadfast love, O LORD, held me up.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 94, 19, 'When the cares of my heart are many,  
    your consolations cheer my soul.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 94, 20, 'Can wicked rulers be allied with you,  
    those who contrive mischief by statute?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 94, 21, 'They band together against the life of the righteous,  
    and condemn the innocent to death.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 94, 22, 'But the LORD has become my stronghold,  
    and my God the rock of my refuge.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 94, 23, 'He will repay them for their iniquity  
    and wipe them out for their wickedness;  
    the LORD our God will wipe them out.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 95, 1, 'O come, let us sing to the LORD;  
    let us make a joyful noise to the rock of our salvation!', 'en', 'NRSV-CE', 'Psalm 95'),
(19, 'Maz', 'Psalms', 95, 2, 'Let us come into his presence with thanksgiving;  
    let us make a joyful noise to him with songs of praise!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 95, 3, 'For the LORD is a great God,  
    and a great King above all gods.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 95, 4, 'In his hand are the depths of the earth;  
    the heights of the mountains are his also.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 95, 5, 'The sea is his, for he made it,  
    and the dry land, which his hands have formed.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 95, 6, 'O come, let us worship and bow down,  
    let us kneel before the LORD, our Maker!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 95, 7, 'For he is our God,  
    and we are the people of his pasture,  
    and the sheep of his hand.
O that today you would listen to his voice!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 95, 8, 'Do not harden your hearts, as at Meribah,  
    as on the day at Massah in the wilderness,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 95, 9, 'when your ancestors tested me,  
    and put me to the proof, though they had seen my work.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 95, 10, 'For forty years I loathed that generation  
    and said, "They are a people whose hearts go astray,  
    and they do not regard my ways."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 95, 11, 'Therefore in my anger I swore,  
    "They shall not enter my rest."', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 96, 1, 'O sing to the LORD a new song;  
    sing to the LORD, all the earth.', 'en', 'NRSV-CE', 'Psalm 96'),
(19, 'Maz', 'Psalms', 96, 2, 'Sing to the LORD, bless his name;  
    tell of his salvation from day to day.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 96, 3, 'Declare his glory among the nations,  
    his marvelous works among all the peoples.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 96, 4, 'For great is the LORD, and greatly to be praised;  
    he is to be revered above all gods.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 96, 5, 'For all the gods of the peoples are idols,  
    but the LORD made the heavens.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 96, 6, 'Honor and majesty are before him;  
    strength and beauty are in his sanctuary.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 96, 7, 'Ascribe to the LORD, O families of the peoples,  
    ascribe to the LORD glory and strength.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 96, 8, 'Ascribe to the LORD the glory due his name;  
    bring an offering, and come into his courts.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 96, 9, 'Worship the LORD in holy splendor;  
    tremble before him, all the earth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 96, 10, 'Say among the nations, "The LORD is king!  
    The world is firmly established; it shall never be moved.  
    He will judge the peoples with equity."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 96, 11, 'Let the heavens be glad, and let the earth rejoice;  
    let the sea roar, and all that fills it;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 96, 12, 'let the field exult, and everything in it.  
Then shall all the trees of the forest sing for joy', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 96, 13, 'before the LORD; for he is coming,  
    for he is coming to judge the earth.  
He will judge the world with righteousness,  
    and the peoples with his truth.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 97, 1, 'The LORD is king! Let the earth rejoice;  
    let the many coastlands be glad!', 'en', 'NRSV-CE', 'Psalm 97'),
(19, 'Maz', 'Psalms', 97, 2, 'Clouds and thick darkness are all around him;  
    righteousness and justice are the foundation of his throne.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 97, 3, 'Fire goes before him,  
    and consumes his adversaries on every side.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 97, 4, 'His lightnings light up the world;  
    the earth sees and trembles.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 97, 5, 'The mountains melt like wax before the LORD,  
    before the Lord of all the earth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 97, 6, 'The heavens proclaim his righteousness;  
    and all the peoples behold his glory.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 97, 7, 'All worshipers of images are put to shame,  
    those who make their boast in worthless idols;  
    all gods bow down before him.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 97, 8, 'Zion hears and is glad,  
    and the towns of Judah rejoice,  
    because of your judgments, O God.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 97, 9, 'For you, O LORD, are most high over all the earth;  
    you are exalted far above all gods.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 97, 10, 'The LORD loves those who hate evil;  
    he guards the lives of his faithful;  
    he rescues them from the hand of the wicked.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 97, 11, 'Light dawns for the righteous,  
    and joy for the upright in heart.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 97, 12, 'Rejoice in the LORD, O you righteous,  
    and give thanks to his holy name!', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 98, 1, 'O sing to the LORD a new song,  
    for he has done marvelous things.  
His right hand and his holy arm  
    have gotten him victory.', 'en', 'NRSV-CE', 'Psalm 98'),
(19, 'Maz', 'Psalms', 98, 2, 'The LORD has made known his victory;  
    he has revealed his vindication in the sight of the nations.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 98, 3, 'He has remembered his steadfast love and faithfulness  
    to the house of Israel.  
All the ends of the earth have seen  
    the victory of our God.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 98, 4, 'Make a joyful noise to the LORD, all the earth;  
    break forth into joyous song and sing praises.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 98, 5, 'Sing praises to the LORD with the lyre,  
    with the lyre and the sound of melody.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 98, 6, 'With trumpets and the sound of the horn  
    make a joyful noise before the King, the LORD.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 98, 7, 'Let the sea roar, and all that fills it;  
    the world and those who live in it.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 98, 8, 'Let the floods clap their hands;  
    let the hills sing together for joy', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 98, 9, 'at the presence of the LORD, for he is coming  
    to judge the earth.  
He will judge the world with righteousness,  
    and the peoples with equity.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 99, 1, 'The LORD is king; let the peoples tremble!  
    He sits enthroned upon the cherubim; let the earth quake!', 'en', 'NRSV-CE', 'Psalm 99'),
(19, 'Maz', 'Psalms', 99, 2, 'The LORD is great in Zion;  
    he is exalted over all the peoples.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 99, 3, 'Let them praise your great and awesome name.  
    Holy is he!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 99, 4, 'Mighty King, lover of justice,  
    you have established equity;  
you have executed justice  
    and righteousness in Jacob.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 99, 5, 'Extol the LORD our God;  
    worship at his footstool.  
    Holy is he!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 99, 6, 'Moses and Aaron were among his priests,  
    Samuel also was among those who called on his name.  
    They cried to the LORD, and he answered them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 99, 7, 'He spoke to them in the pillar of cloud;  
    they kept his decrees,  
    and the statutes that he gave them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 99, 8, 'O LORD our God, you answered them;  
    you were a forgiving God to them,  
    but an avenger of their wrongdoings.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 99, 9, 'Extol the LORD our God,  
    and worship at his holy mountain;  
    for the LORD our God is holy.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 100, 1, 'Make a joyful noise to the LORD, all the earth.', 'en', 'NRSV-CE', 'Psalm 100'),
(19, 'Maz', 'Psalms', 100, 2, 'Worship the LORD with gladness;  
    come into his presence with singing.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 100, 3, 'Know that the LORD is God.  
    It is he that made us, and we are his;  
    we are his people, and the sheep of his pasture.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 100, 4, 'Enter his gates with thanksgiving,  
    and his courts with praise.  
    Give thanks to him, bless his name.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 100, 5, 'For the LORD is good;  
    his steadfast love endures forever,  
    and his faithfulness to all generations.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 101, 1, 'I will sing of loyalty and of justice;  
    to you, O LORD, I will sing.', 'en', 'NRSV-CE', 'Psalm 101'),
(19, 'Maz', 'Psalms', 101, 2, 'I will study the way that is blameless.  
    When shall I attain it?
I will walk with integrity of heart  
    within my house;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 101, 3, 'I will not set before my eyes  
    anything that is base.
I hate the work of those who fall away;  
    it shall not cling to me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 101, 4, 'Perverseness of heart shall be far from me;  
    I will know nothing of evil.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 101, 5, 'One who secretly slanders a neighbor  
    I will destroy.  
A haughty look and an arrogant heart  
    I will not tolerate.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 101, 6, 'I will look with favor on the faithful in the land,  
    so that they may live with me;  
whoever walks in the way that is blameless  
    shall minister to me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 101, 7, 'No one who practices deceit  
    shall remain in my house;  
no one who utters lies  
    shall continue in my presence.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 101, 8, 'Morning by morning I will destroy  
    all the wicked in the land,  
cutting off all evildoers  
    from the city of the LORD.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 102, 1, 'Hear my prayer, O LORD;  
    let my cry come to you.', 'en', 'NRSV-CE', 'Psalm 102'),
(19, 'Maz', 'Psalms', 102, 2, 'Do not hide your face from me  
    in the day of my distress.  
Incline your ear to me;  
    answer me speedily in the day when I call.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 102, 3, 'For my days pass away like smoke,  
    and my bones burn like a furnace.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 102, 4, 'My heart is stricken and withered like grass;  
    I am too wasted to eat my bread.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 102, 5, 'Because of my loud groaning  
    my bones cling to my skin.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 102, 6, 'I am like an owl of the wilderness,  
    like a little owl of the waste places.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 102, 7, 'I lie awake;  
    I am like a lonely bird on the housetop.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 102, 8, 'All day long my enemies taunt me;  
    those who deride me use my name for a curse.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 102, 9, 'For I eat ashes like bread,  
    and mingle tears with my drink,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 102, 10, 'because of your indignation and anger;  
    for you have lifted me up and thrown me aside.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 102, 11, 'My days are like an evening shadow;  
    I wither away like grass.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 102, 12, 'But you, O LORD, are enthroned forever;  
    your name endures to all generations.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 102, 13, 'You will rise up and have compassion on Zion,  
    for it is time to favor it;  
    the appointed time has come.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 102, 14, 'For your servants hold its stones dear,  
    and have pity on its dust.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 102, 15, 'The nations will fear the name of the LORD,  
    and all the kings of the earth your glory.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 102, 16, 'For the LORD will build up Zion;  
    he will appear in his glory.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 102, 17, 'He will regard the prayer of the destitute,  
    and will not despise their prayer.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 102, 18, 'Let this be recorded for a generation to come,  
    so that a people yet unborn may praise the LORD:', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 102, 19, 'that he looked down from his holy height,  
    from heaven the LORD looked at the earth,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 102, 20, 'to hear the groans of the prisoners,  
    to set free those who were doomed to die;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 102, 21, 'so that the name of the LORD may be declared in Zion,  
    and his praise in Jerusalem,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 102, 22, 'when peoples gather together,  
    and kingdoms, to worship the LORD.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 102, 23, 'He has broken my strength in midcourse;  
    he has shortened my days.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 102, 24, '"O my God," I say, "do not take me away  
    at the midpoint of my life,  
you whose years endure  
    throughout all generations."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 102, 25, 'Long ago you laid the foundation of the earth,  
    and the heavens are the work of your hands.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 102, 26, 'They will perish, but you endure;  
    they will all wear out like a garment.  
You change them like clothing, and they pass away;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 102, 27, 'but you are the same, and your years have no end.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 102, 28, 'The children of your servants shall live secure;  
    their offspring shall be established in your presence.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 103, 1, 'Bless the LORD, O my soul,  
    and all that is within me,  
    bless his holy name.', 'en', 'NRSV-CE', 'Psalm 103'),
(19, 'Maz', 'Psalms', 103, 2, 'Bless the LORD, O my soul,  
    and do not forget all his benefits--', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 103, 3, 'who forgives all your iniquity,  
    who heals all your diseases,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 103, 4, 'who redeems your life from the Pit,  
    who crowns you with steadfast love and mercy,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 103, 5, 'who satisfies you with good as long as you live  
    so that your youth is renewed like the eagle"s.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 103, 6, 'The LORD works vindication  
    and justice for all who are oppressed.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 103, 7, 'He made known his ways to Moses,  
    his acts to the people of Israel.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 103, 8, 'The LORD is merciful and gracious,  
    slow to anger and abounding in steadfast love.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 103, 9, 'He will not always accuse,  
    nor will he keep his anger forever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 103, 10, 'He does not deal with us according to our sins,  
    nor repay us according to our iniquities.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 103, 11, 'For as the heavens are high above the earth,  
    so great is his steadfast love toward those who fear him;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 103, 12, 'as far as the east is from the west,  
    so far he removes our transgressions from us.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 103, 13, 'As a father has compassion for his children,  
    so the LORD has compassion for those who fear him.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 103, 14, 'For he knows how we were made;  
    he remembers that we are dust.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 103, 15, 'As for mortals, their days are like grass;  
    they flourish like a flower of the field;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 103, 16, 'for the wind passes over it, and it is gone,  
    and its place knows it no more.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 103, 17, 'But the steadfast love of the LORD is from everlasting to everlasting  
    on those who fear him,  
    and his righteousness to children"s children,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 103, 18, 'to those who keep his covenant  
    and remember to do his commandments.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 103, 19, 'The LORD has established his throne in the heavens,  
    and his kingdom rules over all.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 103, 20, 'Bless the LORD, O you his angels,  
    you mighty ones who do his bidding,  
    obedient to his spoken word.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 103, 21, 'Bless the LORD, all his hosts,  
    his ministers that do his will.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 103, 22, 'Bless the LORD, all his works,  
    in all places of his dominion.  
Bless the LORD, O my soul.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 104, 1, 'Bless the LORD, O my soul.  
    O LORD my God, you are very great.  
You are clothed with honor and majesty,', 'en', 'NRSV-CE', 'Psalm 104'),
(19, 'Maz', 'Psalms', 104, 2, 'wrapped in light as with a garment.  
You stretch out the heavens like a tent,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 3, 'you set the beams of your chambers on the waters,  
you make the clouds your chariot,  
    you ride on the wings of the wind,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 4, 'you make the winds your messengers,  
    fire and flame your ministers.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 5, 'You set the earth on its foundations,  
    so that it shall never be shaken.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 6, 'You cover it with the deep as with a garment;  
    the waters stood above the mountains.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 7, 'At your rebuke they flee;  
    at the sound of your thunder they take to flight.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 8, 'They rose up to the mountains, ran down to the valleys  
    to the place that you appointed for them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 9, 'You set a boundary that they may not pass,  
    so that they might not again cover the earth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 10, 'You make springs gush forth in the valleys;  
    they flow between the hills,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 11, 'giving drink to every wild animal;  
    the wild asses quench their thirst.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 12, 'By the streams the birds of the air have their habitation;  
    they sing among the branches.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 13, 'From your lofty abode you water the mountains;  
    the earth is satisfied with the fruit of your work.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 14, 'You cause the grass to grow for the cattle,  
    and plants for people to use,  
to bring forth food from the earth,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 15, 'and wine to gladden the human heart,  
oil to make the face shine,  
    and bread to strengthen the human heart.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 16, 'The trees of the LORD are watered abundantly,  
    the cedars of Lebanon that he planted.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 17, 'In them the birds build their nests;  
    the stork has its home in the fir trees.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 18, 'The high mountains are for the wild goats;  
    the rocks are a refuge for the coneys.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 19, 'You have made the moon to mark the seasons;  
    the sun knows its time for setting.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 20, 'You make darkness, and it is night,  
    when all the animals of the forest come creeping out.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 21, 'The young lions roar for their prey,  
    seeking their food from God.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 22, 'When the sun rises, they withdraw  
    and lie down in their dens.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 23, 'People go out to their work  
    and to their labor until the evening.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 24, 'O LORD, how manifold are your works!  
    In wisdom you have made them all;  
    the earth is full of your creatures.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 25, 'Yonder is the sea, great and wide,  
    creeping things innumerable are there,  
    living things both small and great.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 26, 'There go the ships,  
    and Leviathan that you formed to sport in it.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 27, 'These all look to you  
    to give them their food in due season;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 28, 'when you give to them, they gather it up;  
    when you open your hand, they are filled with good things.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 29, 'When you hide your face, they are dismayed;  
    when you take away their breath, they die  
    and return to their dust.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 30, 'When you send forth your spirit, they are created;  
    and you renew the face of the ground.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 31, 'May the glory of the LORD endure forever;  
    may the LORD rejoice in his works--', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 32, 'who looks on the earth and it trembles,  
    who touches the mountains and they smoke.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 33, 'I will sing to the LORD as long as I live;  
    I will sing praise to my God while I have being.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 34, 'May my meditation be pleasing to him,  
    for I rejoice in the LORD.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 104, 35, 'Let sinners be consumed from the earth,  
    and let the wicked be no more.  
Bless the LORD, O my soul.  
Praise the LORD!', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 105, 1, 'O give thanks to the LORD, call on his name,  
    make known his deeds among the peoples.', 'en', 'NRSV-CE', 'Psalm 105'),
(19, 'Maz', 'Psalms', 105, 2, 'Sing to him, sing praises to him;  
    tell of all his wonderful works.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 3, 'Glory in his holy name;  
    let the hearts of those who seek the LORD rejoice.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 4, 'Seek the LORD and his strength;  
    seek his presence continually.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 5, 'Remember the wonderful works he has done,  
    his miracles, and the judgments he has uttered,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 6, 'O offspring of his servant Abraham,  
    children of Jacob, his chosen ones.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 7, 'He is the LORD our God;  
    his judgments are in all the earth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 8, 'He is mindful of his covenant forever,  
    of the word that he commanded, for a thousand generations,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 9, 'the covenant that he made with Abraham,  
    his sworn promise to Isaac,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 10, 'which he confirmed to Jacob as a statute,  
    to Israel as an everlasting covenant,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 11, 'saying, "To you I will give the land of Canaan  
    as your portion for an inheritance."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 12, 'When they were few in number,  
    of little account, and strangers in it,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 13, 'wandering from nation to nation,  
    from one kingdom to another people,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 14, 'he allowed no one to oppress them;  
    he rebuked kings on their account,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 15, 'saying, "Do not touch my anointed ones;  
    do my prophets no harm."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 16, 'When he summoned famine against the land,  
    and broke every staff of bread,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 17, 'he had sent a man ahead of them,  
    Joseph, who was sold as a slave.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 18, 'His feet were hurt with fetters,  
    his neck was put in a collar of iron;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 19, 'until what he had said came to pass,  
    the word of the LORD kept testing him.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 20, 'The king sent and released him;  
    the ruler of the peoples set him free.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 21, 'He made him lord of his house,  
    and ruler of all his possessions,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 22, 'to instruct his officials at his pleasure,  
    and to teach his elders wisdom.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 23, 'Then Israel came to Egypt;  
    Jacob lived as an alien in the land of Ham.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 24, 'And the LORD made his people very fruitful,  
    and made them stronger than their foes,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 25, 'whose hearts he then turned to hate his people,  
    to deal craftily with his servants.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 26, 'He sent his servant Moses,  
    and Aaron whom he had chosen.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 27, 'They performed his signs among them,  
    and miracles in the land of Ham.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 28, 'He sent darkness, and made the land dark;  
    they rebelled against his words.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 29, 'He turned their waters into blood,  
    and caused their fish to die.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 30, 'Their land swarmed with frogs,  
    even in the chambers of their kings.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 31, 'He spoke, and there came swarms of flies,  
    and gnats throughout their country.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 32, 'He gave them hail for rain,  
    and lightning that flashed through their land.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 33, 'He struck their vines and fig trees,  
    and shattered the trees of their country.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 34, 'He spoke, and the locusts came,  
    and young locusts without number;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 35, 'they devoured all the vegetation in their land,  
    and ate up the fruit of their ground.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 36, 'He struck down all the firstborn in their land,  
    the first issue of all their strength.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 37, 'Then he brought Israel out with silver and gold,  
    and there was no one among their tribes who stumbled.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 38, 'Egypt was glad when they departed,  
    for dread of them had fallen upon it.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 39, 'He spread a cloud for a covering,  
    and fire to give light by night.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 40, 'They asked, and he brought quails,  
    and gave them food from heaven in abundance.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 41, 'He opened the rock, and water gushed out;  
    it flowed through the desert like a river.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 42, 'For he remembered his holy promise,  
    and Abraham, his servant.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 43, 'So he brought his people out with joy,  
    his chosen ones with singing.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 44, 'He gave them the lands of the nations,  
    and they took possession of the wealth of the peoples,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 105, 45, 'that they might keep his statutes  
    and observe his laws.  
Praise the LORD!', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 106, 1, 'Praise the LORD!  
    O give thanks to the LORD, for he is good;  
    for his steadfast love endures forever.', 'en', 'NRSV-CE', 'Psalm 106'),
(19, 'Maz', 'Psalms', 106, 2, 'Who can utter the mighty doings of the LORD,  
    or declare all his praise?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 3, 'Happy are those who observe justice,  
    who do righteousness at all times.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 4, 'Remember me, O LORD, when you show favor to your people;  
    help me when you deliver them;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 5, 'that I may see the prosperity of your chosen ones,  
    that I may rejoice in the gladness of your nation,  
    that I may glory in your heritage.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 6, 'Both we and our ancestors have sinned;  
    we have committed iniquity, have done wickedly.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 7, 'Our ancestors, when they were in Egypt,  
    did not consider your wonderful works;  
they did not remember the abundance of your steadfast love,  
    but rebelled against the Most High at the Red Sea.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 8, 'Yet he saved them for his name"s sake,  
    so that he might make known his mighty power.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 9, 'He rebuked the Red Sea, and it became dry;  
    he led them through the deep as through a desert.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 10, 'So he saved them from the hand of the foe,  
    and delivered them from the hand of the enemy.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 11, 'The waters covered their adversaries;  
    not one of them was left.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 12, 'Then they believed his words;  
    they sang his praise.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 13, 'But they soon forgot his works;  
    they did not wait for his counsel.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 14, 'But they had a wanton craving in the wilderness,  
    and put God to the test in the desert;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 15, 'he gave them what they asked,  
    but sent a wasting disease among them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 16, 'They were jealous of Moses in the camp,  
    and of Aaron, the holy one of the LORD.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 17, 'The earth opened and swallowed up Dathan,  
    and covered the faction of Abiram.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 18, 'Fire also broke out in their company;  
    the flame burned up the wicked.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 19, 'They made a calf at Horeb  
    and worshiped a cast image.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 20, 'They exchanged the glory of God  
    for the image of an ox that eats grass.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 21, 'They forgot God, their Savior,  
    who had done great things in Egypt,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 22, 'wondrous works in the land of Ham,  
    and awesome deeds by the Red Sea.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 23, 'Therefore he said he would destroy them--  
    had not Moses, his chosen one,  
stood in the breach before him,  
    to turn away his wrath from destroying them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 24, 'Then they despised the pleasant land,  
    having no faith in his promise.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 25, 'They grumbled in their tents,  
    and did not obey the voice of the LORD.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 26, 'Therefore he raised his hand and swore to them  
    that he would make them fall in the wilderness,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 27, 'and would disperse their descendants among the nations,  
    scattering them over the lands.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 28, 'Then they attached themselves to the Baal of Peor,  
    and ate sacrifices offered to the dead;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 29, 'they provoked the LORD to anger with their deeds,  
    and a plague broke out among them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 30, 'Then Phinehas stood up and interceded,  
    and the plague was stopped.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 31, 'And that has been reckoned to him as righteousness  
    from generation to generation forever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 32, 'They angered the LORD at the waters of Meribah,  
    and it went ill with Moses on their account;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 33, 'for they made his spirit bitter,  
    and he spoke words that were rash.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 34, 'They did not destroy the peoples,  
    as the LORD commanded them,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 35, 'but they mingled with the nations  
    and learned to do as they did.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 36, 'They served their idols,  
    which became a snare to them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 37, 'They sacrificed their sons  
    and their daughters to the demons;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 38, 'they poured out innocent blood,  
    the blood of their sons and daughters,  
whom they sacrificed to the idols of Canaan;  
    and the land was polluted with blood.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 39, 'Thus they became unclean by their acts,  
    and prostituted themselves in their doings.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 40, 'Then the anger of the LORD was kindled against his people,  
    and he abhorred his heritage;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 41, 'he gave them into the hand of the nations,  
    so that those who hated them ruled over them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 42, 'Their enemies oppressed them,  
    and they were brought into subjection under their power.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 43, 'Many times he delivered them,  
    but they were rebellious in their purposes,  
    and were brought low through their iniquity.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 44, 'Nevertheless he regarded their distress  
    when he heard their cry.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 45, 'For their sake he remembered his covenant,  
    and showed compassion according to the abundance of his steadfast love.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 46, 'He caused them to be pitied  
    by all who held them captive.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 47, 'Save us, O LORD our God,  
    and gather us from among the nations,  
that we may give thanks to your holy name  
    and glory in your praise.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 106, 48, 'Blessed be the LORD, the God of Israel,  
    from everlasting to everlasting.  
And let all the people say, "Amen."  
    Praise the LORD!', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 107, 1, 'O give thanks to the LORD, for he is good;  
    for his steadfast love endures forever.', 'en', 'NRSV-CE', 'Psalm 107'),
(19, 'Maz', 'Psalms', 107, 2, 'Let the redeemed of the LORD say so,  
    those he redeemed from trouble', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 3, 'and gathered in from the lands,  
    from the east and from the west,  
    from the north and from the south.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 4, 'Some wandered in desert wastes,  
    finding no way to an inhabited town;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 5, 'hungry and thirsty,  
    their soul fainted within them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 6, 'Then they cried to the LORD in their trouble,  
    and he delivered them from their distress;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 7, 'he led them by a straight way,  
    until they reached an inhabited town.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 8, 'Let them thank the LORD for his steadfast love,  
    for his wonderful works to humankind.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 9, 'For he satisfies the thirsty,  
    and the hungry he fills with good things.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 10, 'Some sat in darkness and in gloom,  
    prisoners in misery and in irons,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 11, 'for they had rebelled against the words of God,  
    and spurned the counsel of the Most High.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 12, 'Their hearts were bowed down with hard labor;  
    they fell down, with no one to help.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 13, 'Then they cried to the LORD in their trouble,  
    and he saved them from their distress;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 14, 'he brought them out of darkness and gloom,  
    and broke their bonds asunder.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 15, 'Let them thank the LORD for his steadfast love,  
    for his wonderful works to humankind.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 16, 'For he shatters the doors of bronze,  
    and cuts in two the bars of iron.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 17, 'Some were sick through their sinful ways,  
    and because of their iniquities endured affliction;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 18, 'they loathed any kind of food,  
    and they drew near to the gates of death.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 19, 'Then they cried to the LORD in their trouble,  
    and he saved them from their distress;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 20, 'he sent out his word and healed them,  
    and delivered them from destruction.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 21, 'Let them thank the LORD for his steadfast love,  
    for his wonderful works to humankind.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 22, 'And let them offer thanksgiving sacrifices,  
    and tell of his deeds with songs of joy.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 23, 'Some went down to the sea in ships,  
    doing business on the mighty waters;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 24, 'they saw the deeds of the LORD,  
    his wondrous works in the deep.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 25, 'For he commanded and raised the stormy wind,  
    which lifted up the waves of the sea.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 26, 'They mounted up to heaven, they went down to the depths;  
    their courage melted away in their calamity;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 27, 'they reeled and staggered like drunkards,  
    and were at their wits" end.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 28, 'Then they cried to the LORD in their trouble,  
    and he brought them out from their distress;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 29, 'he made the storm be still,  
    and the waves of the sea were hushed.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 30, 'Then they were glad because they had quiet,  
    and he brought them to their desired haven.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 31, 'Let them thank the LORD for his steadfast love,  
    for his wonderful works to humankind.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 32, 'Let them extol him in the congregation of the people,  
    and praise him in the assembly of the elders.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 33, 'He turns rivers into a desert,  
    springs of water into thirsty ground,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 34, 'a fruitful land into a salty waste,  
    because of the wickedness of its inhabitants.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 35, 'He turns a desert into pools of water,  
    a parched land into springs of water.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 36, 'And there he lets the hungry live,  
    and they establish a town to live in;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 37, 'they sow fields, and plant vineyards,  
    and get a fruitful yield.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 38, 'By his blessing they multiply greatly,  
    and he does not let their cattle decrease.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 39, 'When they are diminished and brought low  
    through oppression, trouble, and sorrow,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 40, 'he pours contempt on princes  
    and makes them wander in trackless wastes;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 41, 'but he raises up the needy out of distress,  
    and makes their families like flocks.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 42, 'The upright see it and are glad;  
    and all wickedness stops its mouth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 107, 43, 'Let those who are wise give heed to these things,  
    and consider the steadfast love of the LORD.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 108, 1, 'My heart is steadfast, O God, my heart is steadfast;  
    I will sing and make melody.  
    Awake, my soul!', 'en', 'NRSV-CE', 'Psalm 108'),
(19, 'Maz', 'Psalms', 108, 2, 'Awake, O harp and lyre!  
    I will awake the dawn.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 108, 3, 'I will give thanks to you, O LORD, among the peoples,  
    and I will sing praises to you among the nations.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 108, 4, 'For your steadfast love is higher than the heavens,  
    and your faithfulness reaches to the clouds.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 108, 5, 'Be exalted, O God, above the heavens,  
    and let your glory be over all the earth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 108, 6, 'Give victory with your right hand, and answer me,  
    so that those whom you love may be rescued.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 108, 7, 'God has promised in his sanctuary:  
    "With exultation I will divide up Shechem,  
    and portion out the Vale of Succoth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 108, 8, 'Gilead is mine; Manasseh is mine;  
    Ephraim is my helmet;  
    Judah is my scepter.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 108, 9, 'Moab is my washbasin;  
    on Edom I hurl my shoe;  
    over Philistia I shout in triumph."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 108, 10, 'Who will bring me to the fortified city?  
    Who will lead me to Edom?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 108, 11, 'Have you not rejected us, O God?  
    You do not go out, O God, with our armies.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 108, 12, 'O grant us help against the foe,  
    for human help is worthless.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 108, 13, 'With God we shall do valiantly;  
    it is he who will tread down our foes.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 109, 1, 'Do not be silent, O God of my praise.', 'en', 'NRSV-CE', 'Psalm 109'),
(19, 'Maz', 'Psalms', 109, 2, 'For wicked and deceitful mouths are opened against me,  
    speaking against me with lying tongues.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 3, 'They beset me with words of hate,  
    and attack me without cause.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 4, 'In return for my love they accuse me,  
    even while I make prayer for them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 5, 'So they reward me evil for good,  
    and hatred for my love.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 6, 'They say, "Appoint a wicked man against him;  
    let an accuser stand on his right.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 7, 'When he is tried, let him be found guilty;  
    let his prayer be counted as sin.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 8, 'May his days be few;  
    may another seize his position.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 9, 'May his children be orphans,  
    and his wife a widow.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 10, 'May his children wander about and beg;  
    may they be driven out of the ruins they inhabit.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 11, 'May the creditor seize all that he has;  
    may strangers plunder the fruits of his toil.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 12, 'May there be no one to do him a kindness,  
    nor anyone to pity his orphaned children.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 13, 'May his posterity be cut off;  
    may his name be blotted out in the second generation.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 14, 'May the iniquity of his father be remembered before the LORD,  
    and do not let the sin of his mother be blotted out.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 15, 'Let them be before the LORD continually,  
    and may his memory be cut off from the earth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 16, 'For he did not remember to show kindness,  
    but pursued the poor and needy  
    and the brokenhearted to their death.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 17, 'He loved to curse; let curses come on him.  
    He did not like blessing; may it be far from him.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 18, 'He clothed himself with cursing as his coat,  
    may it soak into his body like water,  
    like oil into his bones.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 19, 'May it be like a garment that he wraps around himself,  
    like a belt that he wears every day."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 20, 'May that be the reward of my accusers from the LORD,  
    of those who speak evil against my life.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 21, 'But you, O LORD my Lord,  
    act on my behalf for your name"s sake;  
    because your steadfast love is good, deliver me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 22, 'For I am poor and needy,  
    and my heart is pierced within me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 23, 'I am gone like a shadow at evening;  
    I am shaken off like a locust.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 24, 'My knees are weak through fasting;  
    my body has become gaunt.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 25, 'I am an object of scorn to my accusers;  
    when they see me, they shake their heads.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 26, 'Help me, O LORD my God!  
    Save me according to your steadfast love.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 27, 'Let them know that this is your hand;  
    you, O LORD, have done it.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 28, 'Let them curse, but you will bless.  
    Let my assailants be put to shame; may your servant be glad.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 29, 'May my accusers be clothed with dishonor;  
    may they be wrapped in their own shame as in a mantle.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 30, 'With my mouth I will give great thanks to the LORD;  
    I will praise him in the midst of the throng.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 109, 31, 'For he stands at the right hand of the needy,  
    to save them from those who would condemn them to death.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 110, 1, 'The LORD says to my lord,  
    "Sit at my right hand  
until I make your enemies your footstool."', 'en', 'NRSV-CE', 'Psalm 110'),
(19, 'Maz', 'Psalms', 110, 2, 'The LORD sends out from Zion  
    your mighty scepter.  
    Rule in the midst of your foes.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 110, 3, 'Your people will offer themselves willingly  
    on the day you lead your forces  
    on the holy mountains.  
From the womb of the morning,  
    like dew, your youth will come to you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 110, 4, 'The LORD has sworn and will not change his mind,  
    "You are a priest forever according to the order of Melchizedek."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 110, 5, 'The Lord is at your right hand;  
    he will shatter kings on the day of his wrath.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 110, 6, 'He will execute judgment among the nations,  
    filling them with corpses;  
he will shatter heads  
    over the wide earth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 110, 7, 'He will drink from the stream by the path;  
    therefore he will lift up his head.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 111, 1, 'Praise the LORD!  
I will give thanks to the LORD with my whole heart,  
    in the company of the upright, in the congregation.', 'en', 'NRSV-CE', 'Psalm 111'),
(19, 'Maz', 'Psalms', 111, 2, 'Great are the works of the LORD,  
    studied by all who delight in them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 111, 3, 'Full of honor and majesty is his work,  
    and his righteousness endures forever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 111, 4, 'He has gained renown by his wonderful deeds;  
    the LORD is gracious and merciful.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 111, 5, 'He provides food for those who fear him;  
    he is ever mindful of his covenant.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 111, 6, 'He has shown his people the power of his works,  
    in giving them the heritage of the nations.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 111, 7, 'The works of his hands are faithful and just;  
    all his precepts are trustworthy.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 111, 8, 'They are established forever and ever,  
    to be performed with faithfulness and uprightness.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 111, 9, 'He sent redemption to his people;  
    he has commanded his covenant forever.  
    Holy and awesome is his name.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 111, 10, 'The fear of the LORD is the beginning of wisdom;  
    all those who practice it have a good understanding.  
    His praise endures forever.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 112, 1, 'Praise the LORD!  
    Happy are those who fear the LORD,  
    who greatly delight in his commandments.', 'en', 'NRSV-CE', 'Psalm 112'),
(19, 'Maz', 'Psalms', 112, 2, 'Their descendants will be mighty in the land;  
    the generation of the upright will be blessed.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 112, 3, 'Wealth and riches are in their houses,  
    and their righteousness endures forever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 112, 4, 'They rise in the darkness as a light for the upright;  
    they are gracious, merciful, and righteous.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 112, 5, 'It is well with those who deal generously and lend,  
    who conduct their affairs with justice.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 112, 6, 'For the righteous will never be moved;  
    they will be remembered forever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 112, 7, 'They are not afraid of evil tidings;  
    their hearts are firm, secure in the LORD.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 112, 8, 'Their hearts are steady, they will not be afraid;  
    in the end they will look in triumph on their foes.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 112, 9, 'They have distributed freely, they have given to the poor;  
    their righteousness endures forever;  
    their horn is exalted in honor.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 112, 10, 'The wicked see it and are angry;  
    they gnash their teeth and melt away;  
    the desire of the wicked comes to nothing.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 113, 1, 'Praise the LORD!  
Praise, O servants of the LORD;  
    praise the name of the LORD.', 'en', 'NRSV-CE', 'Psalm 113'),
(19, 'Maz', 'Psalms', 113, 2, 'Blessed be the name of the LORD  
    from this time on and forevermore.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 113, 3, 'From the rising of the sun to its setting  
    the name of the LORD is to be praised.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 113, 4, 'The LORD is high above all nations,  
    and his glory above the heavens.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 113, 5, 'Who is like the LORD our God,  
    who is seated on high,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 113, 6, 'who looks far down  
    on the heavens and the earth?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 113, 7, 'He raises the poor from the dust,  
    and lifts the needy from the ash heap,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 113, 8, 'to make them sit with princes,  
    with the princes of his people.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 113, 9, 'He gives the barren woman a home,  
    making her the joyous mother of children.  
Praise the LORD!', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 114, 1, 'When Israel went out from Egypt,  
    the house of Jacob from a people of strange language,', 'en', 'NRSV-CE', 'Psalm 114'),
(19, 'Maz', 'Psalms', 114, 2, 'Judah became God"s sanctuary,  
    Israel his dominion.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 114, 3, 'The sea looked and fled;  
    Jordan turned back.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 114, 4, 'The mountains skipped like rams,  
    the hills like lambs.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 114, 5, 'Why is it, O sea, that you flee?  
    O Jordan, that you turn back?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 114, 6, 'O mountains, that you skip like rams?  
    O hills, like lambs?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 114, 7, 'Tremble, O earth, at the presence of the LORD,  
    at the presence of the God of Jacob,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 114, 8, 'who turns the rock into a pool of water,  
    the flint into a spring of water.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 115, 1, 'Not to us, O LORD, not to us, but to your name give glory,  
    for the sake of your steadfast love and your faithfulness.', 'en', 'NRSV-CE', 'Psalm 115'),
(19, 'Maz', 'Psalms', 115, 2, 'Why should the nations say,  
    "Where is their God?"', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 115, 3, 'Our God is in the heavens;  
    he does whatever he pleases.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 115, 4, 'Their idols are silver and gold,  
    the work of human hands.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 115, 5, 'They have mouths, but do not speak;  
    eyes, but do not see.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 115, 6, 'They have ears, but do not hear;  
    noses, but do not smell.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 115, 7, 'They have hands, but do not feel;  
    feet, but do not walk;  
    they make no sound in their throats.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 115, 8, 'Those who make them are like them;  
    so are all who trust in them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 115, 9, 'O Israel, trust in the LORD!  
    He is their help and their shield.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 115, 10, 'O house of Aaron, trust in the LORD!  
    He is their help and their shield.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 115, 11, 'You who fear the LORD, trust in the LORD!  
    He is their help and their shield.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 115, 12, 'The LORD has been mindful of us; he will bless us;  
    he will bless the house of Israel;  
    he will bless the house of Aaron;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 115, 13, 'he will bless those who fear the LORD,  
    both small and great.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 115, 14, 'May the LORD give you increase,  
    both you and your children.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 115, 15, 'May you be blessed by the LORD,  
    who made heaven and earth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 115, 16, 'The heavens are the LORD"s heavens,  
    but the earth he has given to human beings.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 115, 17, 'The dead do not praise the LORD,  
    nor do any that go down into silence.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 115, 18, 'But we will bless the LORD  
    from this time on and forevermore.  
Praise the LORD!', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 116, 1, 'I love the LORD, because he has heard  
    my voice and my supplications.', 'en', 'NRSV-CE', 'Psalm 116'),
(19, 'Maz', 'Psalms', 116, 2, 'Because he inclined his ear to me,  
    therefore I will call on him as long as I live.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 116, 3, 'The snares of death encompassed me;  
    the pangs of Sheol laid hold on me;  
    I suffered distress and anguish.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 116, 4, 'Then I called on the name of the LORD:  
    "O LORD, I pray, save my life!"', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 116, 5, 'Gracious is the LORD, and righteous;  
    our God is merciful.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 116, 6, 'The LORD protects the simple;  
    when I was brought low, he saved me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 116, 7, 'Return, O my soul, to your rest,  
    for the LORD has dealt bountifully with you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 116, 8, 'For you have delivered my soul from death,  
    my eyes from tears,  
    my feet from stumbling.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 116, 9, 'I walk before the LORD  
    in the land of the living.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 116, 10, 'I kept my faith, even when I said,  
    "I am greatly afflicted";', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 116, 11, 'I said in my consternation,  
    "Everyone is a liar."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 116, 12, 'What shall I return to the LORD  
    for all his bounty to me?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 116, 13, 'I will lift up the cup of salvation  
    and call on the name of the LORD,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 116, 14, 'I will pay my vows to the LORD  
    in the presence of all his people.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 116, 15, 'Precious in the sight of the LORD  
    is the death of his faithful ones.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 116, 16, 'O LORD, I am your servant;  
    I am your servant, the child of your serving girl.  
    You have loosed my bonds.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 116, 17, 'I will offer to you a thanksgiving sacrifice  
    and call on the name of the LORD.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 116, 18, 'I will pay my vows to the LORD  
    in the presence of all his people,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 116, 19, 'in the courts of the house of the LORD,  
    in your midst, O Jerusalem.  
Praise the LORD!', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 117, 1, 'Praise the LORD, all you nations!  
    Extol him, all you peoples!', 'en', 'NRSV-CE', 'Psalm 117'),
(19, 'Maz', 'Psalms', 117, 2, 'For great is his steadfast love toward us,  
    and the faithfulness of the LORD endures forever.  
Praise the LORD!', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 118, 1, 'O give thanks to the LORD, for he is good;  
    his steadfast love endures forever!', 'en', 'NRSV-CE', 'Psalm 118'),
(19, 'Maz', 'Psalms', 118, 2, 'Let Israel say,  
    "His steadfast love endures forever."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 3, 'Let the house of Aaron say,  
    "His steadfast love endures forever."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 4, 'Let those who fear the LORD say,  
    "His steadfast love endures forever."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 5, 'Out of my distress I called on the LORD;  
    the LORD answered me and set me in a broad place.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 6, 'With the LORD on my side I do not fear.  
    What can mortals do to me?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 7, 'The LORD is on my side to help me;  
    I shall look in triumph on those who hate me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 8, 'It is better to take refuge in the LORD  
    than to put confidence in mortals.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 9, 'It is better to take refuge in the LORD  
    than to put confidence in princes.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 10, 'All nations surrounded me;  
    in the name of the LORD I cut them off!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 11, 'They surrounded me, surrounded me on every side;  
    in the name of the LORD I cut them off!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 12, 'They surrounded me like bees;  
    they blazed like a fire of thorns;  
    in the name of the LORD I cut them off!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 13, 'I was pushed hard, so that I was falling,  
    but the LORD helped me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 14, 'The LORD is my strength and my might;  
    he has become my salvation.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 15, 'There are glad songs of victory in the tents of the righteous:  
"The right hand of the LORD does valiantly;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 16, 'the right hand of the LORD is exalted;  
    the right hand of the LORD does valiantly."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 17, 'I shall not die, but I shall live,  
    and recount the deeds of the LORD.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 18, 'The LORD has punished me severely,  
    but he did not give me over to death.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 19, 'Open to me the gates of righteousness,  
    that I may enter through them  
    and give thanks to the LORD.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 20, 'This is the gate of the LORD;  
    the righteous shall enter through it.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 21, 'I thank you that you have answered me  
    and have become my salvation.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 22, 'The stone that the builders rejected  
    has become the chief cornerstone.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 23, 'This is the LORD"s doing;  
    it is marvelous in our eyes.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 24, 'This is the day that the LORD has made;  
    let us rejoice and be glad in it.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 25, 'Save us, we beseech you, O LORD!  
    O LORD, we beseech you, give us success!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 26, 'Blessed is the one who comes in the name of the LORD.  
    We bless you from the house of the LORD.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 27, 'The LORD is God,  
    and he has given us light.  
Bind the festal procession with branches,  
    up to the horns of the altar.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 28, 'You are my God, and I will give thanks to you;  
    you are my God, I will extol you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 118, 29, 'O give thanks to the LORD, for he is good,  
    for his steadfast love endures forever.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 119, 1, 'Happy are those whose way is blameless,  
    who walk in the law of the LORD.', 'en', 'NRSV-CE', 'Psalm 119'),
(19, 'Maz', 'Psalms', 119, 2, 'Happy are those who keep his decrees,  
    who seek him with their whole heart,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 3, 'who also do no wrong,  
    but walk in his ways.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 4, 'You have commanded your precepts  
    to be kept diligently.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 5, 'O that my ways may be steadfast  
    in keeping your statutes!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 6, 'Then I shall not be put to shame,  
    having my eyes fixed on all your commandments.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 7, 'I will praise you with an upright heart,  
    when I learn your righteous ordinances.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 8, 'I will observe your statutes;  
    do not utterly forsake me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 9, 'How can young people keep their way pure?  
    By guarding it according to your word.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 10, 'With my whole heart I seek you;  
    do not let me stray from your commandments.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 11, 'I treasure your word in my heart,  
    so that I may not sin against you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 12, 'Blessed are you, O LORD;  
    teach me your statutes.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 13, 'With my lips I declare  
    all the ordinances of your mouth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 14, 'I delight in the way of your decrees  
    as much as in all riches.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 15, 'I will meditate on your precepts,  
    and fix my eyes on your ways.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 16, 'I will delight in your statutes;  
    I will not forget your word.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 17, 'Deal bountifully with your servant,  
    so that I may live and observe your word.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 18, 'Open my eyes, so that I may behold  
    wondrous things out of your law.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 19, 'I live as an alien in the land;  
    do not hide your commandments from me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 20, 'My soul is consumed with longing  
    for your ordinances at all times.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 21, 'You rebuke the insolent, accursed ones,  
    who wander from your commandments;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 22, 'take away from me their scorn and contempt,  
    for I have kept your decrees.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 23, 'Even though princes sit plotting against me,  
    your servant will meditate on your statutes.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 24, 'Your decrees are my delight,  
    they are my counselors.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 25, 'My soul clings to the dust;  
    revive me according to your word.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 26, 'When I told of my ways, you answered me;  
    teach me your statutes.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 27, 'Make me understand the way of your precepts,  
    and I will meditate on your wondrous works.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 28, 'My soul melts away for sorrow;  
    strengthen me according to your word.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 29, 'Put false ways far from me;  
    and graciously teach me your law.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 30, 'I have chosen the way of faithfulness;  
    I set your ordinances before me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 31, 'I cling to your decrees, O LORD;  
    let me not be put to shame.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 32, 'I run the way of your commandments,  
    for you enlarge my understanding.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 33, 'Teach me, O LORD, the way of your statutes,  
    and I will observe it to the end.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 34, 'Give me understanding, that I may keep your law  
    and observe it with my whole heart.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 35, 'Lead me in the path of your commandments,  
    for I delight in it.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 36, 'Turn my heart to your decrees,  
    and not to selfish gain.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 37, 'Turn my eyes from looking at vanities;  
    give me life in your ways.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 38, 'Confirm to your servant your promise,  
    which is for those who fear you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 39, 'Turn away the disgrace that I dread,  
    for your ordinances are good.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 40, 'See, I have longed for your precepts;  
    in your righteousness give me life.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 41, 'Let your steadfast love come to me, O LORD,  
    your salvation according to your promise.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 42, 'Then I shall have an answer for those who taunt me,  
    for I trust in your word.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 43, 'Do not take the word of truth utterly out of my mouth,  
    for my hope is in your ordinances.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 44, 'I will keep your law continually,  
    forever and ever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 45, 'I shall walk at liberty,  
    for I have sought your precepts.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 46, 'I will also speak of your decrees before kings,  
    and shall not be put to shame;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 47, 'I find my delight in your commandments,  
    because I love them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 48, 'I revere your commandments, which I love,  
    and I will meditate on your statutes.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 49, 'Remember your word to your servant,  
    in which you have made me hope.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 50, 'This is my comfort in my distress,  
    that your promise gives me life.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 51, 'The arrogant utterly deride me,  
    but I do not turn away from your law.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 52, 'When I think of your ordinances from of old,  
    I take comfort, O LORD.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 53, 'Hot indignation seizes me because of the wicked,  
    those who forsake your law.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 54, 'Your statutes have been my songs  
    wherever I make my home.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 55, 'I remember your name in the night, O LORD,  
    and keep your law.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 56, 'This blessing has fallen to me,  
    for I have kept your precepts.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 57, 'The LORD is my portion;  
    I promise to keep your words.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 58, 'I implore your favor with all my heart;  
    be gracious to me according to your promise.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 59, 'When I think of your ways,  
    I turn my feet to your decrees;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 60, 'I hurry and do not delay  
    to keep your commandments.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 61, 'Though the cords of the wicked ensnare me,  
    I do not forget your law.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 62, 'At midnight I rise to praise you,  
    because of your righteous ordinances.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 63, 'I am a companion of all who fear you,  
    of those who keep your precepts.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 64, 'The earth, O LORD, is full of your steadfast love;  
    teach me your statutes.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 65, 'You have dealt well with your servant,  
    O LORD, according to your word.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 66, 'Teach me good judgment and knowledge,  
    for I believe in your commandments.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 67, 'Before I was humbled I went astray,  
    but now I keep your word.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 68, 'You are good and do good;  
    teach me your statutes.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 69, 'The arrogant smear me with lies,  
    but with my whole heart I keep your precepts.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 70, 'Their hearts are fat and gross,  
    but I delight in your law.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 71, 'It is good for me that I was humbled,  
    so that I might learn your statutes.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 72, 'The law of your mouth is better to me  
    than thousands of gold and silver pieces.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 73, 'Your hands have made and fashioned me;  
    give me understanding that I may learn your commandments.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 74, 'Those who fear you shall see me and rejoice,  
    because I have hoped in your word.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 75, 'I know, O LORD, that your judgments are right,  
    and that in faithfulness you have humbled me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 76, 'Let your steadfast love become my comfort  
    according to your promise to your servant.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 77, 'Let your mercy come to me, that I may live;  
    for your law is my delight.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 78, 'Let the arrogant be put to shame,  
    because they have subverted me with guile;  
    as for me, I will meditate on your precepts.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 79, 'Let those who fear you turn to me,  
    so that they may know your decrees.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 80, 'May my heart be blameless in your statutes,  
    so that I may not be put to shame.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 81, 'My soul languishes for your salvation;  
    I hope in your word.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 82, 'My eyes fail with watching for your promise;  
    I ask, "When will you comfort me?"', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 83, 'For I have become like a wineskin in the smoke,  
    yet I have not forgotten your statutes.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 84, 'How long must your servant endure?  
    When will you judge those who persecute me?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 85, 'The arrogant have dug pitfalls for me;  
    they flout your law.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 86, 'All your commandments are enduring;  
    I am persecuted without cause; help me!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 87, 'They have almost made an end of me on earth;  
    but I have not forsaken your precepts.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 88, 'In your steadfast love spare my life,  
    so that I may keep the decrees of your mouth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 89, 'The LORD exists forever;  
    your word is firmly fixed in heaven.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 90, 'Your faithfulness endures to all generations;  
    you have established the earth, and it stands fast.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 91, 'By your appointment they stand today,  
    for all things are your servants.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 92, 'If your law had not been my delight,  
    I would have perished in my misery.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 93, 'I will never forget your precepts,  
    for by them you have given me life.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 94, 'I am yours; save me,  
    for I have sought your precepts.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 95, 'The wicked lie in wait to destroy me,  
    but I consider your decrees.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 96, 'I have seen a limit to all perfection,  
    but your commandment is exceedingly broad.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 97, 'Oh, how I love your law!  
    It is my meditation all day long.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 98, 'Your commandment makes me wiser than my enemies,  
    for it is always with me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 99, 'I have more understanding than all my teachers,  
    for your decrees are my meditation.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 100, 'I understand more than the aged,  
    for I keep your precepts.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 101, 'I hold back my feet from every evil way,  
    in order to keep your word.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 102, 'I do not turn away from your ordinances,  
    for you have taught me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 103, 'How sweet are your words to my taste,  
    sweeter than honey to my mouth!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 104, 'Through your precepts I get understanding;  
    therefore I hate every false way.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 105, 'Your word is a lamp to my feet  
    and a light to my path.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 106, 'I have sworn an oath and confirmed it,  
    to observe your righteous ordinances.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 107, 'I am severely afflicted;  
    give me life, O LORD, according to your word.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 108, 'Accept my offerings of praise, O LORD,  
    and teach me your ordinances.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 109, 'I hold my life in my hand continually,  
    but I do not forget your law.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 110, 'The wicked have laid a snare for me,  
    but I do not stray from your precepts.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 111, 'Your decrees are my heritage forever;  
    they are the joy of my heart.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 112, 'I incline my heart to perform your statutes  
    forever, to the end.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 113, 'I hate the double-minded,  
    but I love your law.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 114, 'You are my hiding place and my shield;  
    I hope in your word.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 115, 'Go away from me, you evildoers,  
    that I may keep the commandments of my God.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 116, 'Uphold me according to your promise, that I may live,  
    and let me not be put to shame in my hope.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 117, 'Hold me up, that I may be safe  
    and have regard for your statutes continually.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 118, 'You spurn all who go astray from your statutes;  
    for their cunning is in vain.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 119, 'All the wicked of the earth you count as dross;  
    therefore I love your decrees.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 120, 'My flesh trembles for fear of you,  
    and I am afraid of your judgments.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 121, 'I have done what is just and right;  
    do not leave me to my oppressors.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 122, 'Guarantee your servant"s well-being;  
    do not let the godless oppress me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 123, 'My eyes fail from watching for your salvation,  
    and for the fulfillment of your righteous promise.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 124, 'Deal with your servant according to your steadfast love,  
    and teach me your statutes.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 125, 'I am your servant; give me understanding,  
    so that I may know your decrees.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 126, 'It is time for the LORD to act,  
    for your law has been broken.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 127, 'Truly I love your commandments  
    more than gold, more than fine gold.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 128, 'Truly I direct my steps by all your precepts;  
    I hate every false way.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 129, 'Your decrees are wonderful;  
    therefore my soul keeps them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 130, 'The unfolding of your words gives light;  
    it imparts understanding to the simple.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 131, 'With open mouth I pant,  
    because I long for your commandments.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 132, 'Turn to me and be gracious to me,  
    as is your custom toward those who love your name.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 133, 'Keep my steps steady according to your promise,  
    and never let iniquity have dominion over me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 134, 'Redeem me from human oppression,  
    that I may keep your precepts.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 135, 'Make your face shine upon your servant,  
    and teach me your statutes.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 136, 'My eyes shed streams of tears  
    because your law is not kept.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 137, 'You are righteous, O LORD,  
    and your judgments are right.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 138, 'You have appointed your decrees in righteousness  
    and in all faithfulness.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 139, 'My zeal consumes me  
    because my foes forget your words.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 140, 'Your promise is well tried,  
    and your servant loves it.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 141, 'I am small and despised,  
    yet I do not forget your precepts.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 142, 'Your righteousness is an everlasting righteousness,  
    and your law is the truth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 143, 'Trouble and anguish have come upon me,  
    but your commandments are my delight.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 144, 'Your decrees are righteous forever;  
    give me understanding that I may live.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 145, 'With my whole heart I cry; answer me, O LORD.  
    I will keep your statutes.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 146, 'I cry to you; save me,  
    that I may observe your decrees.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 147, 'I rise before dawn and cry for help;  
    I put my hope in your words.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 148, 'My eyes are awake before each watch of the night,  
    that I may meditate on your promise.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 149, 'In your steadfast love hear my voice;  
    O LORD, in your justice preserve my life.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 150, 'Those who persecute me with evil purpose draw near;  
    they are far from your law.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 151, 'Yet you are near, O LORD,  
    and all your commandments are true.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 152, 'Long ago I learned from your decrees  
    that you have established them forever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 153, 'Look on my misery and rescue me,  
    for I do not forget your law.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 154, 'Plead my cause and redeem me;  
    give me life according to your promise.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 155, 'Salvation is far from the wicked,  
    for they do not seek your statutes.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 156, 'Great is your mercy, O LORD;  
    give me life according to your justice.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 157, 'Many are my persecutors and my adversaries,  
    yet I do not swerve from your decrees.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 158, 'I look at the faithless with disgust,  
    because they do not keep your commands.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 159, 'Consider how I love your precepts;  
    preserve my life according to your steadfast love.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 160, 'The sum of your word is truth;  
    and every one of your righteous ordinances endures forever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 161, 'Princes persecute me without cause,  
    but my heart stands in awe of your words.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 162, 'I rejoice at your word  
    like one who finds great spoil.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 163, 'I hate and abhor falsehood,  
    but I love your law.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 164, 'Seven times a day I praise you  
    for your righteous ordinances.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 165, 'Great peace have those who love your law;  
    nothing can make them stumble.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 166, 'I hope for your salvation, O LORD,  
    and I fulfill your commandments.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 167, 'My soul keeps your decrees;  
    I love them exceedingly.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 168, 'I keep your precepts and decrees,  
    for all my ways are before you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 169, 'Let my cry come before you, O LORD;  
    give me understanding according to your word.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 170, 'Let my supplication come before you;  
    deliver me according to your promise.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 171, 'My lips will pour forth praise,  
    because you teach me your statutes.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 172, 'My tongue will sing of your promise,  
    for all your commandments are right.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 173, 'Let your hand be ready to help me,  
    for I have chosen your precepts.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 174, 'I long for your salvation, O LORD,  
    and your law is my delight.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 175, 'Let me live that I may praise you,  
    and let your ordinances help me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 119, 176, 'I have gone astray like a lost sheep; seek out your servant,  
    for I do not forget your commandments.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 120, 1, 'In my distress I cry to the LORD,  
    that he may answer me:', 'en', 'NRSV-CE', 'Psalm 120'),
(19, 'Maz', 'Psalms', 120, 2, '"Deliver me, O LORD,  
    from lying lips,  
    from a deceitful tongue."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 120, 3, 'What shall be given to you?  
    And what more shall be done to you,  
    you deceitful tongue?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 120, 4, 'A warrior"s sharp arrows,  
    with glowing coals of the broom tree!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 120, 5, 'Woe is me, that I am an alien in Meshech,  
    that I must live among the tents of Kedar.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 120, 6, 'Too long have I had my dwelling  
    among those who hate peace.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 120, 7, 'I am for peace;  
    but when I speak,  
    they are for war.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 121, 1, 'I lift up my eyes to the hills--  
    from where will my help come?', 'en', 'NRSV-CE', 'Psalm 121'),
(19, 'Maz', 'Psalms', 121, 2, 'My help comes from the LORD,  
    who made heaven and earth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 121, 3, 'He will not let your foot be moved;  
    he who keeps you will not slumber.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 121, 4, 'He who keeps Israel  
    will neither slumber nor sleep.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 121, 5, 'The LORD is your keeper;  
    the LORD is your shade at your right hand.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 121, 6, 'The sun shall not strike you by day,  
    nor the moon by night.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 121, 7, 'The LORD will keep you from all evil;  
    he will keep your life.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 121, 8, 'The LORD will keep  
    your going out and your coming in  
    from this time on and forevermore.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 122, 1, 'I was glad when they said to me,  
    "Let us go to the house of the LORD!"', 'en', 'NRSV-CE', 'Psalm 122'),
(19, 'Maz', 'Psalms', 122, 2, 'Our feet are standing  
    within your gates, O Jerusalem.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 122, 3, 'Jerusalem--built as a city  
    that is bound firmly together.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 122, 4, 'To it the tribes go up,  
    the tribes of the LORD,  
as was decreed for Israel,  
    to give thanks to the name of the LORD.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 122, 5, 'For there the thrones for judgment were set up,  
    the thrones of the house of David.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 122, 6, 'Pray for the peace of Jerusalem:  
    "May they prosper who love you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 122, 7, 'Peace be within your walls,  
    and security within your towers."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 122, 8, 'For the sake of my relatives and friends  
    I will say, "Peace be within you."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 122, 9, 'For the sake of the house of the LORD our God,  
    I will seek your good.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 123, 1, 'To you I lift up my eyes,  
    O you who are enthroned in the heavens!', 'en', 'NRSV-CE', 'Psalm 123'),
(19, 'Maz', 'Psalms', 123, 2, 'As the eyes of servants  
    look to the hand of their master,  
as the eyes of a maid  
    to the hand of her mistress,  
so our eyes look to the LORD our God,  
    until he has mercy upon us.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 123, 3, 'Have mercy upon us, O LORD, have mercy upon us,  
    for we have had more than enough of contempt.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 123, 4, 'Our soul has had more than its fill  
    of the scorn of those who are at ease,  
    of the contempt of the proud.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 124, 1, 'If it had not been the LORD who was on our side  
    --let Israel now say--', 'en', 'NRSV-CE', 'Psalm 124'),
(19, 'Maz', 'Psalms', 124, 2, 'if it had not been the LORD who was on our side,  
    when our enemies attacked us,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 124, 3, 'then they would have swallowed us up alive,  
    when their anger was kindled against us;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 124, 4, 'then the flood would have swept us away,  
    the torrent would have gone over us;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 124, 5, 'then over us would have gone  
    the raging waters.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 124, 6, 'Blessed be the LORD,  
    who has not given us  
    as prey to their teeth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 124, 7, 'We have escaped like a bird  
    from the snare of the fowlers;  
the snare is broken,  
    and we have escaped.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 124, 8, 'Our help is in the name of the LORD,  
    who made heaven and earth.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 125, 1, 'Those who trust in the LORD are like Mount Zion,  
    which cannot be moved, but abides forever.', 'en', 'NRSV-CE', 'Psalm 125'),
(19, 'Maz', 'Psalms', 125, 2, 'As the mountains surround Jerusalem,  
    so the LORD surrounds his people,  
    from this time on and forevermore.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 125, 3, 'For the scepter of wickedness shall not rest  
    on the land allotted to the righteous,  
so that the righteous might not stretch out  
    their hands to do wrong.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 125, 4, 'Do good, O LORD, to those who are good,  
    and to those who are upright in their hearts.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 125, 5, 'But those who turn aside to their own crooked ways  
    the LORD will lead away with evildoers.  
    Peace be upon Israel!', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 126, 1, 'When the LORD restored the fortunes of Zion,  
    we were like those who dream.', 'en', 'NRSV-CE', 'Psalm 126'),
(19, 'Maz', 'Psalms', 126, 2, 'Then our mouth was filled with laughter,  
    and our tongue with shouts of joy;  
then it was said among the nations,  
    "The LORD has done great things for them."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 126, 3, 'The LORD has done great things for us,  
    and we rejoiced.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 126, 4, 'Restore our fortunes, O LORD,  
    like the watercourses in the Negeb.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 126, 5, 'May those who sow in tears  
    reap with shouts of joy.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 126, 6, 'Those who go out weeping,  
    bearing the seed for sowing,  
shall come home with shouts of joy,  
    carrying their sheaves.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 127, 1, 'Unless the LORD builds the house,  
    those who build it labor in vain.  
Unless the LORD guards the city,  
    the guard keeps watch in vain.', 'en', 'NRSV-CE', 'Psalm 127'),
(19, 'Maz', 'Psalms', 127, 2, 'It is in vain that you rise up early  
    and go late to rest,  
eating the bread of anxious toil;  
    for he gives sleep to his beloved.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 127, 3, 'Sons are indeed a heritage from the LORD,  
    the fruit of the womb a reward.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 127, 4, 'Like arrows in the hand of a warrior  
    are the sons of one"s youth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 127, 5, 'Happy is the man who has  
    his quiver full of them.  
He shall not be put to shame  
    when he speaks with his enemies in the gate.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 128, 1, 'Happy is everyone who fears the LORD,  
    who walks in his ways.', 'en', 'NRSV-CE', 'Psalm 128'),
(19, 'Maz', 'Psalms', 128, 2, 'You shall eat the fruit of the labor of your hands;  
    you shall be happy, and it shall go well with you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 128, 3, 'Your wife will be like a fruitful vine  
    within your house;  
your children will be like olive shoots  
    around your table.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 128, 4, 'Thus shall the man be blessed  
    who fears the LORD.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 128, 5, 'The LORD bless you from Zion.  
    May you see the prosperity of Jerusalem  
    all the days of your life.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 128, 6, 'May you see your children"s children.  
    Peace be upon Israel!', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 129, 1, '"Often have they attacked me from my youth"  
    --let Israel now say--', 'en', 'NRSV-CE', 'Psalm 129'),
(19, 'Maz', 'Psalms', 129, 2, '"often have they attacked me from my youth,  
    yet they have not prevailed against me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 129, 3, 'The plowers plowed on my back;  
    they made their furrows long."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 129, 4, 'The LORD is righteous;  
    he has cut the cords of the wicked.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 129, 5, 'May all who hate Zion  
    be put to shame and turned backward.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 129, 6, 'Let them be like the grass on the housetops  
    that withers before it grows up,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 129, 7, 'with which reapers do not fill their hands  
    or binders of sheaves their arms,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 129, 8, 'while those who pass by do not say,  
    "The blessing of the LORD be upon you!  
    We bless you in the name of the LORD!"', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 130, 1, 'Out of the depths I cry to you, O LORD.', 'en', 'NRSV-CE', 'Psalm 130'),
(19, 'Maz', 'Psalms', 130, 2, 'Lord, hear my voice!  
Let your ears be attentive  
    to the voice of my supplications!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 130, 3, 'If you, O LORD, should mark iniquities,  
    Lord, who could stand?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 130, 4, 'But there is forgiveness with you,  
    so that you may be revered.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 130, 5, 'I wait for the LORD, my soul waits,  
    and in his word I hope;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 130, 6, 'my soul waits for the Lord  
    more than those who watch for the morning,  
    more than those who watch for the morning.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 130, 7, 'O Israel, hope in the LORD!  
    For with the LORD there is steadfast love,  
    and with him is great power to redeem.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 130, 8, 'It is he who will redeem Israel  
    from all its iniquities.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 131, 1, 'O LORD, my heart is not lifted up,  
    my eyes are not raised too high;  
I do not occupy myself with things  
    too great and too marvelous for me.', 'en', 'NRSV-CE', 'Psalm 131'),
(19, 'Maz', 'Psalms', 131, 2, 'But I have calmed and quieted my soul,  
    like a weaned child with its mother;  
    my soul is like the weaned child that is with me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 131, 3, 'O Israel, hope in the LORD  
    from this time on and forevermore.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 132, 1, 'O LORD, remember in David"s favor  
    all the hardships he endured;', 'en', 'NRSV-CE', 'Psalm 132'),
(19, 'Maz', 'Psalms', 132, 2, 'how he swore to the LORD  
    and vowed to the Mighty One of Jacob,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 132, 3, '"I will not enter my house  
    or get into my bed;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 132, 4, 'I will not give sleep to my eyes  
    or slumber to my eyelids,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 132, 5, 'until I find a place for the LORD,  
    a dwelling place for the Mighty One of Jacob."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 132, 6, 'We heard of it in Ephrathah;  
    we found it in the fields of Jaar.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 132, 7, '"Let us go to his dwelling place;  
    let us worship at his footstool."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 132, 8, 'Rise up, O LORD, and go to your resting place,  
    you and the ark of your might.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 132, 9, 'Let your priests be clothed with righteousness,  
    and let your faithful shout for joy.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 132, 10, 'For your servant David"s sake  
    do not turn away the face of your anointed one.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 132, 11, 'The LORD swore to David a sure oath  
    from which he will not turn back:  
"One of the sons of your body  
    I will set on your throne.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 132, 12, 'If your sons keep my covenant  
    and my decrees that I shall teach them,  
their sons also, forevermore,  
    shall sit on your throne."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 132, 13, 'For the LORD has chosen Zion;  
    he has desired it for his habitation:', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 132, 14, '"This is my resting place forever;  
    here I will reside, for I have desired it.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 132, 15, 'I will abundantly bless its provisions;  
    I will satisfy its poor with bread.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 132, 16, 'Its priests I will clothe with salvation,  
    and its faithful will shout for joy.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 132, 17, 'There I will cause a horn to sprout up for David;  
    I have prepared a lamp for my anointed one.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 132, 18, 'His enemies I will clothe with disgrace,  
    but on him, his crown will gleam."', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 133, 1, 'How very good and pleasant it is  
    when kindred live together in unity!', 'en', 'NRSV-CE', 'Psalm 133'),
(19, 'Maz', 'Psalms', 133, 2, 'It is like the precious oil on the head,  
    running down upon the beard,  
on the beard of Aaron,  
    running down over the collar of his robes.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 133, 3, 'It is like the dew of Hermon,  
    which falls on the mountains of Zion.  
For there the LORD ordained his blessing,  
    life forevermore.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 134, 1, 'Come, bless the LORD, all you servants of the LORD,  
    who stand by night in the house of the LORD!', 'en', 'NRSV-CE', 'Psalm 134'),
(19, 'Maz', 'Psalms', 134, 2, 'Lift up your hands to the holy place,  
    and bless the LORD.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 134, 3, 'May the LORD, maker of heaven and earth,  
    bless you from Zion.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 135, 1, 'Praise the LORD!  
    Praise the name of the LORD;  
    give praise, O servants of the LORD,', 'en', 'NRSV-CE', 'Psalm 135'),
(19, 'Maz', 'Psalms', 135, 2, 'you that stand in the house of the LORD,  
    in the courts of the house of our God.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 135, 3, 'Praise the LORD, for the LORD is good;  
    sing to his name, for he is gracious.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 135, 4, 'For the LORD has chosen Jacob for himself,  
    Israel as his own possession.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 135, 5, 'For I know that the LORD is great;  
    our Lord is above all gods.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 135, 6, 'Whatever the LORD pleases he does,  
    in heaven and on earth,  
    in the seas and all deeps.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 135, 7, 'He it is who makes the clouds rise at the end of the earth;  
    he makes lightnings for the rain  
    and brings out the wind from his storehouses.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 135, 8, 'He it was who struck down the firstborn of Egypt,  
    both human beings and animals;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 135, 9, 'he sent signs and wonders  
    into your midst, O Egypt,  
    against Pharaoh and all his servants.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 135, 10, 'He struck down many nations  
    and killed mighty kings--', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 135, 11, 'Sihon, king of the Amorites,  
    and Og, king of Bashan,  
    and all the kingdoms of Canaan--', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 135, 12, 'and gave their land as a heritage,  
    a heritage to his people Israel.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 135, 13, 'Your name, O LORD, endures forever,  
    your renown, O LORD, throughout all ages.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 135, 14, 'For the LORD will vindicate his people,  
    and have compassion on his servants.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 135, 15, 'The idols of the nations are silver and gold,  
    the work of human hands.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 135, 16, 'They have mouths, but they do not speak;  
    they have eyes, but they do not see;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 135, 17, 'they have ears, but they do not hear,  
    and there is no breath in their mouths.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 135, 18, 'Those who make them  
    and all who trust them  
    shall become like them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 135, 19, 'O house of Israel, bless the LORD!  
    O house of Aaron, bless the LORD!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 135, 20, 'O house of Levi, bless the LORD!  
    You that fear the LORD, bless the LORD!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 135, 21, 'Blessed be the LORD from Zion,  
    he who resides in Jerusalem.  
Praise the LORD!', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 136, 1, 'O give thanks to the LORD, for he is good,  
    for his steadfast love endures forever.', 'en', 'NRSV-CE', 'Psalm 136'),
(19, 'Maz', 'Psalms', 136, 2, 'O give thanks to the God of gods,  
    for his steadfast love endures forever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 136, 3, 'O give thanks to the Lord of lords,  
    for his steadfast love endures forever;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 136, 4, 'who alone does great wonders,  
    for his steadfast love endures forever;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 136, 5, 'who by understanding made the heavens,  
    for his steadfast love endures forever;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 136, 6, 'who spread out the earth on the waters,  
    for his steadfast love endures forever;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 136, 7, 'who made the great lights,  
    for his steadfast love endures forever;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 136, 8, 'the sun to rule over the day,  
    for his steadfast love endures forever;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 136, 9, 'the moon and stars to rule over the night,  
    for his steadfast love endures forever;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 136, 10, 'who struck Egypt through their firstborn,  
    for his steadfast love endures forever;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 136, 11, 'and brought Israel out from among them,  
    for his steadfast love endures forever;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 136, 12, 'with a strong hand and an outstretched arm,  
    for his steadfast love endures forever;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 136, 13, 'who divided the Red Sea in two,  
    for his steadfast love endures forever;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 136, 14, 'and made Israel pass through the midst of it,  
    for his steadfast love endures forever;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 136, 15, 'but overthrew Pharaoh and his army in the Red Sea,  
    for his steadfast love endures forever;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 136, 16, 'who led his people through the wilderness,  
    for his steadfast love endures forever;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 136, 17, 'who struck down great kings,  
    for his steadfast love endures forever;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 136, 18, 'and killed famous kings,  
    for his steadfast love endures forever;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 136, 19, 'Sihon, king of the Amorites,  
    for his steadfast love endures forever;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 136, 20, 'and Og, king of Bashan,  
    for his steadfast love endures forever;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 136, 21, 'and gave their land as a heritage,  
    for his steadfast love endures forever;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 136, 22, 'a heritage to his servant Israel,  
    for his steadfast love endures forever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 136, 23, 'It is he who remembered us in our low estate,  
    for his steadfast love endures forever;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 136, 24, 'and rescued us from our foes,  
    for his steadfast love endures forever;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 136, 25, 'who gives food to all flesh,  
    for his steadfast love endures forever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 136, 26, 'O give thanks to the God of heaven,  
    for his steadfast love endures forever.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 137, 1, 'By the rivers of Babylon--  
    there we sat down and there we wept  
    when we remembered Zion.', 'en', 'NRSV-CE', 'Psalm 137'),
(19, 'Maz', 'Psalms', 137, 2, 'On the willows there  
    we hung up our harps.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 137, 3, 'For there our captors  
    asked us for songs,  
and our tormentors asked for mirth, saying,  
    "Sing us one of the songs of Zion!"', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 137, 4, 'How could we sing the LORD"s song  
    in a foreign land?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 137, 5, 'If I forget you, O Jerusalem,  
    let my right hand wither!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 137, 6, 'Let my tongue cling to the roof of my mouth,  
    if I do not remember you,  
if I do not set Jerusalem  
    above my highest joy.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 137, 7, 'Remember, O LORD, against the Edomites  
    the day of Jerusalem"s fall,  
how they said, "Tear it down! Tear it down!  
    Down to its foundations!"', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 137, 8, 'O daughter Babylon, you devastator!  
    Happy shall they be who pay you back  
    what you have done to us!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 137, 9, 'Happy shall they be who take your little ones  
    and dash them against the rock!', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 138, 1, 'I give you thanks, O LORD, with my whole heart;  
    before the gods I sing your praise;', 'en', 'NRSV-CE', 'Psalm 138'),
(19, 'Maz', 'Psalms', 138, 2, 'I bow down toward your holy temple  
    and give thanks to your name for your steadfast love and your faithfulness;  
    for you have exalted your name and your word  
    above everything.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 138, 3, 'On the day I called, you answered me,  
    you increased my strength of soul.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 138, 4, 'All the kings of the earth shall praise you, O LORD,  
    for they have heard the words of your mouth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 138, 5, 'They shall sing of the ways of the LORD,  
    for great is the glory of the LORD.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 138, 6, 'For though the LORD is high, he regards the lowly;  
    but the haughty he perceives from far away.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 138, 7, 'Though I walk in the midst of trouble,  
    you preserve me against the wrath of my enemies;  
you stretch out your hand,  
    and your right hand delivers me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 138, 8, 'The LORD will fulfill his purpose for me;  
    your steadfast love, O LORD, endures forever.  
    Do not forsake the work of your hands.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 139, 1, 'O LORD, you have searched me and known me.', 'en', 'NRSV-CE', 'Psalm 139'),
(19, 'Maz', 'Psalms', 139, 2, 'You know when I sit down and when I rise up;  
    you discern my thoughts from far away.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 139, 3, 'You search out my path and my lying down,  
    and are acquainted with all my ways.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 139, 4, 'Even before a word is on my tongue,  
    O LORD, you know it completely.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 139, 5, 'You hem me in, behind and before,  
    and lay your hand upon me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 139, 6, 'Such knowledge is too wonderful for me;  
    it is so high that I cannot attain it.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 139, 7, 'Where can I go from your spirit?  
    Or where can I flee from your presence?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 139, 8, 'If I ascend to heaven, you are there;  
    if I make my bed in Sheol, you are there.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 139, 9, 'If I take the wings of the morning  
    and settle at the farthest limits of the sea,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 139, 10, 'even there your hand shall lead me,  
    and your right hand shall hold me fast.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 139, 11, 'If I say, "Surely the darkness shall cover me,  
    and the light around me become night,"', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 139, 12, 'even the darkness is not dark to you;  
    the night is as bright as the day,  
    for darkness is as light to you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 139, 13, 'For it was you who formed my inward parts;  
    you knit me together in my mother"s womb.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 139, 14, 'I praise you, for I am fearfully and wonderfully made.  
    Wonderful are your works;  
that I know very well.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 139, 15, 'My frame was not hidden from you,  
when I was being made in secret,  
    intricately woven in the depths of the earth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 139, 16, 'Your eyes beheld my unformed substance.  
In your book were written  
    all the days that were formed for me,  
    when none of them as yet existed.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 139, 17, 'How weighty to me are your thoughts, O God!  
    How vast is the sum of them!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 139, 18, 'I try to count them--they are more than the sand;  
    I come to the end--I am still with you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 139, 19, 'O that you would kill the wicked, O God,  
    and that the bloodthirsty would depart from me--', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 139, 20, 'those who speak of you maliciously,  
    and lift themselves up against you for evil!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 139, 21, 'Do I not hate those who hate you, O LORD?  
    And do I not loathe those who rise up against you?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 139, 22, 'I hate them with perfect hatred;  
    I count them my enemies.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 139, 23, 'Search me, O God, and know my heart;  
    test me and know my thoughts.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 139, 24, 'See if there is any wicked way in me,  
    and lead me in the way everlasting.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 140, 1, 'Deliver me, O LORD, from evildoers;  
    protect me from those who are violent,', 'en', 'NRSV-CE', 'Psalm 140'),
(19, 'Maz', 'Psalms', 140, 2, 'who plan evil things in their minds  
    and stir up wars continually.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 140, 3, 'They make their tongue sharp as a snake"s,  
    and under their lips is the venom of vipers._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 140, 4, 'Guard me, O LORD, from the hands of the wicked;  
    protect me from the violent  
    who have planned my downfall.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 140, 5, 'The arrogant have hidden a trap for me,  
    and with cords they have spread a net,  
    along the road they have set snares for me._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 140, 6, 'I say to the LORD, "You are my God;  
    give ear, O LORD, to the voice of my supplications."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 140, 7, 'O LORD, my Lord, my strong deliverer,  
    you have covered my head in the day of battle.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 140, 8, 'Do not grant, O LORD, the desires of the wicked;  
    do not further their evil plot._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 140, 9, 'Those who surround me lift up their heads;  
    let the mischief of their lips overwhelm them!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 140, 10, 'Let burning coals fall on them!  
    Let them be flung into pits, no more to rise!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 140, 11, 'Do not let the slanderer be established in the land;  
    let evil speedily hunt down the violent!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 140, 12, 'I know that the LORD maintains the cause of the needy,  
    and executes justice for the poor.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 140, 13, 'Surely the righteous shall give thanks to your name;  
    the upright shall live in your presence.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 141, 1, 'I call upon you, O LORD; come quickly to me;  
    give ear to my voice when I call to you.', 'en', 'NRSV-CE', 'Psalm 141'),
(19, 'Maz', 'Psalms', 141, 2, 'Let my prayer be counted as incense before you,  
    and the lifting up of my hands as an evening sacrifice.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 141, 3, 'Set a guard over my mouth, O LORD;  
    keep watch over the door of my lips.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 141, 4, 'Do not turn my heart to any evil,  
    to busy myself with wicked deeds  
in company with those who work iniquity;  
    do not let me eat of their delicacies.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 141, 5, 'Let the righteous strike me;  
    let the faithful correct me.  
Never let the oil of the wicked anoint my head,  
    for my prayer is continually against their wicked deeds.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 141, 6, 'When they are given over to those who shall condemn them,  
    then they shall learn that my words were pleasant.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 141, 7, 'Like a rock that one breaks apart and shatters on the land,  
    so shall their bones be strewn at the mouth of Sheol.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 141, 8, 'But my eyes are turned toward you, O God, my Lord;  
    in you I seek refuge; do not leave me defenseless.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 141, 9, 'Keep me from the trap that they have laid for me,  
    and from the snares of evildoers.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 141, 10, 'Let the wicked fall into their own nets,  
    while I alone escape.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 142, 1, 'With my voice I cry to the LORD;  
    with my voice I make supplication to the LORD.', 'en', 'NRSV-CE', 'Psalm 142'),
(19, 'Maz', 'Psalms', 142, 2, 'I pour out my complaint before him;  
    I tell my trouble before him.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 142, 3, 'When my spirit is faint,  
    you know my way.
In the path where I walk  
    they have hidden a trap for me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 142, 4, 'Look on my right hand and see--  
    there is no one who takes notice of me;  
no refuge remains to me;  
    no one cares for me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 142, 5, 'I cry to you, O LORD;  
    I say, "You are my refuge,  
    my portion in the land of the living."', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 142, 6, 'Give heed to my cry,  
    for I am brought very low.
Save me from my persecutors,  
    for they are too strong for me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 142, 7, 'Bring me out of prison,  
    so that I may give thanks to your name.  
The righteous will surround me,  
    for you will deal bountifully with me.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 143, 1, 'Hear my prayer, O LORD;  
    give ear to my supplications in your faithfulness;  
    answer me in your righteousness.', 'en', 'NRSV-CE', 'Psalm 143'),
(19, 'Maz', 'Psalms', 143, 2, 'Do not enter into judgment with your servant,  
    for no one living is righteous before you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 143, 3, 'For the enemy has pursued me,  
    crushing my life to the ground,  
    making me sit in darkness like those long dead.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 143, 4, 'Therefore my spirit faints within me;  
    my heart within me is appalled.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 143, 5, 'I remember the days of old,  
    I think about all your deeds,  
    I meditate on the works of your hands.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 143, 6, 'I stretch out my hands to you;  
    my soul thirsts for you like a parched land._Selah_', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 143, 7, 'Answer me quickly, O LORD;  
    my spirit fails.  
Do not hide your face from me,  
    or I shall be like those who go down to the Pit.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 143, 8, 'Let me hear of your steadfast love in the morning,  
    for in you I put my trust.  
Teach me the way I should go,  
    for to you I lift up my soul.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 143, 9, 'Save me, O LORD, from my enemies;  
    I have fled to you for refuge.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 143, 10, 'Teach me to do your will,  
    for you are my God.  
Let your good spirit lead me  
    on a level path.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 143, 11, 'For your name"s sake, O LORD, preserve my life.  
    In your righteousness bring me out of trouble.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 143, 12, 'In your steadfast love cut off my enemies,  
    and destroy all my adversaries,  
    for I am your servant.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 144, 1, 'Blessed be the LORD, my rock,  
    who trains my hands for war, and my fingers for battle;', 'en', 'NRSV-CE', 'Psalm 144'),
(19, 'Maz', 'Psalms', 144, 2, 'my rock and my fortress,  
    my stronghold and my deliverer,  
my shield, in whom I take refuge,  
    who subdues the peoples under me.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 144, 3, 'O LORD, what are human beings that you regard them,  
    or mortals that you think of them?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 144, 4, 'They are like a breath;  
    their days are like a passing shadow.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 144, 5, 'Bow your heavens, O LORD, and come down;  
    touch the mountains so that they smoke.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 144, 6, 'Make the lightning flash and scatter them;  
    send out your arrows and rout them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 144, 7, 'Stretch out your hand from on high;  
    set me free and rescue me from the mighty waters,  
    from the hand of aliens,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 144, 8, 'whose mouths speak lies,  
    and whose right hands are false.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 144, 9, 'I will sing a new song to you, O God;  
    upon a ten-stringed harp I will play to you,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 144, 10, 'the one who gives victory to kings,  
    who rescues his servant David.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 144, 11, 'Rescue me from the cruel sword,  
    and deliver me from the hand of aliens,  
whose mouths speak lies,  
    and whose right hands are false.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 144, 12, 'May our sons in their youth  
    be like plants full grown,  
our daughters like corner pillars,  
    cut for the building of a palace.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 144, 13, 'May our barns be filled,  
    with produce of every kind;  
may our sheep increase by thousands,  
    by tens of thousands in our fields,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 144, 14, 'and may our cattle be heavy with young.  
May there be no breach in the walls, no exile,  
    and no cry of distress in our streets.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 144, 15, 'Happy are the people to whom such blessings fall;  
    happy are the people whose God is the LORD.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 145, 1, 'I will extol you, my God and King,  
    and bless your name forever and ever.', 'en', 'NRSV-CE', 'Psalm 145'),
(19, 'Maz', 'Psalms', 145, 2, 'Every day I will bless you,  
    and praise your name forever and ever.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 145, 3, 'Great is the LORD, and greatly to be praised;  
    his greatness is unsearchable.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 145, 4, 'One generation shall laud your works to another,  
    and shall declare your mighty acts.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 145, 5, 'On the glorious splendor of your majesty,  
    and on your wondrous works, I will meditate.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 145, 6, 'The might of your awesome deeds shall be proclaimed,  
    and I will declare your greatness.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 145, 7, 'They shall celebrate the fame of your abundant goodness,  
    and shall sing aloud of your righteousness.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 145, 8, 'The LORD is gracious and merciful,  
    slow to anger and abounding in steadfast love.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 145, 9, 'The LORD is good to all,  
    and his compassion is over all that he has made.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 145, 10, 'All your works shall give thanks to you, O LORD,  
    and all your faithful shall bless you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 145, 11, 'They shall speak of the glory of your kingdom,  
    and tell of your power,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 145, 12, 'to make known to all people your mighty deeds,  
    and the glorious splendor of your kingdom.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 145, 13, 'Your kingdom is an everlasting kingdom,  
    and your dominion endures throughout all generations.
The LORD is faithful in all his words,  
    and gracious in all his deeds.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 145, 14, 'The LORD upholds all who are falling,  
    and raises up all who are bowed down.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 145, 15, 'The eyes of all look to you,  
    and you give them their food in due season.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 145, 16, 'You open your hand,  
    satisfying the desire of every living thing.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 145, 17, 'The LORD is just in all his ways,  
    and kind in all his doings.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 145, 18, 'The LORD is near to all who call on him,  
    to all who call on him in truth.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 145, 19, 'He fulfills the desire of all who fear him;  
    he also hears their cry, and saves them.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 145, 20, 'The LORD watches over all who love him,  
    but all the wicked he will destroy.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 145, 21, 'My mouth will speak the praise of the LORD,  
    and all flesh will bless his holy name forever and ever.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 146, 1, 'Praise the LORD!  
Praise the LORD, O my soul!', 'en', 'NRSV-CE', 'Psalm 146'),
(19, 'Maz', 'Psalms', 146, 2, 'I will praise the LORD as long as I live;  
    I will sing praises to my God all my life long.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 146, 3, 'Do not put your trust in princes,  
    in mortals, in whom there is no help.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 146, 4, 'When their breath departs, they return to the earth;  
    on that very day their plans perish.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 146, 5, 'Happy are those whose help is the God of Jacob,  
    whose hope is in the LORD their God,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 146, 6, 'who made heaven and earth,  
    the sea, and all that is in them;  
who keeps faith forever;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 146, 7, 'who executes justice for the oppressed;  
    who gives food to the hungry.
The LORD sets the prisoners free;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 146, 8, 'the LORD opens the eyes of the blind.  
The LORD lifts up those who are bowed down;  
    the LORD loves the righteous.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 146, 9, 'The LORD watches over the strangers;  
    he upholds the orphan and the widow,  
    but the way of the wicked he brings to ruin.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 146, 10, 'The LORD will reign forever,  
    your God, O Zion, for all generations.  
Praise the LORD!', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 147, 1, 'Praise the LORD!  
How good it is to sing praises to our God;  
    for he is gracious, and a song of praise is fitting.', 'en', 'NRSV-CE', 'Psalm 147'),
(19, 'Maz', 'Psalms', 147, 2, 'The LORD builds up Jerusalem;  
    he gathers the outcasts of Israel.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 147, 3, 'He heals the brokenhearted,  
    and binds up their wounds.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 147, 4, 'He determines the number of the stars;  
    he gives to all of them their names.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 147, 5, 'Great is our Lord, and abundant in power;  
    his understanding is beyond measure.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 147, 6, 'The LORD lifts up the downtrodden;  
    he casts the wicked to the ground.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 147, 7, 'Sing to the LORD with thanksgiving;  
    make melody to our God on the lyre.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 147, 8, 'He covers the heavens with clouds,  
    prepares rain for the earth,  
    makes grass grow on the hills.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 147, 9, 'He gives to the animals their food,  
    and to the young ravens when they cry.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 147, 10, 'His delight is not in the strength of the horse,  
    nor his pleasure in the speed of a runner;', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 147, 11, 'but the LORD takes pleasure in those who fear him,  
    in those who hope in his steadfast love.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 147, 12, 'Praise the LORD, O Jerusalem!  
    Praise your God, O Zion!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 147, 13, 'For he strengthens the bars of your gates;  
    he blesses your children within you.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 147, 14, 'He grants peace within your borders;  
    he fills you with the finest of wheat.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 147, 15, 'He sends out his command to the earth;  
    his word runs swiftly.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 147, 16, 'He gives snow like wool;  
    he scatters frost like ashes.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 147, 17, 'He hurls down hail like crumbs--  
    who can stand before his cold?', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 147, 18, 'He sends out his word, and melts them;  
    he makes his wind blow, and the waters flow.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 147, 19, 'He declares his word to Jacob,  
    his statutes and ordinances to Israel.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 147, 20, 'He has not dealt thus with any other nation;  
    they do not know his ordinances.  
Praise the LORD!', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 148, 1, 'Praise the LORD!  
Praise the LORD from the heavens;  
    praise him in the heights!', 'en', 'NRSV-CE', 'Psalm 148'),
(19, 'Maz', 'Psalms', 148, 2, 'Praise him, all his angels;  
    praise him, all his host!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 148, 3, 'Praise him, sun and moon;  
    praise him, all you shining stars!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 148, 4, 'Praise him, you highest heavens,  
    and you waters above the heavens!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 148, 5, 'Let them praise the name of the LORD,  
    for he commanded and they were created.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 148, 6, 'He established them forever and ever;  
    he fixed their bounds, which cannot be passed.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 148, 7, 'Praise the LORD from the earth,  
    you sea monsters and all deeps,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 148, 8, 'fire and hail, snow and frost,  
    stormy wind fulfilling his command!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 148, 9, 'Mountains and all hills,  
    fruit trees and all cedars!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 148, 10, 'Wild animals and all cattle,  
    creeping things and flying birds!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 148, 11, 'Kings of the earth and all peoples,  
    princes and all rulers of the earth!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 148, 12, 'Young men and women alike,  
    old and young together!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 148, 13, 'Let them praise the name of the LORD,  
    for his name alone is exalted;  
    his glory is above earth and heaven.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 148, 14, 'He has raised up a horn for his people,  
    praise for all his faithful,  
    for the people of Israel who are close to him.  
Praise the LORD!', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 149, 1, 'Praise the LORD!  
Sing to the LORD a new song,  
    his praise in the assembly of the faithful.', 'en', 'NRSV-CE', 'Psalm 149'),
(19, 'Maz', 'Psalms', 149, 2, 'Let Israel be glad in its Maker;  
    let the children of Zion rejoice in their King.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 149, 3, 'Let them praise his name with dancing,  
    making melody to him with tambourine and lyre.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 149, 4, 'For the LORD takes pleasure in his people;  
    he adorns the humble with victory.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 149, 5, 'Let the faithful exult in glory;  
    let them sing for joy on their couches.', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 149, 6, 'Let the high praises of God be in their throats  
    and two-edged swords in their hands,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 149, 7, 'to execute vengeance on the nations  
    and punishment on the peoples,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 149, 8, 'to bind their kings with fetters  
    and their nobles with chains of iron,', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 149, 9, 'to execute on them the judgment decreed.  
    This is glory for all his faithful ones.  
Praise the LORD!', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(19, 'Maz', 'Psalms', 150, 1, 'Praise the LORD!  
Praise God in his sanctuary;  
    praise him in his mighty firmament!', 'en', 'NRSV-CE', 'Psalm 150'),
(19, 'Maz', 'Psalms', 150, 2, 'Praise him for his mighty deeds;  
    praise him according to his surpassing greatness!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 150, 3, 'Praise him with trumpet sound;  
    praise him with lute and harp!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 150, 4, 'Praise him with tambourine and dance;  
    praise him with strings and pipe!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 150, 5, 'Praise him with clanging cymbals;  
    praise him with loud clashing cymbals!', 'en', 'NRSV-CE', NULL),
(19, 'Maz', 'Psalms', 150, 6, 'Let everything that breathes praise the LORD!  
Praise the LORD!', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 1, 1, 'The proverbs of Solomon son of David, king of Israel:', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 2, 'For learning about wisdom and instruction,  
    for understanding words of insight,', 'en', 'NRSV-CE', 'Prologue'),
(20, 'Ams', 'Proverbs', 1, 3, 'for gaining instruction in wise dealing,  
    righteousness, justice, and equity;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 4, 'to teach shrewdness to the simple,  
    knowledge and prudence to the young--', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 5, 'let the wise also hear and gain in learning,  
    and the discerning acquire skill,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 6, 'to understand a proverb and a figure,  
    the words of the wise and their riddles.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 7, 'The fear of the LORD is the beginning of knowledge;  
    fools despise wisdom and instruction.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 8, 'Hear, my child, your father"s instruction,  
    and do not reject your mother"s teaching;', 'en', 'NRSV-CE', 'Warnings against Evil Companions'),
(20, 'Ams', 'Proverbs', 1, 9, 'for they are a fair garland for your head,  
    and pendants for your neck.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 10, 'My child, if sinners entice you,  
    do not consent.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 11, 'If they say, "Come with us, let us lie in wait for blood;  
    let us wantonly ambush the innocent;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 12, 'like Sheol let us swallow them alive  
    and whole, like those who go down to the Pit.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 13, 'We shall find all kinds of costly things;  
    we shall fill our houses with booty.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 14, 'Throw in your lot among us;  
    we will all have one purse"--', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 15, 'my child, do not walk in their way,  
    keep your foot from their paths;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 16, 'for their feet run to evil,  
    and they hurry to shed blood.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 17, 'For in vain is the net baited  
    while the bird is looking on;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 18, 'yet they lie in wait--to kill themselves!  
    and set an ambush--for their own lives!', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 19, 'Such is the end of all who are greedy for gain;  
    it takes away the life of its possessors.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 20, 'Wisdom cries out in the street;  
    in the squares she raises her voice.', 'en', 'NRSV-CE', 'The Call of Wisdom'),
(20, 'Ams', 'Proverbs', 1, 21, 'At the busiest corner she cries out;  
    at the entrance of the city gates she speaks:', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 22, '"How long, O simple ones, will you love being simple?  
How long will scoffers delight in their scoffing  
    and fools hate knowledge?', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 23, 'Give heed to my reproof;  
I will pour out my thoughts to you;  
    I will make my words known to you.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 24, 'Because I have called and you refused,  
    have stretched out my hand and no one heeded,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 25, 'and because you have ignored all my counsel  
    and would have none of my reproof,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 26, 'I also will laugh at your calamity;  
    I will mock when panic strikes you,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 27, 'when panic strikes you like a storm,  
    and your calamity comes like a whirlwind,  
    when distress and anguish come upon you.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 28, 'Then they will call upon me, but I will not answer;  
    they will seek me diligently, but will not find me.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 29, 'Because they hated knowledge  
    and did not choose the fear of the LORD,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 30, 'would have none of my counsel,  
    and despised all my reproof,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 31, 'therefore they shall eat the fruit of their way  
    and be sated with their own devices.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 32, 'For waywardness kills the simple,  
    and the complacency of fools destroys them;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 1, 33, 'but those who listen to me will be secure  
    and will live at ease, without dread of disaster."', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 2, 1, 'My child, if you accept my words  
    and treasure up my commandments within you,', 'en', 'NRSV-CE', 'The Value of Wisdom'),
(20, 'Ams', 'Proverbs', 2, 2, 'making your ear attentive to wisdom  
    and inclining your heart to understanding;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 2, 3, 'if you indeed cry out for insight,  
    and raise your voice for understanding;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 2, 4, 'if you seek it like silver,  
    and search for it as for hidden treasures--', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 2, 5, 'then you will understand the fear of the LORD  
    and find the knowledge of God.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 2, 6, 'For the LORD gives wisdom;  
    from his mouth come knowledge and understanding;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 2, 7, 'he stores up sound wisdom for the upright;  
    he is a shield to those who walk blamelessly,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 2, 8, 'guarding the paths of justice  
    and preserving the way of his faithful ones.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 2, 9, 'Then you will understand righteousness and justice  
    and equity, every good path;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 2, 10, 'for wisdom will come into your heart,  
    and knowledge will be pleasant to your soul;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 2, 11, 'prudence will watch over you;  
    and understanding will guard you.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 2, 12, 'It will save you from the way of evil,  
    from those who speak perversely,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 2, 13, 'who forsake the paths of uprightness  
    to walk in the ways of darkness,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 2, 14, 'who rejoice in doing evil  
    and delight in the perverseness of evil;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 2, 15, 'those whose paths are crooked,  
    and who are devious in their ways.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 2, 16, 'You will be saved from the loose woman,  
    from the adulteress with her smooth words,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 2, 17, 'who forsakes the partner of her youth  
    and forgets her sacred covenant;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 2, 18, 'for her way leads down to death,  
    and her paths to the shades;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 2, 19, 'those who go to her never come back,  
    nor do they regain the paths of life.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 2, 20, 'Therefore walk in the way of the good,  
    and keep to the paths of the just.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 2, 21, 'For the upright will abide in the land,  
    and the innocent will remain in it;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 2, 22, 'but the wicked will be cut off from the land,  
    and the treacherous will be rooted out of it.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 3, 1, 'My child, do not forget my teaching,  
    but let your heart keep my commandments;', 'en', 'NRSV-CE', 'Admonition to Trust and Honor God'),
(20, 'Ams', 'Proverbs', 3, 2, 'for length of days and years of life  
    and abundant welfare they will give you.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 3, 'Do not let loyalty and faithfulness forsake you;  
    bind them around your neck,  
    write them on the tablet of your heart.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 4, 'So you will find favor and good repute  
    in the sight of God and of people.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 5, 'Trust in the LORD with all your heart,  
    and do not rely on your own insight.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 6, 'In all your ways acknowledge him,  
    and he will make straight your paths.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 7, 'Do not be wise in your own eyes;  
    fear the LORD, and turn away from evil.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 8, 'It will be a healing for your flesh  
    and a refreshment for your body.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 9, 'Honor the LORD with your substance  
    and with the first fruits of all your produce;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 10, 'then your barns will be filled with plenty,  
    and your vats will be bursting with wine.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 11, 'My child, do not despise the LORD"s discipline  
    or be weary of his reproof,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 12, 'for the LORD reproves the one he loves,  
    as a father the son in whom he delights.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 13, 'Happy are those who find wisdom,  
    and those who get understanding,', 'en', 'NRSV-CE', 'The True Wealth'),
(20, 'Ams', 'Proverbs', 3, 14, 'for her income is better than silver,  
    and her revenue better than gold.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 15, 'She is more precious than jewels,  
    and nothing you desire can compare with her.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 16, 'Long life is in her right hand;  
    in her left hand are riches and honor.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 17, 'Her ways are ways of pleasantness,  
    and all her paths are peace.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 18, 'She is a tree of life to those who lay hold of her;  
    those who hold her fast are called happy.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 19, 'The LORD by wisdom founded the earth;  
    by understanding he established the heavens;', 'en', 'NRSV-CE', 'God"s Wisdom in Creation'),
(20, 'Ams', 'Proverbs', 3, 20, 'by his knowledge the deeps broke open,  
    and the clouds drop down the dew.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 21, 'My child, do not let these escape from your sight:  
    keep sound wisdom and prudence,', 'en', 'NRSV-CE', 'The True Security'),
(20, 'Ams', 'Proverbs', 3, 22, 'and they will be life for your soul  
    and adornment for your neck.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 23, 'Then you will walk on your way securely  
    and your foot will not stumble.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 24, 'If you sit down, you will not be afraid;  
    when you lie down, your sleep will be sweet.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 25, 'Do not be afraid of sudden panic,  
    or of the storm that strikes the wicked;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 26, 'for the LORD will be your confidence  
    and will keep your foot from being caught.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 27, 'Do not withhold good from those to whom it is due,  
    when it is in your power to do it.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 28, 'Do not say to your neighbor, "Go, and come again,  
    tomorrow I will give it"--when you have it with you.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 29, 'Do not plan harm against your neighbor  
    who lives trustingly beside you.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 30, 'Do not quarrel with anyone without cause,  
    when no harm has been done to you.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 31, 'Do not envy the violent  
    and do not choose any of their ways;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 32, 'for the perverse are an abomination to the LORD,  
    but the upright are in his confidence.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 33, 'The LORD"s curse is on the house of the wicked,  
    but he blesses the abode of the righteous.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 34, 'Toward the scorners he is scornful,  
    but to the humble he shows favor.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 3, 35, 'The wise will inherit honor,  
    but stubborn fools, disgrace.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 4, 1, 'Listen, children, to a father"s instruction,  
    and be attentive, that you may gain insight;', 'en', 'NRSV-CE', 'Parental Advice'),
(20, 'Ams', 'Proverbs', 4, 2, 'for I give you good precepts:  
    do not forsake my teaching.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 4, 3, 'When I was a son with my father,  
    tender, and my mother"s favorite,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 4, 4, 'he taught me, and said to me,  
"Let your heart hold fast my words;  
    keep my commandments, and live.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 4, 5, 'Get wisdom; get insight: do not forget, nor turn away  
    from the words of my mouth.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 4, 6, 'Do not forsake her, and she will keep you;  
    love her, and she will guard you.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 4, 7, 'The beginning of wisdom is this: Get wisdom,  
    and whatever else you get, get insight.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 4, 8, 'Prize her highly, and she will exalt you;  
    she will honor you if you embrace her.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 4, 9, 'She will place on your head a fair garland;  
    she will bestow on you a beautiful crown."', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 4, 10, 'Hear, my child, and accept my words,  
    that the years of your life may be many.', 'en', 'NRSV-CE', 'Admonition to Keep to the Right Path'),
(20, 'Ams', 'Proverbs', 4, 11, 'I have taught you the way of wisdom;  
    I have led you in the paths of uprightness.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 4, 12, 'When you walk, your step will not be hampered;  
    and if you run, you will not stumble.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 4, 13, 'Keep hold of instruction; do not let go;  
    guard her, for she is your life.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 4, 14, 'Do not enter the path of the wicked,  
    and do not walk in the way of evildoers.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 4, 15, 'Avoid it; do not go on it;  
    turn away from it and pass on.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 4, 16, 'For they cannot sleep unless they have done wrong;  
    they are robbed of sleep unless they have made someone stumble.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 4, 17, 'For they eat the bread of wickedness  
    and drink the wine of violence.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 4, 18, 'But the path of the righteous is like the light of dawn,  
    which shines brighter and brighter until full day.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 4, 19, 'The way of the wicked is like deep darkness;  
    they do not know what they stumble over.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 4, 20, 'My child, be attentive to my words;  
    incline your ear to my sayings.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 4, 21, 'Do not let them escape from your sight;  
    keep them within your heart.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 4, 22, 'For they are life to those who find them,  
    and healing to all their flesh.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 4, 23, 'Keep your heart with all vigilance,  
    for from it flow the springs of life.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 4, 24, 'Put away from you crooked speech,  
    and put devious talk far from you.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 4, 25, 'Let your eyes look directly forward,  
    and your gaze be straight before you.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 4, 26, 'Keep straight the path of your feet,  
    and all your ways will be sure.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 4, 27, 'Do not swerve to the right or to the left;  
    turn your foot away from evil.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 5, 1, 'My child, be attentive to my wisdom;  
    incline your ear to my understanding,', 'en', 'NRSV-CE', 'Warning against Impurity and Infidelity'),
(20, 'Ams', 'Proverbs', 5, 2, 'so that you may hold on to prudence,  
    and your lips may guard knowledge.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 5, 3, 'For the lips of a loose woman drip honey,  
    and her speech is smoother than oil;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 5, 4, 'but in the end she is bitter as wormwood,  
    sharp as a two-edged sword.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 5, 5, 'Her feet go down to death;  
    her steps follow the path to Sheol.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 5, 6, 'She does not keep straight to the path of life;  
    her ways wander, and she does not know it.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 5, 7, 'And now, my child, listen to me,  
    and do not depart from the words of my mouth.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 5, 8, 'Keep your way far from her,  
    and do not go near the door of her house;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 5, 9, 'or you will give your honor to others,  
    and your years to the merciless,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 5, 10, 'and strangers will take their fill of your wealth,  
    and your labors will go to the house of an alien;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 5, 11, 'and at the end of your life you will groan,  
    when your flesh and body are consumed,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 5, 12, 'and you say, "Oh, how I hated discipline,  
    and my heart despised reproof!', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 5, 13, 'I did not listen to the voice of my teachers  
    or incline my ear to my instructors.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 5, 14, 'Now I am at the point of utter ruin  
    in the public assembly."', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 5, 15, 'Drink water from your own cistern,  
    flowing water from your own well.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 5, 16, 'Should your springs be scattered abroad,  
    streams of water in the streets?', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 5, 17, 'Let them be for yourself alone,  
    and not for sharing with strangers.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 5, 18, 'Let your fountain be blessed,  
    and rejoice in the wife of your youth,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 5, 19, 'a lovely deer, a graceful doe.  
May her breasts satisfy you at all times;  
    may you be intoxicated always by her love.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 5, 20, 'Why should you be intoxicated, my son, by another woman  
    and embrace the bosom of an adulteress?', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 5, 21, 'For human ways are under the eyes of the LORD,  
    and he examines all their paths.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 5, 22, 'The iniquities of the wicked ensnare them,  
    and they are caught in the toils of their sin.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 5, 23, 'They die for lack of discipline,  
    and because of their great folly they are lost.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 6, 1, 'My child, if you have given your pledge to your neighbor,  
    if you have bound yourself to another,', 'en', 'NRSV-CE', 'Practical Admonitions'),
(20, 'Ams', 'Proverbs', 6, 2, 'you are snared by the utterance of your lips,  
    caught by the words of your mouth.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 3, 'So do this, my child, and save yourself,  
    for you have come into your neighbor"s power:  
    go, hurry, and plead with your neighbor.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 4, 'Give your eyes no sleep  
    and your eyelids no slumber;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 5, 'save yourself like a gazelle from the hunter,  
    like a bird from the hand of the fowler.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 6, 'Go to the ant, you lazybones;  
    consider its ways, and be wise.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 7, 'Without having any chief  
    or officer or ruler,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 8, 'it prepares its food in summer,  
    and gathers its sustenance in harvest.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 9, 'How long will you lie there, O lazybones?  
    When will you rise from your sleep?', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 10, 'A little sleep, a little slumber,  
    a little folding of the hands to rest,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 11, 'and poverty will come upon you like a robber,  
    and want, like an armed warrior.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 12, 'A scoundrel and a villain  
    goes around with crooked speech,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 13, 'winking the eyes, shuffling the feet,  
    pointing the fingers,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 14, 'with perverted mind devising evil,  
    continually sowing discord;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 15, 'on such a one calamity will descend suddenly;  
    in a moment, damage beyond repair.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 16, 'There are six things that the LORD hates,  
    seven that are an abomination to him:', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 17, 'haughty eyes, a lying tongue,  
    and hands that shed innocent blood,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 18, 'a heart that devises wicked plans,  
    feet that hurry to run to evil,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 19, 'a lying witness who testifies falsely,  
    and one who sows discord in a family.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 20, 'My child, keep your father"s commandment,  
    and do not forsake your mother"s teaching.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 21, 'Bind them upon your heart always;  
    tie them around your neck.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 22, 'When you walk, they will lead you;  
    when you lie down, they will watch over you;  
    and when you awake, they will talk with you.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 23, 'For the commandment is a lamp and the teaching a light,  
    and the reproofs of discipline are the way of life,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 24, 'to preserve you from the wife of another,  
    from the smooth tongue of the adulteress.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 25, 'Do not desire her beauty in your heart,  
    and do not let her capture you with her eyelashes;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 26, 'for a prostitute"s fee is only a loaf of bread,  
    but the wife of another stalks a man"s very life.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 27, 'Can fire be carried in the bosom  
    without burning one"s clothes?', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 28, 'Or can one walk on hot coals  
    without scorching the feet?', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 29, 'So is he who sleeps with his neighbor"s wife;  
    no one who touches her will go unpunished.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 30, 'Thieves are not despised who steal only  
    to satisfy their appetite when they are hungry.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 31, 'Yet if they are caught, they will pay sevenfold;  
    they will forfeit all the goods of their house.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 32, 'But he who commits adultery has no sense;  
    he who does it destroys himself.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 33, 'He will get wounds and dishonor,  
    and his disgrace will not be wiped away.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 34, 'For jealousy arouses a husband"s fury,  
    and he shows no restraint when he takes revenge.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 6, 35, 'He will accept no compensation,  
    and refuses a bribe no matter how great.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 7, 1, 'My child, keep my words  
    and store up my commandments with you;', 'en', 'NRSV-CE', 'The False Attractions of Adultery'),
(20, 'Ams', 'Proverbs', 7, 2, 'keep my commandments and live,  
    keep my teachings as the apple of your eye;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 7, 3, 'bind them on your fingers,  
    write them on the tablet of your heart.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 7, 4, 'Say to wisdom, "You are my sister,"  
    and call insight your intimate friend,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 7, 5, 'that they may keep you from the loose woman,  
    from the adulteress with her smooth words.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 7, 6, 'For at the window of my house  
    I looked out through my lattice,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 7, 7, 'and I saw among the simple ones,  
    I observed among the youths,  
    a young man without sense,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 7, 8, 'passing along the street near her corner,  
    taking the road to her house', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 7, 9, 'in the twilight, in the evening,  
    at the time of night and darkness.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 7, 10, 'Then a woman comes toward him,  
    decked out like a prostitute, wily of heart.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 7, 11, 'She is loud and wayward;  
    her feet do not stay at home;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 7, 12, 'now in the street, now in the squares,  
    and at every corner she lies in wait.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 7, 13, 'She seizes him and kisses him,  
    and with impudent face she says to him:', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 7, 14, '"I had to offer sacrifices,  
    and today I have paid my vows;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 7, 15, 'so now I have come out to meet you,  
    to seek you eagerly, and I have found you!', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 7, 16, 'I have decked my couch with coverings,  
    colored spreads of Egyptian linen;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 7, 17, 'I have perfumed my bed with myrrh,  
    aloes, and cinnamon.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 7, 18, 'Come, let us take our fill of love until morning;  
    let us delight ourselves with love.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 7, 19, 'For my husband is not at home;  
    he has gone on a long journey.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 7, 20, 'He took a bag of money with him;  
    he will not come home until full moon."', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 7, 21, 'With much seductive speech she persuades him;  
    with her smooth talk she compels him.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 7, 22, 'Right away he follows her,  
    and goes like an ox to the slaughter,  
or bounds like a stag toward the trap', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 7, 23, 'until an arrow pierces its entrails.  
He is like a bird rushing into a snare,  
    not knowing that it will cost him his life.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 7, 24, 'And now, my children, listen to me,  
    and be attentive to the words of my mouth.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 7, 25, 'Do not let your hearts turn aside to her ways;  
    do not stray into her paths.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 7, 26, 'For many are those she has laid low,  
    and numerous are her victims.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 7, 27, 'Her house is the way to Sheol,  
    going down to the chambers of death.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 8, 1, 'Does not wisdom call,  
    and does not understanding raise her voice?', 'en', 'NRSV-CE', 'The Gifts of Wisdom'),
(20, 'Ams', 'Proverbs', 8, 2, 'On the heights, beside the way,  
    at the crossroads she takes her stand;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 3, 'beside the gates in front of the town,  
    at the entrance of the portals she cries out:', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 4, '"To you, O people, I call,  
    and my cry is to all that live.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 5, 'O simple ones, learn prudence;  
    acquire intelligence, you who lack it.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 6, 'Hear, for I will speak noble things,  
    and from my lips will come what is right;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 7, 'for my mouth will utter truth;  
    wickedness is an abomination to my lips.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 8, 'All the words of my mouth are righteous;  
    there is nothing twisted or crooked in them.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 9, 'They are all straight to one who understands  
    and right to those who find knowledge.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 10, 'Take my instruction instead of silver,  
    and knowledge rather than choice gold;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 11, 'for wisdom is better than jewels,  
    and all that you may desire cannot compare with her.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 12, 'I, wisdom, live with prudence,  
    and I attain knowledge and discretion.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 13, 'The fear of the LORD is hatred of evil.  
Pride and arrogance and the way of evil  
    and perverted speech I hate.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 14, 'I have good advice and sound wisdom;  
    I have insight, I have strength.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 15, 'By me kings reign,  
    and rulers decree what is just;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 16, 'by me rulers rule,  
    and nobles, all who govern rightly.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 17, 'I love those who love me,  
    and those who seek me diligently find me.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 18, 'Riches and honor are with me,  
    enduring wealth and prosperity.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 19, 'My fruit is better than gold, even fine gold,  
    and my yield than choice silver.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 20, 'I walk in the way of righteousness,  
    along the paths of justice,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 21, 'endowing with wealth those who love me,  
    and filling their treasuries.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 22, 'The LORD created me at the beginning of his work,  
    the first of his acts of long ago.', 'en', 'NRSV-CE', 'Wisdom"s Part in Creation'),
(20, 'Ams', 'Proverbs', 8, 23, 'Ages ago I was set up,  
    at the first, before the beginning of the earth.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 24, 'When there were no depths I was brought forth,  
    when there were no springs abounding with water.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 25, 'Before the mountains had been shaped,  
    before the hills, I was brought forth--', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 26, 'when he had not yet made earth and fields,  
    or the world"s first bits of soil.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 27, 'When he established the heavens, I was there,  
    when he drew a circle on the face of the deep,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 28, 'when he made firm the skies above,  
    when he established the fountains of the deep,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 29, 'when he assigned to the sea its limit,  
    so that the waters might not transgress his command,  
when he marked out the foundations of the earth,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 30, 'then I was beside him, like a master worker;  
and I was daily his delight,  
    rejoicing before him always,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 31, 'rejoicing in his inhabited world  
    and delighting in the human race.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 32, '"And now, my children, listen to me:  
    happy are those who keep my ways.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 33, 'Hear instruction and be wise,  
    and do not neglect it.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 34, 'Happy is the one who listens to me,  
    watching daily at my gates,  
    waiting beside my doors.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 35, 'For whoever finds me finds life  
    and obtains favor from the LORD;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 8, 36, 'but those who miss me injure themselves;  
    all who hate me love death."', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 9, 1, 'Wisdom has built her house,  
    she has hewn her seven pillars.', 'en', 'NRSV-CE', 'Wisdom"s Feast'),
(20, 'Ams', 'Proverbs', 9, 2, 'She has slaughtered her animals, she has mixed her wine,  
    she has also set her table.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 9, 3, 'She has sent out her servant-girls, she calls  
    from the highest places in the town,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 9, 4, '"You that are simple, turn in here!"  
    To those without sense she says,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 9, 5, '"Come, eat of my bread  
    and drink of the wine I have mixed.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 9, 6, 'Lay aside immaturity, and live,  
    and walk in the way of insight."', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 9, 7, 'Whoever corrects a scoffer wins abuse;  
    whoever rebukes the wicked gets hurt.', 'en', 'NRSV-CE', 'General Maxims'),
(20, 'Ams', 'Proverbs', 9, 8, 'A scoffer who is rebuked will only hate you;  
    the wise, when rebuked, will love you.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 9, 9, 'Give instruction to the wise, and they will become wiser still;  
    teach the righteous and they will gain in learning.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 9, 10, 'The fear of the LORD is the beginning of wisdom,  
    and the knowledge of the Holy One is insight.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 9, 11, 'For by me your days will be multiplied,  
    and years will be added to your life.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 9, 12, 'If you are wise, you are wise for yourself;  
    if you scoff, you alone will bear it.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 9, 13, 'The foolish woman is loud;  
    she is ignorant and knows nothing.', 'en', 'NRSV-CE', 'Folly"s Invitation and Promise'),
(20, 'Ams', 'Proverbs', 9, 14, 'She sits at the door of her house,  
    on a seat at the high places of the town,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 9, 15, 'calling to those who pass by,  
    who are going straight on their way,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 9, 16, '"You who are simple, turn in here!"  
    And to those without sense she says,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 9, 17, '"Stolen water is sweet,  
    and bread eaten in secret is pleasant."', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 9, 18, 'But they do not know that the dead are there,  
    that her guests are in the depths of Sheol.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 10, 1, 'The proverbs of Solomon.
A wise child makes a glad father,  
    but a foolish child is a mother"s grief.', 'en', 'NRSV-CE', 'Wise Sayings of Solomon'),
(20, 'Ams', 'Proverbs', 10, 2, 'Treasures gained by wickedness do not profit,  
    but righteousness delivers from death.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 3, 'The LORD does not let the righteous go hungry,  
    but he thwarts the craving of the wicked.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 4, 'A slack hand causes poverty,  
    but the hand of the diligent makes rich.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 5, 'A child who gathers in summer is prudent,  
    but a child who sleeps in harvest brings shame.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 6, 'Blessings are on the head of the righteous,  
    but the mouth of the wicked conceals violence.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 7, 'The memory of the righteous is a blessing,  
    but the name of the wicked will rot.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 8, 'The wise of heart will heed commandments,  
    but a babbling fool will come to ruin.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 9, 'Whoever walks in integrity walks securely,  
    but whoever follows perverse ways will be found out.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 10, 'Whoever winks the eye causes trouble,  
    but the one who rebukes boldly makes peace.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 11, 'The mouth of the righteous is a fountain of life,  
    but the mouth of the wicked conceals violence.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 12, 'Hatred stirs up strife,  
    but love covers all offenses.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 13, 'On the lips of one who has understanding wisdom is found,  
    but a rod is for the back of one who lacks sense.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 14, 'The wise lay up knowledge,  
    but the babbling of a fool brings ruin near.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 15, 'The wealth of the rich is their fortress;  
    the poverty of the poor is their ruin.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 16, 'The wage of the righteous leads to life,  
    the gain of the wicked to sin.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 17, 'Whoever heeds instruction is on the path to life,  
    but one who rejects a rebuke goes astray.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 18, 'Lying lips conceal hatred,  
    and whoever utters slander is a fool.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 19, 'When words are many, transgression is not lacking,  
    but the prudent are restrained in speech.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 20, 'The tongue of the righteous is choice silver;  
    the mind of the wicked is of little worth.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 21, 'The lips of the righteous feed many,  
    but fools die for lack of sense.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 22, 'The blessing of the LORD makes rich,  
    and he adds no sorrow with it.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 23, 'Doing wrong is like sport to a fool,  
    but wise conduct is pleasure to a person of understanding.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 24, 'What the wicked dread will come upon them,  
    but the desire of the righteous will be granted.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 25, 'When the tempest passes, the wicked are no more,  
    but the righteous are established forever.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 26, 'Like vinegar to the teeth, and smoke to the eyes,  
    so are the lazy to their employers.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 27, 'The fear of the LORD prolongs life,  
    but the years of the wicked will be short.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 28, 'The hope of the righteous ends in gladness,  
    but the expectation of the wicked comes to nothing.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 29, 'The way of the LORD is a stronghold for the upright,  
    but destruction for evildoers.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 30, 'The righteous will never be removed,  
    but the wicked will not remain in the land.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 31, 'The mouth of the righteous brings forth wisdom,  
    but the perverse tongue will be cut off.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 10, 32, 'The lips of the righteous know what is acceptable,  
    but the mouth of the wicked what is perverse.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 11, 1, 'A false balance is an abomination to the LORD,  
    but an accurate weight is his delight.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 2, 'When pride comes, then comes disgrace;  
    but wisdom is with the humble.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 3, 'The integrity of the upright guides them,  
    but the crookedness of the treacherous destroys them.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 4, 'Riches do not profit in the day of wrath,  
    but righteousness delivers from death.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 5, 'The righteousness of the blameless keeps their ways straight,  
    but the wicked fall by their own wickedness.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 6, 'The righteousness of the upright saves them,  
    but the treacherous are taken captive by their schemes.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 7, 'When the wicked die, their hope perishes,  
    and the expectation of the godless comes to nothing.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 8, 'The righteous are delivered from trouble,  
    and the wicked get into it instead.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 9, 'With their mouths the godless would destroy their neighbors,  
    but by knowledge the righteous are delivered.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 10, 'When it goes well with the righteous, the city rejoices;  
    and when the wicked perish, there is jubilation.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 11, 'By the blessing of the upright a city is exalted,  
    but it is overthrown by the mouth of the wicked.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 12, 'Whoever belittles another lacks sense,  
    but an intelligent person remains silent.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 13, 'A gossip goes about telling secrets,  
    but one who is trustworthy in spirit keeps a confidence.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 14, 'Where there is no guidance, a nation falls,  
    but in an abundance of counselors there is safety.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 15, 'To guarantee loans for a stranger brings trouble,  
    but there is safety in refusing to do so.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 16, 'A gracious woman gets honor,  
    but she who hates virtue is covered with shame.  
The timid become destitute,  
    but the aggressive gain riches.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 17, 'Those who are kind reward themselves,  
    but the cruel do themselves harm.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 18, 'The wicked earn no real gain,  
    but those who sow righteousness get a true reward.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 19, 'Whoever is steadfast in righteousness will live,  
    but whoever pursues evil will die.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 20, 'Crooked minds are an abomination to the LORD,  
    but those of blameless ways are his delight.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 21, 'Be assured, the wicked will not go unpunished,  
    but those who are righteous will escape.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 22, 'Like a gold ring in a pig"s snout  
    is a beautiful woman without good sense.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 23, 'The desire of the righteous ends only in good;  
    the expectation of the wicked in wrath.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 24, 'Some give freely, yet grow all the richer;  
    others withhold what is due, and only suffer want.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 25, 'A generous person will be enriched,  
    and one who gives water will get water.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 26, 'The people curse those who hold back grain,  
    but a blessing is on the head of those who sell it.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 27, 'Whoever diligently seeks good seeks favor,  
    but evil comes to the one who searches for it.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 28, 'Those who trust in their riches will wither,  
    but the righteous will flourish like green leaves.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 29, 'Those who trouble their households will inherit wind,  
    and the fool will be servant to the wise.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 30, 'The fruit of the righteous is a tree of life,  
    but violence takes lives away.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 11, 31, 'If the righteous are repaid on earth,  
    how much more the wicked and the sinner!', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 12, 1, 'Whoever loves discipline loves knowledge,  
    but those who hate to be rebuked are stupid.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 2, 'The good obtain favor from the LORD,  
    but those who devise evil he condemns.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 3, 'No one finds security by wickedness,  
    but the root of the righteous will never be moved.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 4, 'A good wife is the crown of her husband,  
    but she who brings shame is like rottenness in his bones.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 5, 'The thoughts of the righteous are just;  
    the advice of the wicked is treacherous.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 6, 'The words of the wicked are a deadly ambush,  
    but the speech of the upright delivers them.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 7, 'The wicked are overthrown and are no more,  
    but the house of the righteous will stand.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 8, 'One is commended for good sense,  
    but a perverse mind is despised.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 9, 'Better to be despised and have a servant,  
    than to be self-important and lack food.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 10, 'The righteous know the needs of their animals,  
    but the mercy of the wicked is cruel.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 11, 'Those who till their land will have plenty of food,  
    but those who follow worthless pursuits have no sense.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 12, 'The wicked covet the proceeds of wickedness,  
    but the root of the righteous bears fruit.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 13, 'The evil are ensnared by the transgression of their lips,  
    but the righteous escape from trouble.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 14, 'From the fruit of the mouth one is filled with good things,  
    and manual labor has its reward.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 15, 'Fools think their own way is right,  
    but the wise listen to advice.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 16, 'Fools show their anger at once,  
    but the prudent ignore an insult.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 17, 'Whoever speaks the truth gives honest evidence,  
    but a false witness speaks deceitfully.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 18, 'Rash words are like sword thrusts,  
    but the tongue of the wise brings healing.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 19, 'Truthful lips endure forever,  
    but a lying tongue lasts only a moment.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 20, 'Deceit is in the mind of those who plan evil,  
    but those who counsel peace have joy.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 21, 'No harm happens to the righteous,  
    but the wicked are filled with trouble.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 22, 'Lying lips are an abomination to the LORD,  
    but those who act faithfully are his delight.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 23, 'One who is clever conceals knowledge,  
    but the mind of a fool broadcasts folly.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 24, 'The hand of the diligent will rule,  
    while the lazy will be put to forced labor.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 25, 'Anxiety weighs down the human heart,  
    but a good word cheers it up.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 26, 'The righteous gives good advice to friends,  
    but the way of the wicked leads astray.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 27, 'The lazy do not roast their game,  
    but the diligent obtain precious wealth.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 12, 28, 'In the path of righteousness there is life,  
    in walking its path there is no death.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 13, 1, 'A wise child loves discipline,  
    but a scoffer does not listen to rebuke.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 13, 2, 'From the fruit of their words good persons eat good things,  
    but the desire of the treacherous is for wrongdoing.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 13, 3, 'Those who guard their mouths preserve their lives;  
    those who open wide their lips come to ruin.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 13, 4, 'The appetite of the lazy craves, and gets nothing,  
    while the appetite of the diligent is richly supplied.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 13, 5, 'The righteous hate falsehood,  
    but the wicked act shamefully and disgracefully.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 13, 6, 'Righteousness guards one whose way is upright,  
    but sin overthrows the wicked.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 13, 7, 'Some pretend to be rich, yet have nothing;  
    others pretend to be poor, yet have great wealth.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 13, 8, 'Wealth is a ransom for a person"s life,  
    but the poor get no threats.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 13, 9, 'The light of the righteous rejoices,  
    but the lamp of the wicked goes out.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 13, 10, 'By insolence the heedless make strife,  
    but wisdom is with those who take advice.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 13, 11, 'Wealth hastily gotten will dwindle,  
    but those who gather little by little will increase it.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 13, 12, 'Hope deferred makes the heart sick,  
    but a desire fulfilled is a tree of life.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 13, 13, 'Those who despise the word bring destruction on themselves,  
    but those who respect the commandment will be rewarded.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 13, 14, 'The teaching of the wise is a fountain of life,  
    so that one may avoid the snares of death.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 13, 15, 'Good sense wins favor,  
    but the way of the faithless is their ruin.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 13, 16, 'The clever do all things intelligently,  
    but the fool displays folly.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 13, 17, 'A bad messenger brings trouble,  
    but a faithful envoy, healing.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 13, 18, 'Poverty and disgrace are for the one who ignores instruction,  
    but one who heeds reproof is honored.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 13, 19, 'A desire realized is sweet to the soul,  
    but to turn away from evil is an abomination to fools.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 13, 20, 'Whoever walks with the wise becomes wise,  
    but the companion of fools suffers harm.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 13, 21, 'Misfortune pursues sinners,  
    but prosperity rewards the righteous.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 13, 22, 'The good leave an inheritance to their children"s children,  
    but the sinner"s wealth is laid up for the righteous.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 13, 23, 'The field of the poor may yield much food,  
    but it is swept away through injustice.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 13, 24, 'Those who spare the rod hate their children,  
    but those who love them are diligent to discipline them.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 13, 25, 'The righteous have enough to satisfy their appetite,  
    but the belly of the wicked is empty.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 14, 1, 'The wise woman builds her house,  
    but the foolish tears it down with her own hands.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 2, 'Those who walk uprightly fear the LORD,  
    but one who is devious in conduct despises him.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 3, 'The talk of fools is a rod for their backs,  
    but the lips of the wise preserve them.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 4, 'Where there are no oxen, there is no grain;  
    abundant crops come by the strength of the ox.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 5, 'A faithful witness does not lie,  
    but a false witness breathes out lies.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 6, 'A scoffer seeks wisdom in vain,  
    but knowledge is easy for one who understands.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 7, 'Leave the presence of a fool,  
    for there you do not find words of knowledge.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 8, 'It is the wisdom of the clever to understand where they go,  
    but the folly of fools misleads.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 9, 'Fools mock at the guilt offering,  
    but the upright enjoy God"s favor.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 10, 'The heart knows its own bitterness,  
    and no stranger shares its joy.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 11, 'The house of the wicked is destroyed,  
    but the tent of the upright flourishes.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 12, 'There is a way that seems right to a person,  
    but its end is the way to death.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 13, 'Even in laughter the heart is sad,  
    and the end of joy is grief.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 14, 'The perverse get what their ways deserve,  
    and the good, what their deeds deserve.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 15, 'The simple believe everything,  
    but the clever consider their steps.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 16, 'The wise are cautious and turn away from evil,  
    but the fool throws off restraint and is careless.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 17, 'One who is quick-tempered acts foolishly,  
    and the schemer is hated.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 18, 'The simple are adorned with folly,  
    but the clever are crowned with knowledge.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 19, 'The evil bow down before the good,  
    the wicked at the gates of the righteous.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 20, 'The poor are disliked even by their neighbors,  
    but the rich have many friends.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 21, 'Those who despise their neighbors are sinners,  
    but happy are those who are kind to the poor.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 22, 'Do they not err that plan evil?  
    Those who plan good find loyalty and faithfulness.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 23, 'In all toil there is profit,  
    but mere talk leads only to poverty.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 24, 'The crown of the wise is their wisdom,  
    but folly is the garland of fools.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 25, 'A truthful witness saves lives,  
    but one who utters lies is a betrayer.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 26, 'In the fear of the LORD one has strong confidence,  
    and one"s children will have a refuge.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 27, 'The fear of the LORD is a fountain of life,  
    so that one may avoid the snares of death.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 28, 'The glory of a king is a multitude of people;  
    without people a prince is ruined.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 29, 'Whoever is slow to anger has great understanding,  
    but one who has a hasty temper exalts folly.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 30, 'A tranquil mind gives life to the flesh,  
    but passion makes the bones rot.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 31, 'Those who oppress the poor insult their Maker,  
    but those who are kind to the needy honor him.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 32, 'The wicked are overthrown by their evildoing,  
    but the righteous find a refuge in their integrity.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 33, 'Wisdom is at home in the mind of one who has understanding,  
    but it is not known in the heart of fools.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 34, 'Righteousness exalts a nation,  
    but sin is a reproach to any people.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 14, 35, 'A servant who deals wisely has the king"s favor,  
    but his wrath falls on one who acts shamefully.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 15, 1, 'A soft answer turns away wrath,  
    but a harsh word stirs up anger.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 2, 'The tongue of the wise dispenses knowledge,  
    but the mouths of fools pour out folly.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 3, 'The eyes of the LORD are in every place,  
    keeping watch on the evil and the good.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 4, 'A gentle tongue is a tree of life,  
    but perverseness in it breaks the spirit.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 5, 'A fool despises a parent"s instruction,  
    but the one who heeds admonition is prudent.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 6, 'In the house of the righteous there is much treasure,  
    but trouble befalls the income of the wicked.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 7, 'The lips of the wise spread knowledge;  
    not so the minds of fools.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 8, 'The sacrifice of the wicked is an abomination to the LORD,  
    but the prayer of the upright is his delight.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 9, 'The way of the wicked is an abomination to the LORD,  
    but he loves the one who pursues righteousness.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 10, 'There is severe discipline for one who forsakes the way,  
    but one who hates a rebuke will die.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 11, 'Sheol and Abaddon lie open before the LORD,  
    how much more human hearts!', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 12, 'Scoffers do not like to be rebuked;  
    they will not go to the wise.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 13, 'A glad heart makes a cheerful countenance,  
    but by sorrow of heart the spirit is broken.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 14, 'The mind of one who has understanding seeks knowledge,  
    but the mouths of fools feed on folly.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 15, 'All the days of the poor are hard,  
    but a cheerful heart has a continual feast.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 16, 'Better is a little with the fear of the LORD  
    than great treasure and trouble with it.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 17, 'Better is a dinner of vegetables where love is  
    than a fatted ox and hatred with it.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 18, 'Those who are hot-tempered stir up strife,  
    but those who are slow to anger calm contention.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 19, 'The way of the lazy is overgrown with thorns,  
    but the path of the upright is a level highway.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 20, 'A wise child makes a glad father,  
    but the foolish despise their mothers.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 21, 'Folly is a joy to one who has no sense,  
    but a person of understanding walks straight ahead.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 22, 'Without counsel, plans go wrong,  
    but with many advisers they succeed.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 23, 'To make an apt answer is a joy to anyone,  
    and a word in season, how good it is!', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 24, 'For the wise the path of life leads upward,  
    in order to avoid Sheol below.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 25, 'The LORD tears down the house of the proud,  
    but maintains the widow"s boundaries.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 26, 'Evil plans are an abomination to the LORD,  
    but gracious words are pure.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 27, 'Those who are greedy for unjust gain make trouble for their households,  
    but those who hate bribes will live.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 28, 'The mind of the righteous ponders how to answer,  
    but the mouth of the wicked pours out evil.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 29, 'The LORD is far from the wicked,  
    but he hears the prayer of the righteous.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 30, 'The light of the eyes rejoices the heart,  
    and good news refreshes the body.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 31, 'The ear that heeds wholesome admonition  
    will lodge among the wise.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 32, 'Those who ignore instruction despise themselves,  
    but those who heed admonition gain understanding.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 15, 33, 'The fear of the LORD is instruction in wisdom,  
    and humility goes before honor.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 16, 1, 'The plans of the mind belong to mortals,  
    but the answer of the tongue is from the LORD.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 2, 'All one"s ways may be pure in one"s own eyes,  
    but the LORD weighs the spirit.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 3, 'Commit your work to the LORD,  
    and your plans will be established.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 4, 'The LORD has made everything for its purpose,  
    even the wicked for the day of trouble.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 5, 'All those who are arrogant are an abomination to the LORD;  
    be assured, they will not go unpunished.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 6, 'By loyalty and faithfulness iniquity is atoned for,  
    and by the fear of the LORD one avoids evil.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 7, 'When the ways of people please the LORD,  
    he causes even their enemies to be at peace with them.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 8, 'Better is a little with righteousness  
    than large income with injustice.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 9, 'The human mind plans the way,  
    but the LORD directs the steps.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 10, 'Inspired decisions are on the lips of a king;  
    his mouth does not sin in judgment.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 11, 'Honest balances and scales are the LORD"s;  
    all the weights in the bag are his work.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 12, 'It is an abomination to kings to do evil,  
    for the throne is established by righteousness.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 13, 'Righteous lips are the delight of a king,  
    and he loves those who speak what is right.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 14, 'A king"s wrath is a messenger of death,  
    and whoever is wise will appease it.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 15, 'In the light of a king"s face there is life,  
    and his favor is like the clouds that bring the spring rain.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 16, 'How much better to get wisdom than gold!  
    To get understanding is to be chosen rather than silver.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 17, 'The highway of the upright avoids evil;  
    those who guard their way preserve their lives.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 18, 'Pride goes before destruction,  
    and a haughty spirit before a fall.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 19, 'It is better to be of a lowly spirit among the poor  
    than to divide the spoil with the proud.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 20, 'Those who are attentive to a matter will prosper,  
    and happy are those who trust in the LORD.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 21, 'The wise of heart is called perceptive,  
    and pleasant speech increases persuasiveness.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 22, 'Wisdom is a fountain of life to one who has it,  
    but folly is the punishment of fools.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 23, 'The mind of the wise makes their speech judicious,  
    and adds persuasiveness to their lips.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 24, 'Pleasant words are like a honeycomb,  
    sweetness to the soul and health to the body.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 25, 'Sometimes there is a way that seems to be right,  
    but in the end it is the way to death.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 26, 'The appetite of workers works for them;  
    their hunger urges them on.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 27, 'Scoundrels concoct evil,  
    and their speech is like a scorching fire.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 28, 'A perverse person spreads strife,  
    and a whisperer separates close friends.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 29, 'The violent entice their neighbors,  
    and lead them in a way that is not good.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 30, 'One who winks the eyes plans perverse things;  
    one who compresses the lips brings evil to pass.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 31, 'Gray hair is a crown of glory;  
    it is gained in a righteous life.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 32, 'One who is slow to anger is better than the mighty,  
    and one whose temper is controlled than one who captures a city.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 16, 33, 'The lot is cast into the lap,  
    but the decision is the LORD"s alone.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 17, 1, 'Better is a dry morsel with quiet  
    than a house full of feasting with strife.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 2, 'A slave who deals wisely will rule over a child who acts shamefully,  
    and will share the inheritance as one of the family.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 3, 'The crucible is for silver, and the furnace is for gold,  
    but the LORD tests the heart.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 4, 'An evildoer listens to wicked lips;  
    and a liar gives heed to a mischievous tongue.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 5, 'Those who mock the poor insult their Maker;  
    those who are glad at calamity will not go unpunished.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 6, 'Grandchildren are the crown of the aged,  
    and the glory of children is their parents.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 7, 'Fine speech is not becoming to a fool;  
    still less is false speech to a ruler.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 8, 'A bribe is like a magic stone in the eyes of those who give it;  
    wherever they turn they prosper.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 9, 'One who forgives an affront fosters friendship,  
    but one who dwells on disputes will alienate a friend.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 10, 'A rebuke strikes deeper into a discerning person  
    than a hundred blows into a fool.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 11, 'Evil people seek only rebellion,  
    but a cruel messenger will be sent against them.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 12, 'Better to meet a she-bear robbed of its cubs  
    than to confront a fool immersed in folly.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 13, 'Evil will not depart from the house  
    of one who returns evil for good.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 14, 'The beginning of strife is like letting out water;  
    so stop before the quarrel breaks out.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 15, 'One who justifies the wicked and one who condemns the righteous  
    are both alike an abomination to the LORD.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 16, 'Why should fools have a price in hand  
    to buy wisdom, when they have no mind to learn?', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 17, 'A friend loves at all times,  
    and kinsfolk are born to share adversity.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 18, 'It is senseless to give a pledge,  
    to become surety for a neighbor.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 19, 'One who loves transgression loves strife;  
    one who builds a high threshold invites broken bones.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 20, 'The crooked of mind do not prosper,  
    and the perverse of tongue fall into calamity.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 21, 'The one who begets a fool gets trouble;  
    the parent of a fool has no joy.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 22, 'A cheerful heart is a good medicine,  
    but a downcast spirit dries up the bones.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 23, 'The wicked accept a concealed bribe  
    to pervert the ways of justice.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 24, 'The discerning person looks to wisdom,  
    but the eyes of a fool to the ends of the earth.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 25, 'Foolish children are a grief to their father  
    and bitterness to her who bore them.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 26, 'To impose a fine on the innocent is not right,  
    or to flog the noble for their integrity.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 27, 'One who spares words is knowledgeable;  
    one who is cool in spirit has understanding.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 17, 28, 'Even fools who keep silent are considered wise;  
    when they close their lips, they are deemed intelligent.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 18, 1, 'The one who lives alone is self-indulgent,  
    showing contempt for all who have sound judgment.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 18, 2, 'A fool takes no pleasure in understanding,  
    but only in expressing personal opinion.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 18, 3, 'When wickedness comes, contempt comes also;  
    and with dishonor comes disgrace.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 18, 4, 'The words of the mouth are deep waters;  
    the fountain of wisdom is a gushing stream.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 18, 5, 'It is not right to be partial to the guilty,  
    or to subvert the innocent in judgment.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 18, 6, 'A fool"s lips bring strife,  
    and a fool"s mouth invites a flogging.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 18, 7, 'The mouths of fools are their ruin,  
    and their lips a snare to themselves.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 18, 8, 'The words of a whisperer are like delicious morsels;  
    they go down into the inner parts of the body.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 18, 9, 'One who is slack in work  
    is close kin to a vandal.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 18, 10, 'The name of the LORD is a strong tower;  
    the righteous run into it and are safe.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 18, 11, 'The wealth of the rich is their strong city;  
    in their imagination it is like a high wall.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 18, 12, 'Before destruction one"s heart is haughty,  
    but humility goes before honor.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 18, 13, 'If one gives answer before hearing,  
    it is folly and shame.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 18, 14, 'The human spirit will endure sickness;  
    but a broken spirit--who can bear?', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 18, 15, 'An intelligent mind acquires knowledge,  
    and the ear of the wise seeks knowledge.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 18, 16, 'A gift opens doors;  
    it gives access to the great.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 18, 17, 'The one who first states a case seems right,  
    until the other comes and cross-examines.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 18, 18, 'Casting the lot puts an end to disputes  
    and decides between powerful contenders.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 18, 19, 'An ally offended is stronger than a city;  
    such quarreling is like the bars of a castle.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 18, 20, 'From the fruit of the mouth one"s stomach is satisfied;  
    the yield of the lips brings satisfaction.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 18, 21, 'Death and life are in the power of the tongue,  
    and those who love it will eat its fruits.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 18, 22, 'He who finds a wife finds a good thing,  
    and obtains favor from the LORD.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 18, 23, 'The poor use entreaties,  
    but the rich answer roughly.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 18, 24, 'Some friends play at friendship  
    but a true friend sticks closer than one"s nearest kin.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 19, 1, 'Better the poor walking in integrity  
    than one perverse of speech who is a fool.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 2, 'Desire without knowledge is not good,  
    and one who moves too hurriedly misses the way.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 3, 'One"s own folly leads to ruin,  
    yet the heart rages against the LORD.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 4, 'Wealth brings many friends,  
    but the poor are left friendless.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 5, 'A false witness will not go unpunished,  
    and a liar will not escape.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 6, 'Many seek the favor of the generous,  
    and everyone is a friend to a giver of gifts.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 7, 'If the poor are hated even by their kin,  
    how much more are they shunned by their friends!  
When they call after them, they are not there.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 8, 'To get wisdom is to love oneself;  
    to keep understanding is to prosper.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 9, 'A false witness will not go unpunished,  
    and the liar will perish.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 10, 'It is not fitting for a fool to live in luxury,  
    much less for a slave to rule over princes.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 11, 'Those with good sense are slow to anger,  
    and it is their glory to overlook an offense.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 12, 'A king"s anger is like the growling of a lion,  
    but his favor is like dew on the grass.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 13, 'A stupid child is ruin to a father,  
    and a wife"s quarreling is a continual dripping of rain.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 14, 'House and wealth are inherited from parents,  
    but a prudent wife is from the LORD.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 15, 'Laziness brings on deep sleep;  
    an idle person will suffer hunger.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 16, 'Those who keep the commandment will live;  
    those who are heedless of their ways will die.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 17, 'Whoever is kind to the poor lends to the LORD,  
    and will be repaid in full.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 18, 'Discipline your children while there is hope;  
    do not set your heart on their destruction.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 19, 'A violent tempered person will pay the penalty;  
    if you effect a rescue, you will only have to do it again.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 20, 'Listen to advice and accept instruction,  
    that you may gain wisdom for the future.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 21, 'The human mind may devise many plans,  
    but it is the purpose of the LORD that will be established.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 22, 'What is desirable in a person is loyalty,  
    and it is better to be poor than a liar.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 23, 'The fear of the LORD is life indeed;  
    filled with it one rests secure  
    and suffers no harm.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 24, 'The lazy person buries a hand in the dish,  
    and will not even bring it back to the mouth.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 25, 'Strike a scoffer, and the simple will learn prudence;  
    reprove the intelligent, and they will gain knowledge.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 26, 'Those who do violence to their father and chase away their mother  
    are children who cause shame and bring reproach.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 27, 'Cease straying, my child, from the words of knowledge,  
    in order that you may hear instruction.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 28, 'A worthless witness mocks at justice,  
    and the mouth of the wicked devours iniquity.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 19, 29, 'Condemnation is ready for scoffers,  
    and flogging for the backs of fools.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 20, 1, 'Wine is a mocker, strong drink a brawler,  
    and whoever is led astray by it is not wise.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 2, 'The dread anger of a king is like the growling of a lion;  
    anyone who provokes him to anger forfeits life itself.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 3, 'It is honorable to refrain from strife,  
    but every fool is quick to quarrel.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 4, 'The lazy person does not plow in season;  
    harvest comes, and there is nothing to be found.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 5, 'The purposes in the human mind are like deep water,  
    but the intelligent will draw them out.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 6, 'Many proclaim themselves loyal,  
    but who can find one worthy of trust?', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 7, 'The righteous walk in integrity--  
    happy are the children who follow them!', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 8, 'A king who sits on the throne of judgment  
    winnows all evil with his eyes.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 9, 'Who can say, "I have made my heart clean;  
    I am pure from my sin"?', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 10, 'Diverse weights and diverse measures  
    are both alike an abomination to the LORD.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 11, 'Even children make themselves known by their acts,  
    by whether what they do is pure and right.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 12, 'The hearing ear and the seeing eye--  
    the LORD has made them both.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 13, 'Do not love sleep, or else you will come to poverty;  
    open your eyes, and you will have plenty of bread.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 14, '"Bad, bad," says the buyer,  
    then goes away and boasts.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 15, 'There is gold, and abundance of costly stones;  
    but the lips informed by knowledge are a precious jewel.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 16, 'Take the garment of one who has given surety for a stranger;  
    seize the pledge given as surety for foreigners.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 17, 'Bread gained by deceit is sweet,  
    but afterward the mouth will be full of gravel.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 18, 'Plans are established by taking advice;  
    wage war by following wise guidance.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 19, 'A gossip reveals secrets;  
    therefore do not associate with a babbler.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 20, 'If you curse father or mother,  
    your lamp will go out in utter darkness.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 21, 'An estate quickly acquired in the beginning  
    will not be blessed in the end.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 22, 'Do not say, "I will repay evil";  
    wait for the LORD, and he will help you.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 23, 'Differing weights are an abomination to the LORD,  
    and false scales are not good.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 24, 'All our steps are ordered by the LORD;  
    how then can we understand our own ways?', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 25, 'It is a snare for one to say rashly, "It is holy,"  
    and begin to reflect only after making a vow.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 26, 'A wise king winnows the wicked,  
    and drives the wheel over them.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 27, 'The human spirit is the lamp of the LORD,  
    searching every inmost part.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 28, 'Loyalty and faithfulness preserve the king,  
    and his throne is upheld by righteousness.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 29, 'The glory of youths is their strength,  
    but the beauty of the aged is their gray hair.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 20, 30, 'Blows that wound cleanse away evil;  
    beatings make clean the innermost parts.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 21, 1, 'The king"s heart is a stream of water in the hand of the LORD;  
    he turns it wherever he will.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 2, 'All deeds are right in the sight of the doer,  
    but the LORD weighs the heart.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 3, 'To do righteousness and justice  
    is more acceptable to the LORD than sacrifice.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 4, 'Haughty eyes and a proud heart--  
    the lamp of the wicked--are sin.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 5, 'The plans of the diligent lead surely to abundance,  
    but everyone who is hasty comes only to want.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 6, 'The getting of treasures by a lying tongue  
    is a fleeting vapor and a snare of death.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 7, 'The violence of the wicked will sweep them away,  
    because they refuse to do what is just.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 8, 'The way of the guilty is crooked,  
    but the conduct of the pure is right.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 9, 'It is better to live in a corner of the housetop  
    than in a house shared with a contentious wife.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 10, 'The souls of the wicked desire evil;  
    their neighbors find no mercy in their eyes.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 11, 'When a scoffer is punished, the simple become wiser;  
    when the wise are instructed, they increase in knowledge.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 12, 'The Righteous One observes the house of the wicked;  
    he casts the wicked down to ruin.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 13, 'If you close your ear to the cry of the poor,  
    you will cry out and not be heard.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 14, 'A gift in secret averts anger;  
    and a concealed bribe in the bosom, strong wrath.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 15, 'When justice is done, it is a joy to the righteous,  
    but dismay to evildoers.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 16, 'Whoever wanders from the way of understanding  
    will rest in the assembly of the dead.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 17, 'Whoever loves pleasure will suffer want;  
    whoever loves wine and oil will not be rich.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 18, 'The wicked is a ransom for the righteous,  
    and the faithless for the upright.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 19, 'It is better to live in a desert land  
    than with a contentious and fretful wife.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 20, 'Precious treasure remains in the house of the wise,  
    but the fool devours it.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 21, 'Whoever pursues righteousness and kindness  
    will find life and honor.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 22, 'One wise person went up against a city of warriors  
    and brought down the stronghold in which they trusted.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 23, 'To watch over mouth and tongue  
    is to keep out of trouble.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 24, 'The proud, haughty person, named "Scoffer,"  
    acts with arrogant pride.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 25, 'The craving of the lazy person is fatal,  
    for lazy hands refuse to labor.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 26, 'All day long the wicked covet,  
    but the righteous give and do not hold back.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 27, 'The sacrifice of the wicked is an abomination;  
    how much more when brought with evil intent.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 28, 'A false witness will perish,  
    but a good listener will testify successfully.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 29, 'The wicked put on a bold face,  
    but the upright give thought to their ways.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 30, 'No wisdom, no understanding, no counsel,  
    can avail against the LORD.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 21, 31, 'The horse is made ready for the day of battle,  
    but the victory belongs to the LORD.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 22, 1, 'A good name is to be chosen rather than great riches,  
    and favor is better than silver or gold.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 2, 'The rich and the poor have this in common:  
    the LORD is the maker of them all.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 3, 'The clever see danger and hide;  
    but the simple go on, and suffer for it.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 4, 'The reward for humility and fear of the LORD  
    is riches and honor and life.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 5, 'Thorns and snares are in the way of the perverse;  
    the cautious will keep far from them.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 6, 'Train children in the right way,  
    and when old, they will not stray.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 7, 'The rich rule over the poor,  
    and the borrower is the slave of the lender.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 8, 'Whoever sows injustice will reap calamity,  
    and the rod of anger will fail.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 9, 'Those who are generous are blessed,  
    for they share their bread with the poor.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 10, 'Drive out a scoffer, and strife goes out;  
    quarreling and abuse will cease.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 11, 'Those who love a pure heart and are gracious in speech  
    will have the king as a friend.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 12, 'The eyes of the LORD keep watch over knowledge,  
    but he overthrows the words of the faithless.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 13, 'The lazy person says, "There is a lion outside!  
    I shall be killed in the streets!"', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 14, 'The mouth of a loose woman is a deep pit;  
    he with whom the LORD is angry falls into it.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 15, 'Folly is bound up in the heart of a boy,  
    but the rod of discipline drives it far away.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 16, 'Oppressing the poor in order to enrich oneself,  
    and giving to the rich, will lead only to loss.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 17, 'The words of the wise:
Incline your ear and hear my words,  
    and apply your mind to my teaching;', 'en', 'NRSV-CE', 'Sayings of the Wise'),
(20, 'Ams', 'Proverbs', 22, 18, 'for it will be pleasant if you keep them within you,  
    if all of them are ready on your lips.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 19, 'So that your trust may be in the LORD,  
    I have made them known to you today--yes, to you.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 20, 'Have I not written for you thirty sayings  
    of admonition and knowledge,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 21, 'to show you what is right and true,  
    so that you may give a true answer to those who sent you?', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 22, 'Do not rob the poor because they are poor,  
    or crush the afflicted at the gate;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 23, 'for the LORD pleads their cause  
    and despoils of life those who despoil them.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 24, 'Make no friends with those given to anger,  
    and do not associate with hotheads,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 25, 'or you may learn their ways  
    and entangle yourself in a snare.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 26, 'Do not be one of those who give pledges,  
    who become surety for debts.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 27, 'If you have nothing with which to pay,  
    why should your bed be taken from under you?', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 28, 'Do not remove the ancient landmark  
    that your ancestors set up.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 22, 29, 'Do you see those who are skillful in their work?  
    They will serve kings;  
    they will not serve common people.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 23, 1, 'When you sit down to eat with a ruler,  
    observe carefully what is before you,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 2, 'and put a knife to your throat  
    if you have a big appetite.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 3, 'Do not desire the ruler"s delicacies,  
    for they are deceptive food.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 4, 'Do not wear yourself out to get rich;  
    be wise enough to desist.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 5, 'When your eyes light upon it, it is gone;  
    for suddenly it takes wings to itself,  
    flying like an eagle toward heaven.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 6, 'Do not eat the bread of the stingy;  
    do not desire their delicacies;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 7, 'for like a hair in the throat, so are they.  
    "Eat and drink!" they say to you;  
    but they do not mean it.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 8, 'You will vomit up the little you have eaten,  
    and you will waste your pleasant words.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 9, 'Do not speak in the hearing of a fool,  
    who will only despise the wisdom of your words.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 10, 'Do not remove an ancient landmark  
    or encroach on the fields of orphans,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 11, 'for their redeemer is strong;  
    he will plead their cause against you.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 12, 'Apply your mind to instruction  
    and your ear to words of knowledge.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 13, 'Do not withhold discipline from your children;  
    if you beat them with a rod, they will not die.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 14, 'If you beat them with the rod,  
    you will save their lives from Sheol.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 15, 'My child, if your heart is wise,  
    my heart too will be glad.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 16, 'My soul will rejoice  
    when your lips speak what is right.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 17, 'Do not let your heart envy sinners,  
    but always continue in the fear of the LORD.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 18, 'Surely there is a future,  
    and your hope will not be cut off.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 19, 'Hear, my child, and be wise,  
    and direct your mind in the way.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 20, 'Do not be among winebibbers,  
    or among gluttonous eaters of meat;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 21, 'for the drunkard and the glutton will come to poverty,  
    and drowsiness will clothe them with rags.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 22, 'Listen to your father who begot you,  
    and do not despise your mother when she is old.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 23, 'Buy truth, and do not sell it;  
    buy wisdom, instruction, and understanding.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 24, 'The father of the righteous will greatly rejoice;  
    he who begets a wise son will be glad in him.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 25, 'Let your father and mother be glad;  
    let her who bore you rejoice.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 26, 'My child, give me your heart,  
    and let your eyes observe my ways.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 27, 'For a prostitute is a deep pit;  
    an adulteress is a narrow well.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 28, 'She lies in wait like a robber  
    and increases the number of the faithless.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 29, 'Who has woe? Who has sorrow?  
    Who has strife? Who has complaining?  
Who has wounds without cause?  
    Who has redness of eyes?', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 30, 'Those who linger late over wine,  
    those who keep trying mixed wines.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 31, 'Do not look at wine when it is red,  
    when it sparkles in the cup  
    and goes down smoothly.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 32, 'At the last it bites like a serpent,  
    and stings like an adder.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 33, 'Your eyes will see strange things,  
    and your mind utter perverse things.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 34, 'You will be like one who lies down in the midst of the sea,  
    like one who lies on the top of a mast.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 23, 35, '"They struck me," you will say, "but I was not hurt;  
    they beat me, but I did not feel it.  
When shall I awake?  
    I will seek another drink."', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 24, 1, 'Do not envy the wicked,  
    nor desire to be with them;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 2, 'for their minds devise violence,  
    and their lips talk of mischief.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 3, 'By wisdom a house is built,  
    and by understanding it is established;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 4, 'by knowledge the rooms are filled  
    with all precious and pleasant riches.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 5, 'Wise warriors are mightier than strong ones,  
    and those who have knowledge than those who have strength;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 6, 'for by wise guidance you can wage your war,  
    and in abundance of counselors there is victory.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 7, 'Wisdom is too high for fools;  
    in the gate they do not open their mouths.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 8, 'Whoever plans to do evil  
    will be called a mischief-maker.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 9, 'The devising of folly is sin,  
    and the scoffer is an abomination to all.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 10, 'If you faint in the day of adversity,  
    your strength being small;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 11, 'if you hold back from rescuing those taken away to death,  
    those who go staggering to the slaughter;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 12, 'if you say, "Look, we did not know this"--  
    does not he who weighs the heart perceive it?  
Does not he who keeps watch over your soul know it?  
    And will he not repay all according to their deeds?', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 13, 'My child, eat honey, for it is good,  
    and the drippings of the honeycomb are sweet to your taste.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 14, 'Know that wisdom is such to your soul;  
    if you find it, you will find a future,  
    and your hope will not be cut off.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 15, 'Do not lie in wait like an outlaw against the home of the righteous;  
    do no violence to the place where the righteous live;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 16, 'for though they fall seven times, they will rise again;  
    but the wicked are overthrown by calamity.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 17, 'Do not rejoice when your enemies fall,  
    and do not let your heart be glad when they stumble,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 18, 'or else the LORD will see it and be displeased,  
    and turn away his anger from them.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 19, 'Do not fret because of evildoers.  
    Do not envy the wicked;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 20, 'for the evil have no future;  
    the lamp of the wicked will go out.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 21, 'My child, fear the LORD and the king,  
    and do not disobey either of them;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 22, 'for disaster comes from them suddenly,  
    and who knows the ruin that both can bring?', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 23, 'These also are sayings of the wise:
Partiality in judging is not good.', 'en', 'NRSV-CE', 'Further Sayings of the Wise'),
(20, 'Ams', 'Proverbs', 24, 24, 'Whoever says to the wicked, "You are innocent,"  
    will be cursed by peoples, abhorred by nations;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 25, 'but those who rebuke the wicked will have delight,  
    and a good blessing will come upon them.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 26, 'One who gives an honest answer  
    gives a kiss on the lips.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 27, 'Prepare your work outside,  
    get everything ready for you in the field;  
    and after that build your house.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 28, 'Do not be a witness against your neighbor without cause,  
    and do not deceive with your lips.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 29, 'Do not say, "I will do to others as they have done to me;  
    I will pay them back for what they have done."', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 30, 'I passed by the field of one who was lazy,  
    by the vineyard of a stupid person;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 31, 'and see, it was all overgrown with thorns;  
    the ground was covered with nettles,  
    and its stone wall was broken down.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 32, 'Then I saw and considered it;  
    I looked and received instruction.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 33, 'A little sleep, a little slumber,  
    a little folding of the hands to rest,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 24, 34, 'and poverty will come upon you like a robber,  
    and want, like an armed warrior.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 25, 1, 'These are other proverbs of Solomon that the officials of King Hezekiah of Judah copied.', 'en', 'NRSV-CE', 'Further Wise Sayings of Solomon'),
(20, 'Ams', 'Proverbs', 25, 2, 'It is the glory of God to conceal things,  
    but the glory of kings is to search things out.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 25, 3, 'Like the heavens for height, like the earth for depth,  
    so the mind of kings is unsearchable.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 25, 4, 'Take away the dross from the silver,  
    and the smith has material for a vessel;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 25, 5, 'take away the wicked from the presence of the king,  
    and his throne will be established in righteousness.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 25, 6, 'Do not put yourself forward in the king"s presence  
    or stand in the place of the great;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 25, 7, 'for it is better to be told, "Come up here,"  
    than to be put lower in the presence of a noble.
What your eyes have seen', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 25, 8, 'do not hastily bring into court;  
for what will you do in the end,  
    when your neighbor puts you to shame?', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 25, 9, 'Argue your case with your neighbor directly,  
    and do not disclose another"s secret;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 25, 10, 'or else someone who hears you will bring shame upon you,  
    and your ill repute will have no end.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 25, 11, 'A word fitly spoken  
    is like apples of gold in a setting of silver.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 25, 12, 'Like a gold ring or an ornament of gold  
    is a wise rebuke to a listening ear.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 25, 13, 'Like the cold of snow in the time of harvest  
    are faithful messengers to those who send them;  
    they refresh the spirit of their masters.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 25, 14, 'Like clouds and wind without rain  
    is one who boasts of a gift never given.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 25, 15, 'With patience a ruler may be persuaded,  
    and a soft tongue can break bones.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 25, 16, 'If you have found honey, eat only enough for you,  
    or else, having too much, you will vomit it.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 25, 17, 'Let your foot be seldom in your neighbor"s house,  
    otherwise the neighbor will become weary of you and hate you.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 25, 18, 'Like a war club, a sword, or a sharp arrow  
    is one who bears false witness against a neighbor.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 25, 19, 'Like a bad tooth or a lame foot  
    is trust in a faithless person in time of trouble.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 25, 20, 'Like vinegar on a wound  
    is one who sings songs to a heavy heart.  
Like a moth in clothing or a worm in wood,  
    sorrow gnaws at the human heart.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 25, 21, 'If your enemies are hungry, give them bread to eat;  
    and if they are thirsty, give them water to drink;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 25, 22, 'for you will heap coals of fire on their heads,  
    and the LORD will reward you.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 25, 23, 'The north wind produces rain,  
    and a backbiting tongue, angry looks.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 25, 24, 'It is better to live in a corner of the housetop  
    than in a house shared with a contentious wife.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 25, 25, 'Like cold water to a thirsty soul,  
    so is good news from a far country.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 25, 26, 'Like a muddied spring or a polluted fountain  
    are the righteous who give way before the wicked.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 25, 27, 'It is not good to eat much honey,  
    or to seek honor on top of honor.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 25, 28, 'Like a city breached, without walls,  
    is one who lacks self-control.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 26, 1, 'Like snow in summer or rain in harvest,  
    so honor is not fitting for a fool.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 2, 'Like a sparrow in its flitting, like a swallow in its flying,  
    an undeserved curse goes nowhere.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 3, 'A whip for the horse, a bridle for the donkey,  
    and a rod for the back of fools.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 4, 'Do not answer fools according to their folly,  
    or you will be a fool yourself.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 5, 'Answer fools according to their folly,  
    or they will be wise in their own eyes.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 6, 'It is like cutting off one"s foot and drinking down violence,  
    to send a message by a fool.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 7, 'The legs of a disabled person hang limp;  
    so does a proverb in the mouth of a fool.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 8, 'It is like binding a stone in a sling  
    to give honor to a fool.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 9, 'Like a thornbush brandished by the hand of a drunkard  
    is a proverb in the mouth of a fool.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 10, 'Like an archer who wounds everybody  
    is one who hires a passing fool or drunkard.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 11, 'Like a dog that returns to its vomit  
    is a fool who reverts to his folly.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 12, 'Do you see persons wise in their own eyes?  
    There is more hope for fools than for them.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 13, 'The lazy person says, "There is a lion in the road!  
    There is a lion in the streets!"', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 14, 'As a door turns on its hinges,  
    so does a lazy person in bed.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 15, 'The lazy person buries a hand in the dish,  
    and is too tired to bring it back to the mouth.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 16, 'The lazy person is wiser in self-esteem  
    than seven who can answer discreetly.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 17, 'Like somebody who takes a passing dog by the ears  
    is one who meddles in the quarrel of another.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 18, 'Like a maniac who shoots deadly firebrands and arrows,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 19, 'so is one who deceives a neighbor  
    and says, "I am only joking!"', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 20, 'For lack of wood the fire goes out,  
    and where there is no whisperer, quarreling ceases.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 21, 'As charcoal is to hot embers and wood to fire,  
    so is a quarrelsome person for kindling strife.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 22, 'The words of a whisperer are like delicious morsels;  
    they go down into the inner parts of the body.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 23, 'Like the glaze covering an earthen vessel  
    are smooth lips with an evil heart.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 24, 'An enemy dissembles in speaking  
    while harboring deceit within;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 25, 'when an enemy speaks graciously, do not believe it,  
    for there are seven abominations concealed within;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 26, 'though hatred is covered with guile,  
    the enemy"s wickedness will be exposed in the assembly.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 27, 'Whoever digs a pit will fall into it,  
    and a stone will come back on the one who starts it rolling.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 26, 28, 'A lying tongue hates its victims,  
    and a flattering mouth works ruin.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 27, 1, 'Do not boast about tomorrow,  
    for you do not know what a day may bring.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 27, 2, 'Let another praise you, and not your own mouth--  
    a stranger, and not your own lips.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 27, 3, 'A stone is heavy, and sand is weighty,  
    but a fool"s provocation is heavier than both.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 27, 4, 'Wrath is cruel, anger is overwhelming,  
    but who is able to stand before jealousy?', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 27, 5, 'Better is open rebuke  
    than hidden love.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 27, 6, 'Well meant are the wounds a friend inflicts,  
    but profuse are the kisses of an enemy.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 27, 7, 'The sated appetite spurns honey,  
    but to a ravenous appetite even the bitter is sweet.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 27, 8, 'Like a bird that strays from its nest  
    is one who strays from home.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 27, 9, 'Perfume and incense make the heart glad,  
    but the soul is torn by trouble.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 27, 10, 'Do not forsake your friend or the friend of your parent;  
    do not go to the house of your kindred in the day of your calamity.  
Better is a neighbor who is nearby  
    than kindred who are far away.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 27, 11, 'Be wise, my child, and make my heart glad,  
    so that I may answer whoever reproaches me.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 27, 12, 'The clever see danger and hide;  
    but the simple go on, and suffer for it.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 27, 13, 'Take the garment of one who has given surety for a stranger;  
    seize the pledge given as surety for foreigners.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 27, 14, 'Whoever blesses a neighbor with a loud voice,  
    rising early in the morning,  
    will be counted as cursing.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 27, 15, 'A continual dripping on a rainy day  
    and a contentious wife are alike;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 27, 16, 'to restrain her is to restrain the wind  
    or to grasp oil in the right hand.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 27, 17, 'Iron sharpens iron,  
    and one person sharpens the wits of another.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 27, 18, 'Anyone who tends a fig tree will eat its fruit,  
    and anyone who takes care of a master will be honored.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 27, 19, 'Just as water reflects the face,  
    so one human heart reflects another.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 27, 20, 'Sheol and Abaddon are never satisfied,  
    and human eyes are never satisfied.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 27, 21, 'The crucible is for silver, and the furnace is for gold,  
    so a person is tested by being praised.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 27, 22, 'Crush a fool in a mortar with a pestle  
    along with crushed grain,  
    but the folly will not be driven out.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 27, 23, 'Know well the condition of your flocks,  
    and give attention to your herds;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 27, 24, 'for riches do not last forever,  
    nor a crown for all generations.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 27, 25, 'When the grass is gone, and new growth appears,  
    and the herbage of the mountains is gathered,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 27, 26, 'the lambs will provide your clothing,  
    and the goats the price of a field;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 27, 27, 'there will be enough goats" milk for your food,  
    for the food of your household  
    and nourishment for your servant-girls.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 28, 1, 'The wicked flee when no one pursues,  
    but the righteous are as bold as a lion.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 2, 'When a land rebels  
    it has many rulers;  
but with an intelligent ruler  
    there is lasting order.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 3, 'A ruler who oppresses the poor  
    is a beating rain that leaves no food.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 4, 'Those who forsake the law praise the wicked,  
    but those who keep the law struggle against them.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 5, 'The evil do not understand justice,  
    but those who seek the LORD understand it completely.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 6, 'Better to be poor and walk in integrity  
    than to be crooked in one"s ways even though rich.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 7, 'Those who keep the law are wise children,  
    but companions of gluttons shame their parents.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 8, 'One who augments wealth by exorbitant interest  
    gathers it for another who is kind to the poor.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 9, 'When one will not listen to the law,  
    even one"s prayers are an abomination.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 10, 'Those who mislead the upright into evil ways  
    will fall into pits of their own making,  
    but the blameless will have a goodly inheritance.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 11, 'The rich is wise in self-esteem,  
    but an intelligent poor person sees through the pose.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 12, 'When the righteous triumph, there is great glory,  
    but when the wicked prevail, people go into hiding.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 13, 'No one who conceals transgressions will prosper,  
    but one who confesses and forsakes them will obtain mercy.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 14, 'Happy is the one who is never without fear,  
    but one who is hard-hearted will fall into calamity.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 15, 'Like a roaring lion or a charging bear  
    is a wicked ruler over a poor people.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 16, 'A ruler who lacks understanding is a cruel oppressor;  
    but one who hates unjust gain will enjoy a long life.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 17, 'If someone is burdened with the blood of another,  
    let that killer be a fugitive until death;  
    let no one offer assistance.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 18, 'One who walks in integrity will be safe,  
    but whoever follows crooked ways will fall into the Pit.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 19, 'Anyone who tills the land will have plenty of bread,  
    but one who follows worthless pursuits will have plenty of poverty.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 20, 'The faithful will abound with blessings,  
    but one who is in a hurry to be rich will not go unpunished.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 21, 'To show partiality is not good--  
    yet for a piece of bread a person may do wrong.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 22, 'The miser is in a hurry to get rich  
    and does not know that loss is sure to come.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 23, 'Whoever rebukes a person will afterward find more favor  
    than one who flatters with the tongue.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 24, 'Anyone who robs father or mother  
    and says, "That is no crime,"  
    is partner to a thug.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 25, 'The greedy person stirs up strife,  
    but whoever trusts in the LORD will be enriched.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 26, 'Those who trust in their own wits are fools;  
    but those who walk in wisdom come through safely.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 27, 'Whoever gives to the poor will lack nothing,  
    but one who turns a blind eye will get many a curse.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 28, 28, 'When the wicked prevail, people go into hiding;  
    but when they perish, the righteous increase.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 29, 1, 'One who is often reproved, yet remains stubborn,  
    will suddenly be broken beyond healing.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 29, 2, 'When the righteous are in authority, the people rejoice;  
    but when the wicked rule, the people groan.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 29, 3, 'A child who loves wisdom makes a parent glad,  
    but to keep company with prostitutes is to squander one"s substance.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 29, 4, 'By justice a king gives stability to the land,  
    but one who makes heavy exactions ruins it.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 29, 5, 'Whoever flatters a neighbor  
    is spreading a net for the neighbor"s feet.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 29, 6, 'In the transgression of the evil there is a snare,  
    but the righteous sing and rejoice.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 29, 7, 'The righteous know the rights of the poor;  
    the wicked have no such understanding.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 29, 8, 'Scoffers set a city aflame,  
    but the wise turn away wrath.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 29, 9, 'If the wise go to law with fools,  
    there is ranting and ridicule without relief.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 29, 10, 'The bloodthirsty hate the blameless,  
    and they seek the life of the upright.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 29, 11, 'A fool gives full vent to anger,  
    but the wise quietly holds it back.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 29, 12, 'If a ruler listens to falsehood,  
    all his officials will be wicked.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 29, 13, 'The poor and the oppressor have this in common:  
    the LORD gives light to the eyes of both.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 29, 14, 'If a king judges the poor with equity,  
    his throne will be established forever.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 29, 15, 'The rod and reproof give wisdom,  
    but a mother is disgraced by a neglected child.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 29, 16, 'When the wicked are in authority, transgression increases,  
    but the righteous will look upon their downfall.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 29, 17, 'Discipline your children, and they will give you rest;  
    they will give delight to your heart.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 29, 18, 'Where there is no prophecy, the people cast off restraint,  
    but happy are those who keep the law.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 29, 19, 'By mere words servants are not disciplined,  
    for though they understand, they will not give heed.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 29, 20, 'Do you see someone who is hasty in speech?  
    There is more hope for a fool than for anyone like that.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 29, 21, 'A slave pampered from childhood  
    will come to a bad end.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 29, 22, 'One given to anger stirs up strife,  
    and the hothead causes much transgression.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 29, 23, 'A person"s pride will bring humiliation,  
    but one who is lowly in spirit will obtain honor.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 29, 24, 'To be a partner of a thief is to hate one"s own life;  
    one hears the victim"s curse, but discloses nothing.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 29, 25, 'The fear of others lays a snare,  
    but one who trusts in the LORD is secure.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 29, 26, 'Many seek the favor of a ruler,  
    but it is from the LORD that one gets justice.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 29, 27, 'The unjust are an abomination to the righteous,  
    but the upright are an abomination to the wicked.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 30, 1, 'The words of Agur son of Jakeh. An oracle.
Thus says the man: I am weary, O God,  
    I am weary, O God. How can I prevail?', 'en', 'NRSV-CE', 'Sayings of Agur'),
(20, 'Ams', 'Proverbs', 30, 2, 'Surely I am too stupid to be human;  
    I do not have human understanding.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 3, 'I have not learned wisdom,  
    nor have I knowledge of the holy ones.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 4, 'Who has ascended to heaven and come down?  
    Who has gathered the wind in the hollow of the hand?  
Who has wrapped up the waters in a garment?  
    Who has established all the ends of the earth?  
What is the person"s name?  
    And what is the name of the person"s child?  
    Surely you know!', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 5, 'Every word of God proves true;  
    he is a shield to those who take refuge in him.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 6, 'Do not add to his words,  
    or else he will rebuke you, and you will be found a liar.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 7, 'Two things I ask of you;  
    do not deny them to me before I die:', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 8, 'Remove far from me falsehood and lying;  
    give me neither poverty nor riches;  
    feed me with the food that I need,', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 9, 'or I shall be full, and deny you,  
    and say, "Who is the LORD?"  
or I shall be poor, and steal,  
    and profane the name of my God.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 10, 'Do not slander a servant to a master,  
    or the servant will curse you, and you will be held guilty.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 11, 'There are those who curse their fathers  
    and do not bless their mothers.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 12, 'There are those who are pure in their own eyes  
    yet are not cleansed of their filthiness.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 13, 'There are those--how lofty are their eyes,  
    how high their eyelids lift!--', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 14, 'there are those whose teeth are swords,  
    whose teeth are knives,  
to devour the poor from off the earth,  
    the needy from among mortals.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 15, 'The leech has two daughters;  
    "Give, give," they cry.  
Three things are never satisfied;  
    four never say, "Enough":', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 16, 'Sheol, the barren womb,  
    the earth ever thirsty for water,  
    and the fire that never says, "Enough."', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 17, 'The eye that mocks a father  
    and scorns to obey a mother  
will be pecked out by the ravens of the valley  
    and eaten by the vultures.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 18, 'Three things are too wonderful for me;  
    four I do not understand:', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 19, 'the way of an eagle in the sky,  
    the way of a snake on a rock,  
the way of a ship on the high seas,  
    and the way of a man with a girl.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 20, 'This is the way of an adulteress:  
    she eats, and wipes her mouth,  
    and says, "I have done no wrong."', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 21, 'Under three things the earth trembles;  
    under four it cannot bear up:', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 22, 'a slave when he becomes king,  
    and a fool when glutted with food;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 23, 'an unloved woman when she gets a husband,  
    and a maid when she succeeds her mistress.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 24, 'Four things on earth are small,  
    yet they are exceedingly wise:', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 25, 'the ants are a people without strength,  
    yet they provide their food in the summer;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 26, 'the badgers are a people without power,  
    yet they make their homes in the rocks;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 27, 'the locusts have no king,  
    yet all of them march in rank;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 28, 'the lizard can be grasped in the hand,  
    yet it is found in kings" palaces.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 29, 'Three things are stately in their stride;  
    four are stately in their gait:', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 30, 'the lion, which is mightiest among wild animals  
    and does not turn back before any;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 31, 'the strutting rooster, the he-goat,  
    and a king striding before his people.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 32, 'If you have been foolish, exalting yourself,  
    or if you have been devising evil,  
    put your hand on your mouth.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 30, 33, 'For as pressing milk produces curds,  
    and pressing the nose produces blood,  
    so pressing anger produces strife.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(20, 'Ams', 'Proverbs', 31, 1, 'The words of King Lemuel. An oracle that his mother taught him:', 'en', 'NRSV-CE', 'The Teaching of King Lemuel"s Mother'),
(20, 'Ams', 'Proverbs', 31, 2, 'No, my son! No, son of my womb!  
    No, son of my vows!', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 3, 'Do not give your strength to women,  
    your ways to those who destroy kings.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 4, 'It is not for kings, O Lemuel,  
    it is not for kings to drink wine,  
    or for rulers to desire strong drink;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 5, 'or else they will drink and forget what has been decreed,  
    and will pervert the rights of all the afflicted.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 6, 'Give strong drink to one who is perishing,  
    and wine to those in bitter distress;', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 7, 'let them drink and forget their poverty,  
    and remember their misery no more.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 8, 'Speak out for those who cannot speak,  
    for the rights of all the destitute.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 9, 'Speak out, judge righteously,  
    defend the rights of the poor and needy.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 10, 'A capable wife who can find?  
    She is far more precious than jewels.', 'en', 'NRSV-CE', 'Ode to a Capable Wife'),
(20, 'Ams', 'Proverbs', 31, 11, 'The heart of her husband trusts in her,  
    and he will have no lack of gain.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 12, 'She does him good, and not harm,  
    all the days of her life.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 13, 'She seeks wool and flax,  
    and works with willing hands.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 14, 'She is like the ships of the merchant,  
    she brings her food from far away.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 15, 'She rises while it is still night  
    and provides food for her household  
    and tasks for her servant-girls.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 16, 'She considers a field and buys it;  
    with the fruit of her hands she plants a vineyard.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 17, 'She girds herself with strength,  
    and makes her arms strong.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 18, 'She perceives that her merchandise is profitable.  
    Her lamp does not go out at night.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 19, 'She puts her hands to the distaff,  
    and her hands hold the spindle.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 20, 'She opens her hand to the poor,  
    and reaches out her hands to the needy.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 21, 'She is not afraid for her household when it snows,  
    for all her household are clothed in crimson.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 22, 'She makes herself coverings;  
    her clothing is fine linen and purple.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 23, 'Her husband is known in the city gates,  
    taking his seat among the elders of the land.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 24, 'She makes linen garments and sells them;  
    she supplies the merchant with sashes.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 25, 'Strength and dignity are her clothing,  
    and she laughs at the time to come.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 26, 'She opens her mouth with wisdom,  
    and the teaching of kindness is on her tongue.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 27, 'She looks well to the ways of her household,  
    and does not eat the bread of idleness.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 28, 'Her children rise up and call her happy;  
    her husband too, and he praises her:', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 29, '"Many women have done excellently,  
    but you surpass them all."', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 30, 'Charm is deceitful, and beauty is vain,  
    but a woman who fears the LORD is to be praised.', 'en', 'NRSV-CE', NULL),
(20, 'Ams', 'Proverbs', 31, 31, 'Give her a share in the fruit of her hands,  
    and let her works praise her in the city gates.', 'en', 'NRSV-CE', NULL);

